		public static ZipStorer Create(Stream zipStream, string fileComment)
		{
			return new ZipStorer
			{
				comment = fileComment,
				zipFileStream = zipStream,
				access = FileAccess.Write
			};
		}

		public static ZipStorer Open(Stream stream, FileAccess access)
		{
			if (!stream.CanSeek && access != FileAccess.Read)
			{
				throw new InvalidOperationException("Stream cannot seek");
			}
			ZipStorer zipStorer = new ZipStorer();
			zipStorer.zipFileStream = stream;
			zipStorer.access = access;
			if (zipStorer.ReadFileInfo())
			{
				return zipStorer;
			}
			throw new InvalidDataException();
		}

		public void AddFile(CompressionMethod compressionMethod, string sourceFile, string fileNameInZip, string fileEntryComment)
		{
			if (access == FileAccess.Read)
			{
				throw new InvalidOperationException("Writing is not allowed");
			}
			using FileStream sourceStream = new FileStream(sourceFile, FileMode.Open, FileAccess.Read);
			AddStream(compressionMethod, sourceStream, fileNameInZip, File.GetLastWriteTime(sourceFile), fileEntryComment);
		}

		public void AddStream(CompressionMethod compressionMethod, Stream sourceStream, string fileNameInZip, DateTime modificationTimeStamp, string fileEntryComment)
		{
			if (access == FileAccess.Read)
			{
				throw new InvalidOperationException("Writing is not allowed");
			}
			ZipFileEntry zipFileEntry = default(ZipFileEntry);
			zipFileEntry.Method = compressionMethod;
			zipFileEntry.EncodeUTF8 = EncodeUtf8;
			zipFileEntry.FilenameInZip = NormalizeFileName(fileNameInZip);
			zipFileEntry.Comment = ((fileEntryComment == null) ? string.Empty : fileEntryComment);
			zipFileEntry.Crc32 = 0u;
			zipFileEntry.HeaderOffset = (uint)zipFileStream.Position;
			zipFileEntry.ModifyTime = modificationTimeStamp;
			WriteLocalHeader(ref zipFileEntry);
			zipFileEntry.FileOffset = (uint)zipFileStream.Position;
			Store(ref zipFileEntry, sourceStream);
			sourceStream.Close();
			UpdateCrcAndSizes(ref zipFileEntry);
			files.Add(zipFileEntry);
		}

		public void Close()
		{
			if (access != FileAccess.Read)
			{
				uint offset = (uint)zipFileStream.Position;
				uint num = 0u;
				if (centralDirectoryImage != null)
				{
					zipFileStream.Write(centralDirectoryImage, 0, centralDirectoryImage.Length);
				}
				for (int i = 0; i < files.Count; i++)
				{
					long position = zipFileStream.Position;
					WriteCentralDirRecord(files[i]);
					num += (uint)(int)(zipFileStream.Position - position);
				}
				if (centralDirectoryImage != null)
				{
					WriteEndRecord(num + (uint)centralDirectoryImage.Length, offset);
				}
				else
				{
					WriteEndRecord(num, offset);
				}
			}
			if (zipFileStream != null)
			{
				zipFileStream.Flush();
				zipFileStream.Dispose();
				zipFileStream = null;
			}
		}

		public List<ZipFileEntry> ReadCentralDirectory()
		{
			if (centralDirectoryImage == null)
			{
				throw new InvalidOperationException("Central directory currently does not exist");
			}
			List<ZipFileEntry> list = new List<ZipFileEntry>();
			ushort num2;
			ushort num3;
			ushort num4;
			for (int i = 0; i < centralDirectoryImage.Length && BitConverter.ToUInt32(centralDirectoryImage, i) == 33639248; i += 46 + num2 + num3 + num4)
			{
				bool num = (BitConverter.ToUInt16(centralDirectoryImage, i + 8) & 0x800) != 0;
				ushort method = BitConverter.ToUInt16(centralDirectoryImage, i + 10);
				uint dosTime = BitConverter.ToUInt32(centralDirectoryImage, i + 12);
				uint crc = BitConverter.ToUInt32(centralDirectoryImage, i + 16);
				uint compressedSize = BitConverter.ToUInt32(centralDirectoryImage, i + 20);
				uint fileSize = BitConverter.ToUInt32(centralDirectoryImage, i + 24);
				num2 = BitConverter.ToUInt16(centralDirectoryImage, i + 28);
				num3 = BitConverter.ToUInt16(centralDirectoryImage, i + 30);
				num4 = BitConverter.ToUInt16(centralDirectoryImage, i + 32);
				uint headerOffset = BitConverter.ToUInt32(centralDirectoryImage, i + 42);
				uint headerSize = (uint)(46 + num2 + num3 + num4);
				Encoding encoding = (num ? Encoding.UTF8 : defaultEncoding);
				ZipFileEntry item = default(ZipFileEntry);
				item.Method = (CompressionMethod)method;
				item.FilenameInZip = encoding.GetString(centralDirectoryImage, i + 46, num2);
				item.FileOffset = GetFileOffset(headerOffset);
				item.FileSize = fileSize;
				item.CompressedSize = compressedSize;
				item.HeaderOffset = headerOffset;
				item.HeaderSize = headerSize;
				item.Crc32 = crc;
				item.ModifyTime = DosTimeToDateTime(dosTime);
				if (num4 > 0)
				{
					item.Comment = encoding.GetString(centralDirectoryImage, i + 46 + num2 + num3, num4);
				}
				list.Add(item);
			}
			return list;
		}

		public bool ExtractFile(ZipFileEntry zipFileEntry, string destinationFileName)
		{
			string directoryName = Path.GetDirectoryName(destinationFileName);
			if (!Directory.Exists(directoryName))
			{
				Directory.CreateDirectory(directoryName);
			}
			if (Directory.Exists(destinationFileName))
			{
				return true;
			}
			bool result = false;
			using (Stream destinationStream = new FileStream(destinationFileName, FileMode.Create, FileAccess.Write))
			{
				result = ExtractFile(zipFileEntry, destinationStream);
			}
			File.SetCreationTime(destinationFileName, zipFileEntry.ModifyTime);
			File.SetLastWriteTime(destinationFileName, zipFileEntry.ModifyTime);
			return result;
		}

		public bool ExtractFile(ZipFileEntry zipFileEntry, Stream destinationStream)
		{
			if (!destinationStream.CanWrite)
			{
				throw new InvalidOperationException("Stream cannot be written");
			}
			byte[] array = new byte[4];
			zipFileStream.Seek(zipFileEntry.HeaderOffset, SeekOrigin.Begin);
			zipFileStream.Read(array, 0, 4);
			if (BitConverter.ToUInt32(array, 0) != 67324752)
			{
				return false;
			}
			Stream stream;
			if (zipFileEntry.Method == CompressionMethod.Store)
			{
				stream = zipFileStream;
			}
			else
			{
				if (zipFileEntry.Method != CompressionMethod.Deflate)
				{
					return false;
				}
				stream = new DeflateStream(zipFileStream, CompressionMode.Decompress, leaveOpen: true);
			}
			byte[] array2 = new byte[16384];
			zipFileStream.Seek(zipFileEntry.FileOffset, SeekOrigin.Begin);
			uint num = zipFileEntry.FileSize;
			while (num != 0)
			{
				int num2 = stream.Read(array2, 0, (int)Math.Min(num, array2.Length));
				destinationStream.Write(array2, 0, num2);
				num -= (uint)num2;
			}
			destinationStream.Flush();
			if (zipFileEntry.Method == CompressionMethod.Deflate)
			{
				stream.Dispose();
			}
			return true;
		}

		public void Dispose()
		{
			Close();
		}

		private static uint[] GenerateCrc32Table()
		{
			uint[] array = new uint[256];
			for (int i = 0; i < array.Length; i++)
			{
				uint num = (uint)i;
				for (int j = 0; j < 8; j++)
				{
					num = (((num & 1) == 0) ? (num >> 1) : (0xEDB88320u ^ (num >> 1)));
				}
				array[i] = num;
			}
			return array;
		}

		private static uint DateTimeToDosTime(DateTime dateTime)
		{
			return (uint)((dateTime.Second / 2) | (dateTime.Minute << 5) | (dateTime.Hour << 11) | (dateTime.Day << 16) | (dateTime.Month << 21) | (dateTime.Year - 1980 << 25));
		}

		private static DateTime DosTimeToDateTime(uint dosTime)
		{
			return new DateTime((int)((dosTime >> 25) + 1980), (int)((dosTime >> 21) & 0xF), (int)((dosTime >> 16) & 0x1F), (int)((dosTime >> 11) & 0x1F), (int)((dosTime >> 5) & 0x3F), (int)((dosTime & 0x1F) * 2));
		}

		private static string NormalizeFileName(string fileNameToNormalize)
		{
			string text = fileNameToNormalize.Replace('\\', '/');
			int num = text.IndexOf(':');
			if (num >= 0)
			{
				text = text.Remove(0, num + 1);
			}
			return text.Trim(new char[1] { '/' });
		}

		private uint GetFileOffset(uint headerOffset)
		{
			byte[] array = new byte[2];
			zipFileStream.Seek(headerOffset + 26, SeekOrigin.Begin);
			zipFileStream.Read(array, 0, 2);
			ushort num = BitConverter.ToUInt16(array, 0);
			zipFileStream.Read(array, 0, 2);
			ushort num2 = BitConverter.ToUInt16(array, 0);
			return (uint)(30 + num + num2 + headerOffset);
		}

		private void WriteLocalHeader(ref ZipFileEntry zipFileEntry)
		{
			long position = zipFileStream.Position;
			byte[] bytes = (zipFileEntry.EncodeUTF8 ? Encoding.UTF8 : defaultEncoding).GetBytes(zipFileEntry.FilenameInZip);
			zipFileStream.Write(new byte[6] { 80, 75, 3, 4, 20, 0 }, 0, 6);
			zipFileStream.Write(BitConverter.GetBytes((ushort)(zipFileEntry.EncodeUTF8 ? 2048u : 0u)), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes((ushort)zipFileEntry.Method), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes(DateTimeToDosTime(zipFileEntry.ModifyTime)), 0, 4);
			zipFileStream.Write(new byte[12], 0, 12);
			zipFileStream.Write(BitConverter.GetBytes((ushort)bytes.Length), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes((ushort)0), 0, 2);
			zipFileStream.Write(bytes, 0, bytes.Length);
			zipFileEntry.HeaderSize = (uint)(zipFileStream.Position - position);
		}

		private void WriteCentralDirRecord(ZipFileEntry zipFileEntry)
		{
			Encoding obj = (zipFileEntry.EncodeUTF8 ? Encoding.UTF8 : defaultEncoding);
			byte[] bytes = obj.GetBytes(zipFileEntry.FilenameInZip);
			byte[] bytes2 = obj.GetBytes(zipFileEntry.Comment);
			zipFileStream.Write(new byte[8] { 80, 75, 1, 2, 23, 11, 20, 0 }, 0, 8);
			zipFileStream.Write(BitConverter.GetBytes((ushort)(zipFileEntry.EncodeUTF8 ? 2048u : 0u)), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes((ushort)zipFileEntry.Method), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes(DateTimeToDosTime(zipFileEntry.ModifyTime)), 0, 4);
			zipFileStream.Write(BitConverter.GetBytes(zipFileEntry.Crc32), 0, 4);
			zipFileStream.Write(BitConverter.GetBytes(zipFileEntry.CompressedSize), 0, 4);
			zipFileStream.Write(BitConverter.GetBytes(zipFileEntry.FileSize), 0, 4);
			zipFileStream.Write(BitConverter.GetBytes((ushort)bytes.Length), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes((ushort)0), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes((ushort)bytes2.Length), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes((ushort)0), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes((ushort)0), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes((ushort)0), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes((ushort)33024), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes(zipFileEntry.HeaderOffset), 0, 4);
			zipFileStream.Write(bytes, 0, bytes.Length);
			zipFileStream.Write(bytes2, 0, bytes2.Length);
		}

		private void WriteEndRecord(uint size, uint offset)
		{
			byte[] bytes = (EncodeUtf8 ? Encoding.UTF8 : defaultEncoding).GetBytes(comment);
			zipFileStream.Write(new byte[8] { 80, 75, 5, 6, 0, 0, 0, 0 }, 0, 8);
			zipFileStream.Write(BitConverter.GetBytes((ushort)files.Count + existingFileCount), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes((ushort)files.Count + existingFileCount), 0, 2);
			zipFileStream.Write(BitConverter.GetBytes(size), 0, 4);
			zipFileStream.Write(BitConverter.GetBytes(offset), 0, 4);
			zipFileStream.Write(BitConverter.GetBytes((ushort)bytes.Length), 0, 2);
			zipFileStream.Write(bytes, 0, bytes.Length);
		}

		private void Store(ref ZipFileEntry zipFileEntry, Stream sourceStream)
		{
			byte[] array = new byte[16384];
			uint num = 0u;
			long position = zipFileStream.Position;
			long position2 = sourceStream.Position;
			Stream stream = ((zipFileEntry.Method != 0) ? new DeflateStream(zipFileStream, CompressionMode.Compress, leaveOpen: true) : zipFileStream);
			zipFileEntry.Crc32 = uint.MaxValue;
			int num2;
			do
			{
				num2 = sourceStream.Read(array, 0, array.Length);
				num += (uint)num2;
				if (num2 > 0)
				{
					stream.Write(array, 0, num2);
					for (uint num3 = 0u; num3 < num2; num3++)
					{
						zipFileEntry.Crc32 = crcTable[(zipFileEntry.Crc32 ^ array[num3]) & 0xFF] ^ (zipFileEntry.Crc32 >> 8);
					}
				}
			}
			while (num2 == array.Length);
			stream.Flush();
			if (zipFileEntry.Method == CompressionMethod.Deflate)
			{
				stream.Dispose();
			}
			zipFileEntry.Crc32 ^= uint.MaxValue;
			zipFileEntry.FileSize = num;
			zipFileEntry.CompressedSize = (uint)(zipFileStream.Position - position);
			if (zipFileEntry.Method == CompressionMethod.Deflate && !ForceDeflating && sourceStream.CanSeek && zipFileEntry.CompressedSize > zipFileEntry.FileSize)
			{
				zipFileEntry.Method = CompressionMethod.Store;
				zipFileStream.Position = position;
				zipFileStream.SetLength(position);
				sourceStream.Position = position2;
				Store(ref zipFileEntry, sourceStream);
			}
		}

		private void UpdateCrcAndSizes(ref ZipFileEntry zipFileEntry)
		{
			long position = zipFileStream.Position;
			zipFileStream.Position = zipFileEntry.HeaderOffset + 8;
			zipFileStream.Write(BitConverter.GetBytes((ushort)zipFileEntry.Method), 0, 2);
			zipFileStream.Position = zipFileEntry.HeaderOffset + 14;
			zipFileStream.Write(BitConverter.GetBytes(zipFileEntry.Crc32), 0, 4);
			zipFileStream.Write(BitConverter.GetBytes(zipFileEntry.CompressedSize), 0, 4);
			zipFileStream.Write(BitConverter.GetBytes(zipFileEntry.FileSize), 0, 4);
			zipFileStream.Position = position;
		}

		private bool ReadFileInfo()
		{
			if (zipFileStream.Length < 22)
			{
				return false;
			}
			try
			{
				zipFileStream.Seek(-17L, SeekOrigin.End);
				BinaryReader binaryReader = new BinaryReader(zipFileStream);
				do
				{
					zipFileStream.Seek(-5L, SeekOrigin.Current);
					if (binaryReader.ReadUInt32() == 101010256)
					{
						zipFileStream.Seek(6L, SeekOrigin.Current);
						ushort num = binaryReader.ReadUInt16();
						int num2 = binaryReader.ReadInt32();
						uint num3 = binaryReader.ReadUInt32();
						ushort num4 = binaryReader.ReadUInt16();
						if (zipFileStream.Position + num4 != zipFileStream.Length)
						{
							return false;
						}
						existingFileCount = num;
						centralDirectoryImage = new byte[num2];
						zipFileStream.Seek(num3, SeekOrigin.Begin);
						zipFileStream.Read(centralDirectoryImage, 0, num2);
						zipFileStream.Seek(num3, SeekOrigin.Begin);
						return true;
					}
				}
				while (zipFileStream.Position > 0);
			}
			catch (IOException)
			{
			}
			return false;
		}
