		{
			if (cssSelectorToFind == null)
			{
				throw new ArgumentNullException("cssSelectorToFind", "Cannot find elements when name CSS selector is null.");
			}
			return new By
			{
				findElementMethod = (ISearchContext context) => ((IFindsByCssSelector)context).FindElementByCssSelector(cssSelectorToFind),
				findElementsMethod = (ISearchContext context) => ((IFindsByCssSelector)context).FindElementsByCssSelector(cssSelectorToFind),
				description = "By.CssSelector: " + cssSelectorToFind
			};
		}

		public virtual IWebElement FindElement(ISearchContext context)
		{
			return findElementMethod(context);
		}

		public virtual ReadOnlyCollection<IWebElement> FindElements(ISearchContext context)
		{
			return findElementsMethod(context);
		}

		public override string ToString()
		{
			return description;
		}

		public override bool Equals(object obj)
		{
			By by = obj as By;
			if (by != null)
			{
				return description.Equals(by.description);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return description.GetHashCode();
		}
	}
	[Serializable]
	[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
	public class Cookie
	{
		private string cookieName;

		private string cookieValue;

		private string cookiePath;

		private string cookieDomain;

		private DateTime? cookieExpiry;

		[JsonProperty("name")]
		public string Name => cookieName;

		[JsonProperty("value")]
		public string Value => cookieValue;

		[JsonProperty("domain", NullValueHandling = NullValueHandling.Ignore)]
		public string Domain => cookieDomain;

		[JsonProperty("path", NullValueHandling = NullValueHandling.Ignore)]
		public virtual string Path => cookiePath;

		[JsonProperty("secure")]
		public virtual bool Secure => false;

		[JsonProperty("httpOnly")]
		public virtual bool IsHttpOnly => false;

		public DateTime? Expiry => cookieExpiry;

		[JsonProperty("expiry", NullValueHandling = NullValueHandling.Ignore)]
		internal long? ExpirySeconds
		{
			get
			{
				if (!cookieExpiry.HasValue)
				{
					return null;
				}
				DateTime value = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc);
				return Convert.ToInt64(cookieExpiry.Value.ToUniversalTime().Subtract(value).TotalSeconds);
			}
		}

		public Cookie(string name, string value, string domain, string path, DateTime? expiry)
		{
			if (string.IsNullOrEmpty(name))
			{
				throw new ArgumentException("Cookie name cannot be null or empty string", "name");
			}
			if (value == null)
			{
				throw new ArgumentNullException("value", "Cookie value cannot be null");
			}
			if (name.IndexOf(';') != -1)
			{
				throw new ArgumentException("Cookie names cannot contain a ';': " + name, "name");
			}
			cookieName = name;
			cookieValue = value;
			if (!string.IsNullOrEmpty(path))
			{
				cookiePath = path;
			}
			cookieDomain = StripPort(domain);
			if (expiry.HasValue)
			{
				cookieExpiry = expiry;
			}
		}

		public Cookie(string name, string value, string path, DateTime? expiry)
			: this(name, value, null, path, expiry)
		{
		}

		public Cookie(string name, string value, string path)
			: this(name, value, path, null)
		{
		}

		public Cookie(string name, string value)
			: this(name, value, null, null)
		{
		}

		public static Cookie FromDictionary(Dictionary<string, object> rawCookie)
		{
			if (rawCookie == null)
			{
				throw new ArgumentNullException("rawCookie", "Dictionary cannot be null");
			}
			string name = rawCookie["name"].ToString();
			string value = string.Empty;
			if (rawCookie["value"] != null)
			{
				value = rawCookie["value"].ToString();
			}
			string path = "/";
			if (rawCookie.ContainsKey("path") && rawCookie["path"] != null)
			{
				path = rawCookie["path"].ToString();
			}
			string domain = string.Empty;
			if (rawCookie.ContainsKey("domain") && rawCookie["domain"] != null)
			{
				domain = rawCookie["domain"].ToString();
			}
			DateTime? expiry = null;
			if (rawCookie.ContainsKey("expiry") && rawCookie["expiry"] != null)
			{
				double result = 0.0;
				if (double.TryParse(rawCookie["expiry"].ToString(), NumberStyles.Number, CultureInfo.InvariantCulture, out result))
				{
					try
					{
						expiry = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc).AddSeconds(result).ToLocalTime();
					}
					catch (ArgumentOutOfRangeException)
					{
						DateTime maxValue = DateTime.MaxValue;
						expiry = maxValue.ToLocalTime();
					}
				}
			}
			bool isSecure = false;
			if (rawCookie.ContainsKey("secure") && rawCookie["secure"] != null)
			{
				isSecure = bool.Parse(rawCookie["secure"].ToString());
			}
			bool isHttpOnly = false;
			if (rawCookie.ContainsKey("httpOnly") && rawCookie["httpOnly"] != null)
			{
				isHttpOnly = bool.Parse(rawCookie["httpOnly"].ToString());
			}
			return new ReturnedCookie(name, value, domain, path, expiry, isSecure, isHttpOnly);
		}

		public override string ToString()
		{
			return cookieName + "=" + cookieValue + ((!cookieExpiry.HasValue) ? string.Empty : ("; expires=" + cookieExpiry.Value.ToUniversalTime().ToString("ddd MM dd yyyy hh:mm:ss UTC", CultureInfo.InvariantCulture))) + (string.IsNullOrEmpty(cookiePath) ? string.Empty : ("; path=" + cookiePath)) + (string.IsNullOrEmpty(cookieDomain) ? string.Empty : ("; domain=" + cookieDomain));
		}

		public override bool Equals(object obj)
		{
			Cookie cookie = obj as Cookie;
			if (this == obj)
			{
				return true;
			}
			if (cookie == null)
			{
				return false;
			}
			if (!cookieName.Equals(cookie.cookieName))
			{
				return false;
			}
			return !((cookieValue != null) ? (!cookieValue.Equals(cookie.cookieValue)) : (cookie.Value != null));
		}

		public override int GetHashCode()
		{
			return cookieName.GetHashCode();
		}

		private static string StripPort(string domain)
		{
			if (!string.IsNullOrEmpty(domain))
			{
				return domain.Split(new char[1] { ':' })[0];
			}
			return null;
		}
	}
