	public abstract class DriverOptions
	{
		private string browserName;

		private string browserVersion;

		private string platformName;

		private Proxy proxy;

		private bool? acceptInsecureCertificates;

		private UnhandledPromptBehavior unhandledPromptBehavior;

		private PageLoadStrategy pageLoadStrategy;

		private Dictionary<string, object> additionalCapabilities = new Dictionary<string, object>();

		private Dictionary<string, LogLevel> loggingPreferences = new Dictionary<string, LogLevel>();

		private Dictionary<string, string> knownCapabilityNames = new Dictionary<string, string>();

		public string BrowserName
		{
			get
			{
				return browserName;
			}
			protected set
			{
				browserName = value;
			}
		}

		public string BrowserVersion
		{
			get
			{
				return browserVersion;
			}
			set
			{
				browserVersion = value;
			}
		}

		public string PlatformName
		{
			get
			{
				return platformName;
			}
			set
			{
				platformName = value;
			}
		}

		public bool? AcceptInsecureCertificates
		{
			get
			{
				return acceptInsecureCertificates;
			}
			set
			{
				acceptInsecureCertificates = value;
			}
		}

		public UnhandledPromptBehavior UnhandledPromptBehavior
		{
			get
			{
				return unhandledPromptBehavior;
			}
			set
			{
				unhandledPromptBehavior = value;
			}
		}

		public PageLoadStrategy PageLoadStrategy
		{
			get
			{
				return pageLoadStrategy;
			}
			set
			{
				pageLoadStrategy = value;
			}
		}

		public Proxy Proxy
		{
			get
			{
				return proxy;
			}
			set
			{
				proxy = value;
			}
		}

		protected DriverOptions()
		{
			AddKnownCapabilityName(CapabilityType.BrowserName, "BrowserName property");
			AddKnownCapabilityName(CapabilityType.BrowserVersion, "BrowserVersion property");
			AddKnownCapabilityName(CapabilityType.PlatformName, "PlatformName property");
			AddKnownCapabilityName(CapabilityType.Proxy, "Proxy property");
			AddKnownCapabilityName(CapabilityType.UnhandledPromptBehavior, "UnhandledPromptBehavior property");
			AddKnownCapabilityName(CapabilityType.PageLoadStrategy, "PageLoadStrategy property");
		}

		public abstract void AddAdditionalCapability(string capabilityName, object capabilityValue);

		public abstract ICapabilities ToCapabilities();

		public virtual DriverOptionsMergeResult GetMergeResult(DriverOptions other)
		{
			DriverOptionsMergeResult driverOptionsMergeResult = new DriverOptionsMergeResult();
			if (browserName != null && other.BrowserName != null)
			{
				driverOptionsMergeResult.IsMergeConflict = true;
				driverOptionsMergeResult.MergeConflictOptionName = "BrowserName";
				return driverOptionsMergeResult;
			}
			if (browserVersion != null && other.BrowserVersion != null)
			{
				driverOptionsMergeResult.IsMergeConflict = true;
				driverOptionsMergeResult.MergeConflictOptionName = "BrowserVersion";
				return driverOptionsMergeResult;
			}
			if (platformName != null && other.PlatformName != null)
			{
				driverOptionsMergeResult.IsMergeConflict = true;
				driverOptionsMergeResult.MergeConflictOptionName = "PlatformName";
				return driverOptionsMergeResult;
			}
			if (proxy != null && other.Proxy != null)
			{
				driverOptionsMergeResult.IsMergeConflict = true;
				driverOptionsMergeResult.MergeConflictOptionName = "Proxy";
				return driverOptionsMergeResult;
			}
			if (unhandledPromptBehavior != 0 && other.UnhandledPromptBehavior != 0)
			{
				driverOptionsMergeResult.IsMergeConflict = true;
				driverOptionsMergeResult.MergeConflictOptionName = "UnhandledPromptBehavior";
				return driverOptionsMergeResult;
			}
			if (pageLoadStrategy != 0 && other.PageLoadStrategy != 0)
			{
				driverOptionsMergeResult.IsMergeConflict = true;
				driverOptionsMergeResult.MergeConflictOptionName = "PageLoadStrategy";
				return driverOptionsMergeResult;
			}
			return driverOptionsMergeResult;
		}

		public void SetLoggingPreference(string logType, LogLevel logLevel)
		{
			loggingPreferences[logType] = logLevel;
		}

		public override string ToString()
		{
			return JsonConvert.SerializeObject(ToDictionary(), Newtonsoft.Json.Formatting.Indented);
		}

		internal Dictionary<string, object> ToDictionary()
		{
			return (ToCapabilities() as IHasCapabilitiesDictionary).CapabilitiesDictionary;
		}

		protected void AddKnownCapabilityName(string capabilityName, string typeSafeOptionName)
		{
			knownCapabilityNames[capabilityName] = typeSafeOptionName;
		}

		protected bool IsKnownCapabilityName(string capabilityName)
		{
			return knownCapabilityNames.ContainsKey(capabilityName);
		}

		protected string GetTypeSafeOptionName(string capabilityName)
		{
			if (IsKnownCapabilityName(capabilityName))
			{
				return string.Empty;
			}
			return knownCapabilityNames[capabilityName];
		}

		protected Dictionary<string, object> GenerateLoggingPreferencesDictionary()
		{
			if (loggingPreferences.Count == 0)
			{
				return null;
			}
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			foreach (string key in loggingPreferences.Keys)
			{
				dictionary[key] = loggingPreferences[key].ToString().ToUpperInvariant();
			}
			return dictionary;
		}

		protected DesiredCapabilities GenerateDesiredCapabilities(bool isSpecificationCompliant)
		{
			DesiredCapabilities desiredCapabilities = new DesiredCapabilities();
			if (!string.IsNullOrEmpty(browserName))
			{
				desiredCapabilities.SetCapability(CapabilityType.BrowserName, browserName);
			}
			if (!string.IsNullOrEmpty(browserVersion))
			{
				desiredCapabilities.SetCapability(CapabilityType.BrowserVersion, browserVersion);
			}
			if (!string.IsNullOrEmpty(platformName))
			{
				desiredCapabilities.SetCapability(CapabilityType.PlatformName, platformName);
			}
			if (acceptInsecureCertificates.HasValue)
			{
				desiredCapabilities.SetCapability(CapabilityType.AcceptInsecureCertificates, acceptInsecureCertificates);
			}
			if (pageLoadStrategy != 0)
			{
				string capabilityValue = "normal";
				switch (pageLoadStrategy)
				{
				case PageLoadStrategy.Eager:
					capabilityValue = "eager";
					break;
				case PageLoadStrategy.None:
					capabilityValue = "none";
					break;
				}
				desiredCapabilities.SetCapability(CapabilityType.PageLoadStrategy, capabilityValue);
			}
			if (UnhandledPromptBehavior != 0)
			{
				string capabilityValue2 = "ignore";
				switch (UnhandledPromptBehavior)
				{
				case UnhandledPromptBehavior.Accept:
					capabilityValue2 = "accept";
					break;
				case UnhandledPromptBehavior.Dismiss:
					capabilityValue2 = "dismiss";
					break;
				case UnhandledPromptBehavior.AcceptAndNotify:
					capabilityValue2 = "accept and notify";
					break;
				case UnhandledPromptBehavior.DismissAndNotify:
					capabilityValue2 = "dismiss and notify";
					break;
				}
				desiredCapabilities.SetCapability(CapabilityType.UnhandledPromptBehavior, capabilityValue2);
			}
			if (Proxy != null)
			{
				Dictionary<string, object> dictionary = Proxy.ToCapability();
				if (!isSpecificationCompliant)
				{
					dictionary = Proxy.ToLegacyCapability();
				}
				if (dictionary != null)
				{
					desiredCapabilities.SetCapability(CapabilityType.Proxy, dictionary);
				}
			}
			return desiredCapabilities;
		}
	}
	public abstract class DriverService : ICommandServer, IDisposable
	{
		private string driverServicePath;

		private string driverServiceExecutableName;

		private string driverServiceHostName = "localhost";

		private int driverServicePort;

		private bool silent;

		private bool hideCommandPromptWindow;

		private bool isDisposed;

		private Process driverServiceProcess;

		public Uri ServiceUrl => new Uri(string.Format(CultureInfo.InvariantCulture, "http://{0}:{1}", new object[2] { driverServiceHostName, driverServicePort }));

		public string HostName
		{
			get
			{
				return driverServiceHostName;
			}
			set
			{
				driverServiceHostName = value;
			}
		}

		public int Port
		{
			get
			{
				return driverServicePort;
			}
			set
			{
				driverServicePort = value;
			}
		}

		public bool SuppressInitialDiagnosticInformation
		{
			get
			{
				return silent;
			}
			set
			{
				silent = value;
			}
		}

		public bool IsRunning
		{
			[SecurityPermission(SecurityAction.Demand)]
			get
			{
				if (driverServiceProcess != null)
				{
					return !driverServiceProcess.HasExited;
				}
				return false;
			}
		}

		public bool HideCommandPromptWindow
		{
			get
			{
				return hideCommandPromptWindow;
			}
			set
			{
				hideCommandPromptWindow = value;
			}
		}

		public int ProcessId
		{
			get
			{
				if (IsRunning)
				{
					try
					{
						return driverServiceProcess.Id;
					}
					catch (InvalidOperationException)
					{
					}
				}
				return 0;
			}
		}

		protected string DriverServiceExecutableName => driverServiceExecutableName;

		protected virtual string CommandLineArguments => string.Format(CultureInfo.InvariantCulture, "--port={0}", new object[1] { driverServicePort });

		protected virtual TimeSpan InitializationTimeout => TimeSpan.FromSeconds(20.0);

		protected virtual TimeSpan TerminationTimeout => TimeSpan.FromSeconds(10.0);

		protected virtual bool HasShutdown => true;

		protected virtual bool IsInitialized
		{
			get
			{
				bool result = false;
				try
				{
					HttpWebRequest obj = WebRequest.Create(new Uri(ServiceUrl, new Uri(DriverCommand.Status, UriKind.Relative))) as HttpWebRequest;
					obj.KeepAlive = false;
					obj.Timeout = 5000;
					HttpWebResponse httpWebResponse = obj.GetResponse() as HttpWebResponse;
					result = httpWebResponse.StatusCode == HttpStatusCode.OK && httpWebResponse.ContentType.StartsWith("application/json", StringComparison.OrdinalIgnoreCase);
					httpWebResponse.Close();
				}
				catch (WebException ex)
				{
					Console.WriteLine(ex.Message);
				}
				return result;
			}
		}

		protected DriverService(string servicePath, int port, string driverServiceExecutableName, Uri driverServiceDownloadUrl)
		{
			if (string.IsNullOrEmpty(servicePath))
			{
				throw new ArgumentException("Path to locate driver executable cannot be null or empty.", "servicePath");
			}
			string text = Path.Combine(servicePath, driverServiceExecutableName);
			if (!File.Exists(text))
			{
				throw new DriverServiceNotFoundException(string.Format(CultureInfo.InvariantCulture, "The file {0} does not exist. The driver can be downloaded at {1}", new object[2] { text, driverServiceDownloadUrl }));
			}
			driverServicePath = servicePath;
			this.driverServiceExecutableName = driverServiceExecutableName;
			driverServicePort = port;
		}

		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		[SecurityPermission(SecurityAction.Demand)]
		public void Start()
		{
			driverServiceProcess = new Process();
			driverServiceProcess.StartInfo.FileName = Path.Combine(driverServicePath, driverServiceExecutableName);
			driverServiceProcess.StartInfo.Arguments = CommandLineArguments;
			driverServiceProcess.StartInfo.UseShellExecute = false;
			driverServiceProcess.StartInfo.CreateNoWindow = hideCommandPromptWindow;
			driverServiceProcess.Start();
			if (!WaitForServiceInitialization())
			{
				throw new WebDriverException("Cannot start the driver service on " + ServiceUrl);
			}
		}

		protected static string FindDriverServiceExecutable(string executableName, Uri downloadUrl)
		{
			string text = FileUtilities.FindFile(executableName);
			if (string.IsNullOrEmpty(text))
			{
				throw new DriverServiceNotFoundException(string.Format(CultureInfo.InvariantCulture, "The {0} file does not exist in the current directory or in a directory on the PATH environment variable. The driver can be downloaded at {1}.", new object[2] { executableName, downloadUrl }));
			}
			return text;
		}

		protected virtual void Dispose(bool disposing)
		{
			if (!isDisposed)
			{
				if (disposing)
				{
					Stop();
				}
				isDisposed = true;
			}
		}

		[SecurityPermission(SecurityAction.Demand)]
		private void Stop()
		{
			if (!IsRunning)
			{
				return;
			}
			if (HasShutdown)
			{
				Uri requestUri = new Uri(ServiceUrl, "/shutdown");
				DateTime dateTime = DateTime.Now.Add(TerminationTimeout);
				while (IsRunning && DateTime.Now < dateTime)
				{
					try
					{
						HttpWebRequest obj = WebRequest.Create(requestUri) as HttpWebRequest;
						obj.KeepAlive = false;
						(obj.GetResponse() as HttpWebResponse).Close();
						driverServiceProcess.WaitForExit(3000);
					}
					catch (WebException)
					{
					}
				}
			}
			if (IsRunning)
			{
				driverServiceProcess.WaitForExit(Convert.ToInt32(TerminationTimeout.TotalMilliseconds));
				if (!driverServiceProcess.HasExited)
				{
					driverServiceProcess.Kill();
				}
			}
			driverServiceProcess.Dispose();
			driverServiceProcess = null;
		}

		private bool WaitForServiceInitialization()
		{
			bool flag = false;
			DateTime dateTime = DateTime.Now.Add(InitializationTimeout);
			while (!flag && DateTime.Now < dateTime && IsRunning)
			{
				flag = IsInitialized;
			}
			return flag;
		}
	}
