	public class LogEntry
	{
		private LogLevel level;

		private DateTime timestamp = DateTime.MinValue;

		private string message = string.Empty;

		public DateTime Timestamp => timestamp;

		public LogLevel Level => level;

		public string Message => message;

		private LogEntry()
		{
		}

		public override string ToString()
		{
			return string.Format(CultureInfo.InvariantCulture, "[{0:yyyy-MM-ddTHH:mm:ssZ}] [{1}] {2}", new object[3] { timestamp, level, message });
		}

		internal static LogEntry FromDictionary(Dictionary<string, object> entryDictionary)
		{
			LogEntry logEntry = new LogEntry();
			if (entryDictionary.ContainsKey("message"))
			{
				logEntry.message = entryDictionary["message"].ToString();
			}
			if (entryDictionary.ContainsKey("timestamp"))
			{
				DateTime dateTime = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc);
				double value = Convert.ToDouble(entryDictionary["timestamp"], CultureInfo.InvariantCulture);
				logEntry.timestamp = dateTime.AddMilliseconds(value);
			}
			if (entryDictionary.ContainsKey("level"))
			{
				string value2 = entryDictionary["level"].ToString();
				try
				{
					logEntry.level = (LogLevel)Enum.Parse(typeof(LogLevel), value2, ignoreCase: true);
				}
				catch (ArgumentException)
				{
				}
			}
			return logEntry;
		}
	}
