	public enum PlatformType
	{
		Any = 0,
		Windows = 1,
		WinNT = 1,
		XP = 2,
		Vista = 3,
		Mac = 4,
		Unix = 5,
		Linux = 6,
		Android = 7
	}
	public class Platform
	{
		private static Platform current;

		private PlatformType platformTypeValue;

		private int major;

		private int minor;

		public static Platform CurrentPlatform
		{
			get
			{
				if (current == null)
				{
					current = new Platform();
				}
				return current;
			}
		}

		public int MajorVersion => major;

		public int MinorVersion => minor;

		public PlatformType PlatformType => platformTypeValue;

		public string ProtocolPlatformType => platformTypeValue.ToString("G").ToUpperInvariant();

		public Platform(PlatformType typeValue)
		{
			platformTypeValue = typeValue;
		}

		private Platform()
		{
			major = Environment.OSVersion.Version.Major;
			minor = Environment.OSVersion.Version.Minor;
			switch (Environment.OSVersion.Platform)
			{
			case PlatformID.Win32NT:
				if (major == 5)
				{
					platformTypeValue = PlatformType.XP;
				}
				else if (major == 6)
				{
					platformTypeValue = PlatformType.Vista;
				}
				else
				{
					platformTypeValue = PlatformType.Windows;
				}
				break;
			case PlatformID.MacOSX:
				platformTypeValue = PlatformType.Mac;
				break;
			case PlatformID.Unix:
				platformTypeValue = PlatformType.Unix;
				break;
			case PlatformID.WinCE:
			case PlatformID.Xbox:
				break;
			}
		}

		public bool IsPlatformType(PlatformType compareTo)
		{
			bool flag = false;
			return compareTo switch
			{
				PlatformType.Any => true, 
				PlatformType.Windows => platformTypeValue == PlatformType.Windows || platformTypeValue == PlatformType.XP || platformTypeValue == PlatformType.Vista, 
				PlatformType.Vista => platformTypeValue == PlatformType.Windows || platformTypeValue == PlatformType.Vista, 
				PlatformType.XP => platformTypeValue == PlatformType.Windows || platformTypeValue == PlatformType.XP, 
				PlatformType.Linux => platformTypeValue == PlatformType.Linux || platformTypeValue == PlatformType.Unix, 
				_ => platformTypeValue == compareTo, 
			};
		}

		public override string ToString()
		{
			return platformTypeValue.ToString();
		}

		internal static Platform FromString(string platformName)
		{
			PlatformType typeValue = PlatformType.Any;
			try
			{
				typeValue = (PlatformType)Enum.Parse(typeof(PlatformType), platformName, ignoreCase: true);
			}
			catch (ArgumentException)
			{
			}
			return new Platform(typeValue);
		}
	}
	public enum ProxyKind
	{
		Direct = 0,
		Manual = 1,
		ProxyAutoConfigure = 2,
		AutoDetect = 4,
		System = 5,
		Unspecified = 6
	}
	[JsonObject(MemberSerialization.OptIn)]
	public class Proxy
	{
		private ProxyKind proxyKind = ProxyKind.Unspecified;

		private bool isAutoDetect;

		private string ftpProxyLocation;

		private string httpProxyLocation;

		private string proxyAutoConfigUrl;

		private string sslProxyLocation;

		private string socksProxyLocation;

		private string socksUserName;

		private string socksPassword;

		private List<string> noProxyAddresses = new List<string>();

		[JsonIgnore]
		public ProxyKind Kind
		{
			get
			{
				return proxyKind;
			}
			set
			{
				VerifyProxyTypeCompatilibily(value);
				proxyKind = value;
			}
		}

		[JsonProperty("proxyType")]
		public string SerializableProxyKind
		{
			get
			{
				if (proxyKind == ProxyKind.ProxyAutoConfigure)
				{
					return "PAC";
				}
				return proxyKind.ToString().ToUpperInvariant();
			}
		}

		[JsonIgnore]
		public bool IsAutoDetect
		{
			get
			{
				return isAutoDetect;
			}
			set
			{
				if (isAutoDetect != value)
				{
					VerifyProxyTypeCompatilibily(ProxyKind.AutoDetect);
					proxyKind = ProxyKind.AutoDetect;
					isAutoDetect = value;
				}
			}
		}

		[JsonProperty("ftpProxy", DefaultValueHandling = DefaultValueHandling.Ignore, NullValueHandling = NullValueHandling.Ignore)]
		public string FtpProxy
		{
