		public Proxy()
		{
		}

		public Proxy(Dictionary<string, object> settings)
		{
			if (settings == null)
			{
				throw new ArgumentNullException("settings", "settings dictionary cannot be null");
			}
			if (settings.ContainsKey("proxyType"))
			{
				ProxyKind kind = (ProxyKind)Enum.Parse(typeof(ProxyKind), settings["proxyType"].ToString(), ignoreCase: true);
				Kind = kind;
			}
			if (settings.ContainsKey("ftpProxy"))
			{
				FtpProxy = settings["ftpProxy"].ToString();
			}
			if (settings.ContainsKey("httpProxy"))
			{
				HttpProxy = settings["httpProxy"].ToString();
			}
			if (settings.ContainsKey("noProxy"))
			{
				List<string> list = new List<string>();
				if (settings["noProxy"] is string text)
				{
					list.AddRange(text.Split(new char[1] { ';' }));
				}
				else if (settings["noProxy"] is object[] array)
				{
					object[] array2 = array;
					foreach (object obj in array2)
					{
						list.Add(obj.ToString());
					}
				}
				AddBypassAddresses(list);
			}
			if (settings.ContainsKey("proxyAutoconfigUrl"))
			{
				ProxyAutoConfigUrl = settings["proxyAutoconfigUrl"].ToString();
			}
			if (settings.ContainsKey("sslProxy"))
			{
				SslProxy = settings["sslProxy"].ToString();
			}
			if (settings.ContainsKey("socksProxy"))
			{
				SocksProxy = settings["socksProxy"].ToString();
			}
			if (settings.ContainsKey("socksUsername"))
			{
				SocksUserName = settings["socksUsername"].ToString();
			}
			if (settings.ContainsKey("socksPassword"))
			{
				SocksPassword = settings["socksPassword"].ToString();
			}
			if (settings.ContainsKey("autodetect"))
			{
				IsAutoDetect = (bool)settings["autodetect"];
			}
		}

		public void AddBypassAddress(string address)
		{
			if (string.IsNullOrEmpty(address))
			{
				throw new ArgumentException("address must not be null or empty", "address");
			}
			AddBypassAddresses(address);
		}

		public void AddBypassAddresses(params string[] addressesToAdd)
		{
			AddBypassAddresses(new List<string>(addressesToAdd));
		}

		public void AddBypassAddresses(IEnumerable<string> addressesToAdd)
		{
			if (addressesToAdd == null)
			{
				throw new ArgumentNullException("addressesToAdd", "addressesToAdd must not be null");
			}
			VerifyProxyTypeCompatilibily(ProxyKind.Manual);
			proxyKind = ProxyKind.Manual;
			noProxyAddresses.AddRange(addressesToAdd);
		}

		internal Dictionary<string, object> ToCapability()
		{
			return AsDictionary(isSpecCompliant: true);
		}

		internal Dictionary<string, object> ToLegacyCapability()
		{
			return AsDictionary(isSpecCompliant: false);
		}

		private Dictionary<string, object> AsDictionary(bool isSpecCompliant)
		{
			Dictionary<string, object> dictionary = null;
			if (proxyKind != ProxyKind.Unspecified)
			{
				dictionary = new Dictionary<string, object>();
				if (proxyKind == ProxyKind.ProxyAutoConfigure)
				{
					dictionary["proxyType"] = "pac";
					if (!string.IsNullOrEmpty(proxyAutoConfigUrl))
					{
						dictionary["proxyAutoconfigUrl"] = proxyAutoConfigUrl;
					}
				}
				else
				{
					dictionary["proxyType"] = proxyKind.ToString().ToLowerInvariant();
				}
				if (!string.IsNullOrEmpty(httpProxyLocation))
				{
					dictionary["httpProxy"] = httpProxyLocation;
				}
				if (!string.IsNullOrEmpty(sslProxyLocation))
				{
					dictionary["sslProxy"] = sslProxyLocation;
				}
				if (!string.IsNullOrEmpty(ftpProxyLocation))
				{
					dictionary["ftpProxy"] = ftpProxyLocation;
				}
				if (!string.IsNullOrEmpty(socksProxyLocation))
				{
					string text = string.Empty;
					if (!string.IsNullOrEmpty(socksUserName) && !string.IsNullOrEmpty(socksPassword))
					{
						text = socksUserName + ":" + socksPassword + "@";
					}
					dictionary["socksProxy"] = text + socksProxyLocation;
				}
				if (noProxyAddresses.Count > 0)
				{
					dictionary["noProxy"] = GetNoProxyAddressList(isSpecCompliant);
				}
			}
			return dictionary;
		}

		private object GetNoProxyAddressList(bool isSpecCompliant)
		{
			object obj = null;
			if (isSpecCompliant)
			{
				List<object> list = new List<object>();
				foreach (string noProxyAddress in noProxyAddresses)
				{
					list.Add(noProxyAddress);
				}
				return list;
			}
			return BypassProxyAddresses;
		}

		private void VerifyProxyTypeCompatilibily(ProxyKind compatibleProxy)
		{
			if (proxyKind != ProxyKind.Unspecified && proxyKind != compatibleProxy)
			{
				throw new InvalidOperationException(string.Format(CultureInfo.InvariantCulture, "Specified proxy type {0} is not compatible with current setting {1}", new object[2]
				{
					compatibleProxy.ToString().ToUpperInvariant(),
					proxyKind.ToString().ToUpperInvariant()
				}));
			}
		}
	}
	public class RemoteSessionSettings : ICapabilities
	{
		private const string FirstMatchCapabilityName = "firstMatch";

		private const string AlwaysMatchCapabilityName = "alwaysMatch";

		private readonly List<string> reservedSettingNames = new List<string> { "firstMatch", "alwaysMatch" };

		private DriverOptions mustMatchDriverOptions;

		private List<DriverOptions> firstMatchOptions = new List<DriverOptions>();

		private Dictionary<string, object> remoteMetadataSettings = new Dictionary<string, object>();

		internal DriverOptions MustMatchDriverOptions => mustMatchDriverOptions;

		internal int FirstMatchOptionsCount => firstMatchOptions.Count;

		public object this[string capabilityName]
		{
			get
			{
				if (capabilityName == "alwaysMatch")
				{
					return GetAlwaysMatchOptionsAsSerializableDictionary();
				}
				if (capabilityName == "firstMatch")
				{
					return GetFirstMatchOptionsAsSerializableList();
				}
				if (!remoteMetadataSettings.ContainsKey(capabilityName))
				{
					throw new ArgumentException(string.Format(CultureInfo.InvariantCulture, "The capability {0} is not present in this set of capabilities", new object[1] { capabilityName }));
				}
				return remoteMetadataSettings[capabilityName];
			}
		}

		public RemoteSessionSettings()
		{
		}

		public RemoteSessionSettings(DriverOptions mustMatchDriverOptions, params DriverOptions[] firstMatchDriverOptions)
		{
			this.mustMatchDriverOptions = mustMatchDriverOptions;
			foreach (DriverOptions options in firstMatchDriverOptions)
			{
				AddFirstMatchDriverOption(options);
			}
		}

		public void AddMetadataSetting(string settingName, object settingValue)
		{
			if (string.IsNullOrEmpty(settingName))
			{
				throw new ArgumentException("Metadata setting name cannot be null or empty", "settingName");
			}
			if (reservedSettingNames.Contains(settingName))
			{
				throw new ArgumentException($"'{settingName}' is a reserved name for a metadata setting, and cannot be used as a name.", "settingName");
			}
			if (!IsJsonSerializable(settingValue))
			{
				throw new ArgumentException("Metadata setting value must be JSON serializable.", "settingValue");
			}
			remoteMetadataSettings[settingName] = settingValue;
		}

		public void AddFirstMatchDriverOption(DriverOptions options)
		{
			if (mustMatchDriverOptions != null)
			{
				DriverOptionsMergeResult mergeResult = mustMatchDriverOptions.GetMergeResult(options);
				if (mergeResult.IsMergeConflict)
				{
					throw new ArgumentException(string.Format(CultureInfo.InvariantCulture, "You cannot request the same capability in both must-match and first-match capabilities. You are attempting to add a first-match driver options object that defines a capability, '{0}', that is already defined in the must-match driver options.", new object[1] { mergeResult.MergeConflictOptionName }), "options");
				}
			}
			firstMatchOptions.Add(options);
		}

		public void SetMustMatchDriverOptions(DriverOptions options)
		{
			if (firstMatchOptions.Count > 0)
			{
				int num = 0;
				foreach (DriverOptions firstMatchOption in firstMatchOptions)
				{
					DriverOptionsMergeResult mergeResult = firstMatchOption.GetMergeResult(options);
					if (mergeResult.IsMergeConflict)
					{
						throw new ArgumentException(string.Format(CultureInfo.InvariantCulture, "You cannot request the same capability in both must-match and first-match capabilities. You are attempting to add a must-match driver options object that defines a capability, '{0}', that is already defined in the first-match driver options with index {1}.", new object[2] { mergeResult.MergeConflictOptionName, num }), "options");
					}
					num++;
				}
			}
			mustMatchDriverOptions = options;
		}

		public bool HasCapability(string capability)
		{
			if (capability == "alwaysMatch" || capability == "firstMatch")
			{
				return true;
			}
			return remoteMetadataSettings.ContainsKey(capability);
		}

		public object GetCapability(string capability)
		{
			if (capability == "alwaysMatch")
			{
				return GetAlwaysMatchOptionsAsSerializableDictionary();
			}
			if (capability == "firstMatch")
			{
				return GetFirstMatchOptionsAsSerializableList();
			}
			if (remoteMetadataSettings.ContainsKey(capability))
			{
				return remoteMetadataSettings[capability];
			}
			return null;
		}

		public Dictionary<string, object> ToDictionary()
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			foreach (KeyValuePair<string, object> remoteMetadataSetting in remoteMetadataSettings)
			{
				dictionary[remoteMetadataSetting.Key] = remoteMetadataSetting.Value;
			}
			if (mustMatchDriverOptions != null)
			{
				dictionary["alwaysMatch"] = GetAlwaysMatchOptionsAsSerializableDictionary();
			}
			if (firstMatchOptions.Count > 0)
			{
				List<object> firstMatchOptionsAsSerializableList = GetFirstMatchOptionsAsSerializableList();
				dictionary["firstMatch"] = firstMatchOptionsAsSerializableList;
			}
			return dictionary;
		}

		public override string ToString()
		{
			return JsonConvert.SerializeObject(ToDictionary(), Newtonsoft.Json.Formatting.Indented);
		}

		internal DriverOptions GetFirstMatchDriverOptions(int firstMatchIndex)
		{
			if (firstMatchIndex < 0 || firstMatchIndex >= firstMatchOptions.Count)
			{
				throw new ArgumentException("Requested index must be greater than zero and less than the count of firstMatch options added.");
			}
			return firstMatchOptions[firstMatchIndex];
		}

		private Dictionary<string, object> GetAlwaysMatchOptionsAsSerializableDictionary()
		{
			return mustMatchDriverOptions.ToDictionary();
		}

		private List<object> GetFirstMatchOptionsAsSerializableList()
		{
			List<object> list = new List<object>();
			foreach (DriverOptions firstMatchOption in firstMatchOptions)
			{
				list.Add(firstMatchOption.ToDictionary());
			}
			return list;
		}

		private bool IsJsonSerializable(object arg)
		{
			IEnumerable enumerable = arg as IEnumerable;
			IDictionary dictionary = arg as IDictionary;
			if (arg is string || arg is float || arg is double || arg is int || arg is long || arg is bool || arg == null)
			{
				return true;
			}
			if (dictionary != null)
			{
				foreach (object key in dictionary.Keys)
				{
					if (!(key is string))
					{
						return false;
					}
				}
				foreach (object value in dictionary.Values)
				{
					if (!IsJsonSerializable(value))
					{
						return false;
					}
				}
			}
			else
			{
				if (enumerable == null)
				{
					return false;
				}
				foreach (object item in enumerable)
				{
					if (!IsJsonSerializable(item))
					{
						return false;
					}
				}
			}
			return true;
		}
	}
