namespace OpenQA.Selenium.Support.UI
{
	public class DefaultWait<T> : IWait<T>
	{
		private T input;

		private IClock clock;

		private TimeSpan timeout = DefaultSleepTimeout;

		private TimeSpan sleepInterval = DefaultSleepTimeout;

		private string message = string.Empty;

		private List<Type> ignoredExceptions = new List<Type>();

		public TimeSpan Timeout
		{
			get
			{
				return timeout;
			}
			set
			{
				timeout = value;
			}
		}

		public TimeSpan PollingInterval
		{
			get
			{
				return sleepInterval;
			}
			set
			{
				sleepInterval = value;
			}
		}

		public string Message
		{
			get
			{
				return message;
			}
			set
			{
				message = value;
			}
		}

		private static TimeSpan DefaultSleepTimeout => TimeSpan.FromMilliseconds(500.0);

		public DefaultWait(T input)
			: this(input, (IClock)new SystemClock())
		{
		}

		public DefaultWait(T input, IClock clock)
		{
			if (input == null)
			{
				throw new ArgumentNullException("input", "input cannot be null");
			}
			if (clock == null)
			{
				throw new ArgumentNullException("clock", "clock cannot be null");
			}
			this.input = input;
			this.clock = clock;
		}

		public void IgnoreExceptionTypes(params Type[] exceptionTypes)
		{
			if (exceptionTypes == null)
			{
				throw new ArgumentNullException("exceptionTypes", "exceptionTypes cannot be null");
			}
			foreach (Type c in exceptionTypes)
			{
				if (!typeof(Exception).IsAssignableFrom(c))
				{
					throw new ArgumentException("All types to be ignored must derive from System.Exception", "exceptionTypes");
				}
			}
			ignoredExceptions.AddRange(exceptionTypes);
		}

		public TResult Until<TResult>(Func<T, TResult> condition)
		{
			if (condition == null)
			{
				throw new ArgumentNullException("condition", "condition cannot be null");
			}
			Type typeFromHandle = typeof(TResult);
			if ((typeFromHandle.IsValueType && typeFromHandle != typeof(bool)) || !typeof(object).IsAssignableFrom(typeFromHandle))
			{
				throw new ArgumentException("Can only wait on an object or boolean response, tried to use type: " + typeFromHandle.ToString(), "condition");
			}
			Exception lastException = null;
			DateTime otherDateTime = clock.LaterBy(timeout);
			while (true)
			{
				try
				{
					TResult val = condition(input);
					if (typeFromHandle == typeof(bool))
					{
						bool? flag = val as bool?;
						if (flag.HasValue && flag.Value)
						{
							return val;
						}
					}
					else if (val != null)
					{
						return val;
					}
				}
				catch (Exception ex)
				{
					if (!IsIgnoredException(ex))
					{
						throw;
					}
					lastException = ex;
				}
				if (!clock.IsNowBefore(otherDateTime))
				{
					string text = string.Format(CultureInfo.InvariantCulture, "Timed out after {0} seconds", new object[1] { timeout.TotalSeconds });
					if (!string.IsNullOrEmpty(message))
					{
						text = text + ": " + message;
					}
					ThrowTimeoutException(text, lastException);
				}
				Thread.Sleep(sleepInterval);
			}
		}

		protected virtual void ThrowTimeoutException(string exceptionMessage, Exception lastException)
		{
			throw new WebDriverTimeoutException(exceptionMessage, lastException);
		}

		private bool IsIgnoredException(Exception exception)
		{
			return ignoredExceptions.Any((Type type) => type.IsAssignableFrom(exception.GetType()));
		}
	}
	public interface IClock
	{
		DateTime Now { get; }

		DateTime LaterBy(TimeSpan delay);

		bool IsNowBefore(DateTime otherDateTime);
	}
	public interface IWait<T>
	{
		TimeSpan Timeout { get; set; }

		TimeSpan PollingInterval { get; set; }

		string Message { get; set; }

		void IgnoreExceptionTypes(params Type[] exceptionTypes);

		TResult Until<TResult>(Func<T, TResult> condition);
	}
	public class SystemClock : IClock
	{
		public DateTime Now => DateTime.Now;

		public DateTime LaterBy(TimeSpan delay)
		{
			return DateTime.Now.Add(delay);
		}

		public bool IsNowBefore(DateTime otherDateTime)
		{
			return DateTime.Now < otherDateTime;
		}
	}
	public class WebDriverWait : DefaultWait<IWebDriver>
	{
		private static TimeSpan DefaultSleepTimeout => TimeSpan.FromMilliseconds(500.0);

		public WebDriverWait(IWebDriver driver, TimeSpan timeout)
			: this(new SystemClock(), driver, timeout, DefaultSleepTimeout)
		{
		}

		public WebDriverWait(IClock clock, IWebDriver driver, TimeSpan timeout, TimeSpan sleepInterval)
			: base(driver, clock)
		{
			base.Timeout = timeout;
			base.PollingInterval = sleepInterval;
			IgnoreExceptionTypes(typeof(NotFoundException));
		}
	}
