	public sealed class SafariDriverService : DriverService
	{
		private const string DefaultSafariDriverServiceExecutableName = "safaridriver";

		private const string DefaultSafariDriverServiceExecutablePath = "/usr/bin";

		private static readonly Uri SafariDriverDownloadUrl = new Uri("http://apple.com");

		private bool useLegacyProtocol;

		public bool UseLegacyProtocol
		{
			get
			{
				return useLegacyProtocol;
			}
			set
			{
				useLegacyProtocol = value;
			}
		}

		protected override string CommandLineArguments
		{
			get
			{
				StringBuilder stringBuilder = new StringBuilder(base.CommandLineArguments);
				if (useLegacyProtocol)
				{
					stringBuilder.Append(" --legacy");
				}
				return stringBuilder.ToString();
			}
		}

		protected override TimeSpan TerminationTimeout => TimeSpan.FromMilliseconds(100.0);

		protected override bool HasShutdown => false;

		protected override bool IsInitialized
		{
			get
			{
				bool result = false;
				try
				{
					HttpWebRequest obj = WebRequest.Create(new Uri(base.ServiceUrl, new Uri("/session/FakeSessionIdForPollingPurposes", UriKind.Relative))) as HttpWebRequest;
					obj.KeepAlive = false;
					obj.Timeout = 5000;
					obj.Method = "DELETE";
					HttpWebResponse httpWebResponse = obj.GetResponse() as HttpWebResponse;
					result = httpWebResponse.StatusCode == HttpStatusCode.OK && httpWebResponse.ContentType.StartsWith("application/json", StringComparison.OrdinalIgnoreCase);
					httpWebResponse.Close();
				}
				catch (WebException ex)
				{
					if (ex.Response is HttpWebResponse httpWebResponse2)
					{
						result = (httpWebResponse2.StatusCode == HttpStatusCode.InternalServerError && httpWebResponse2.ContentType.StartsWith("application/json", StringComparison.OrdinalIgnoreCase)) || httpWebResponse2.StatusCode == HttpStatusCode.NotFound;
					}
					else
					{
						Console.WriteLine(ex.Message);
					}
				}
				return result;
			}
		}

		private SafariDriverService(string executablePath, string executableFileName, int port)
			: base(executablePath, port, executableFileName, SafariDriverDownloadUrl)
		{
		}

