	public class AsyncJavaScriptExecutor
	{
		private const string AsyncScriptTemplate = "document.__$webdriverPageId = '{0}';\r\nvar timeoutId = window.setTimeout(function() {{\r\n  window.setTimeout(function() {{\r\n    document.__$webdriverAsyncTimeout = 1;\r\n  }}, 0);\r\n}}, {1});\r\ndocument.__$webdriverAsyncTimeout = 0;\r\nvar callback = function(value) {{\r\n  document.__$webdriverAsyncTimeout = 0;\r\n  document.__$webdriverAsyncScriptResult = value;\r\n  window.clearTimeout(timeoutId);\r\n}};\r\nvar argsArray = Array.prototype.slice.call(arguments);\r\nargsArray.push(callback);\r\nif (document.__$webdriverAsyncScriptResult !== undefined) {{\r\n  delete document.__$webdriverAsyncScriptResult;\r\n}}\r\n(function() {{\r\n{2}\r\n}}).apply(null, argsArray);";

		private const string PollingScriptTemplate = "var pendingId = '{0}';\r\nif (document.__$webdriverPageId != '{1}') {{\r\n  return [pendingId, -1];\r\n}} else if ('__$webdriverAsyncScriptResult' in document) {{\r\n  var value = document.__$webdriverAsyncScriptResult;\r\n  delete document.__$webdriverAsyncScriptResult;\r\n  return value;\r\n}} else {{\r\n  return [pendingId, document.__$webdriverAsyncTimeout];\r\n}}\r\n";

		private IJavaScriptExecutor executor;

		private TimeSpan timeout = TimeSpan.FromMilliseconds(0.0);

		public TimeSpan Timeout
		{
			get
			{
				return timeout;
			}
			set
			{
				timeout = value;
			}
		}

		public AsyncJavaScriptExecutor(IJavaScriptExecutor executor)
		{
			this.executor = executor;
		}

		public object ExecuteScript(string script, object[] args)
		{
			string text = Guid.NewGuid().ToString();
			string script2 = string.Format(CultureInfo.InvariantCulture, "document.__$webdriverPageId = '{0}';\r\nvar timeoutId = window.setTimeout(function() {{\r\n  window.setTimeout(function() {{\r\n    document.__$webdriverAsyncTimeout = 1;\r\n  }}, 0);\r\n}}, {1});\r\ndocument.__$webdriverAsyncTimeout = 0;\r\nvar callback = function(value) {{\r\n  document.__$webdriverAsyncTimeout = 0;\r\n  document.__$webdriverAsyncScriptResult = value;\r\n  window.clearTimeout(timeoutId);\r\n}};\r\nvar argsArray = Array.prototype.slice.call(arguments);\r\nargsArray.push(callback);\r\nif (document.__$webdriverAsyncScriptResult !== undefined) {{\r\n  delete document.__$webdriverAsyncScriptResult;\r\n}}\r\n(function() {{\r\n{2}\r\n}}).apply(null, argsArray);", new object[3] { text, timeout.TotalMilliseconds, script });
			string text2 = Guid.NewGuid().ToString();
			string script3 = string.Format(CultureInfo.InvariantCulture, "var pendingId = '{0}';\r\nif (document.__$webdriverPageId != '{1}') {{\r\n  return [pendingId, -1];\r\n}} else if ('__$webdriverAsyncScriptResult' in document) {{\r\n  var value = document.__$webdriverAsyncScriptResult;\r\n  delete document.__$webdriverAsyncScriptResult;\r\n  return value;\r\n}} else {{\r\n  return [pendingId, document.__$webdriverAsyncTimeout];\r\n}}\r\n", new object[2] { text2, text });
			DateTime now = DateTime.Now;
			executor.ExecuteScript(script2, args);
			object obj;
			while (true)
			{
				obj = executor.ExecuteScript(script3);
				if (!(obj is ReadOnlyCollection<object> { Count: 2 } readOnlyCollection) || !(text2 == readOnlyCollection[0].ToString()))
				{
					break;
				}
				long num = (long)readOnlyCollection[1];
				if (num < 0)
				{
					throw new WebDriverException("Detected a new page load while waiting for async script result.\nScript: " + script);
				}
				TimeSpan timeSpan = DateTime.Now - now;
				if (num > 0)
				{
					throw new WebDriverTimeoutException("Timed out waiting for async script callback.\nElapsed time: " + timeSpan.Milliseconds + "milliseconds\nScript: " + script);
				}
				Thread.Sleep(100);
			}
			return obj;
		}
	}
	internal static class FileUtilities
	{
		public static bool CopyDirectory(string sourceDirectory, string destinationDirectory)
		{
			DirectoryInfo directoryInfo = new DirectoryInfo(sourceDirectory);
			DirectoryInfo directoryInfo2 = new DirectoryInfo(destinationDirectory);
			if (directoryInfo.Exists)
			{
				if (!directoryInfo2.Exists)
				{
					directoryInfo2.Create();
				}
				FileInfo[] files = directoryInfo.GetFiles();
				foreach (FileInfo fileInfo in files)
				{
					fileInfo.CopyTo(Path.Combine(directoryInfo2.FullName, fileInfo.Name));
				}
				DirectoryInfo[] directories = directoryInfo.GetDirectories();
				foreach (DirectoryInfo directoryInfo3 in directories)
				{
					CopyDirectory(directoryInfo3.FullName, Path.Combine(directoryInfo2.FullName, directoryInfo3.Name));
				}
			}
			return true;
		}

		public static void DeleteDirectory(string directoryToDelete)
		{
			int num = 0;
			while (Directory.Exists(directoryToDelete) && num < 10)
			{
				try
				{
					Directory.Delete(directoryToDelete, recursive: true);
				}
				catch (IOException)
				{
					Thread.Sleep(500);
				}
				catch (UnauthorizedAccessException)
				{
					Thread.Sleep(500);
				}
				finally
				{
					num++;
				}
			}
			if (Directory.Exists(directoryToDelete))
			{
				Console.WriteLine("Unable to delete directory '{0}'", directoryToDelete);
			}
		}

		public static string FindFile(string fileName)
		{
			string currentDirectory = GetCurrentDirectory();
			if (File.Exists(Path.Combine(currentDirectory, fileName)))
			{
				return currentDirectory;
			}
			string environmentVariable = Environment.GetEnvironmentVariable("PATH");
			if (!string.IsNullOrEmpty(environmentVariable))
			{
				string[] array = Environment.ExpandEnvironmentVariables(environmentVariable).Split(new char[1] { Path.PathSeparator });
				foreach (string text in array)
				{
					if (text.IndexOfAny(Path.GetInvalidPathChars()) < 0 && File.Exists(Path.Combine(text, fileName)))
					{
						return text;
					}
				}
			}
			return string.Empty;
		}

		public static string GetCurrentDirectory()
		{
			Assembly assembly = typeof(FileUtilities).Assembly;
			string text = Path.GetDirectoryName(assembly.Location);
			if (string.IsNullOrEmpty(text))
			{
				text = Directory.GetCurrentDirectory();
			}
			string result = text;
			if (AppDomain.CurrentDomain.ShadowCopyFiles)
			{
				result = Path.GetDirectoryName(new Uri(assembly.CodeBase).LocalPath);
			}
			return result;
		}

		public static string GenerateRandomTempDirectoryName(string directoryPattern)
		{
			string path = string.Format(CultureInfo.InvariantCulture, directoryPattern, new object[1] { Guid.NewGuid().ToString("N") });
			return Path.Combine(Path.GetTempPath(), path);
		}
	}
