	internal static class PortUtilities
	{
		public static int FindFreePort()
		{
			int num = 0;
			Socket socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
			try
			{
				IPEndPoint localEP = new IPEndPoint(IPAddress.Any, 0);
				socket.Bind(localEP);
				localEP = (IPEndPoint)socket.LocalEndPoint;
				return localEP.Port;
			}
			finally
			{
				socket.Close();
			}
		}
	}
	public static class ResourceUtilities
	{
		private static string assemblyVersion;

		private static string platformFamily;

		public static string AssemblyVersion
		{
			get
			{
				if (string.IsNullOrEmpty(assemblyVersion))
				{
					Version version = Assembly.GetCallingAssembly().GetName().Version;
					assemblyVersion = string.Format(CultureInfo.InvariantCulture, "{0}.{1}.{2}", new object[3] { version.Major, version.Minor, version.Revision });
				}
				return assemblyVersion;
			}
		}

		public static string PlatformFamily
		{
			get
			{
				if (string.IsNullOrEmpty(platformFamily))
				{
					platformFamily = GetPlatformString();
				}
				return platformFamily;
			}
		}

		public static Stream GetResourceStream(string fileName, string resourceId)
		{
			Stream stream = null;
			string text = Path.Combine(FileUtilities.GetCurrentDirectory(), Path.GetFileName(fileName));
			if (File.Exists(text))
			{
				stream = new FileStream(text, FileMode.Open, FileAccess.Read);
			}
			else if (File.Exists(fileName))
			{
				stream = new FileStream(fileName, FileMode.Open, FileAccess.Read);
			}
			else
			{
				if (string.IsNullOrEmpty(resourceId))
				{
					throw new WebDriverException("The file specified does not exist, and you have specified no internal resource ID");
				}
				stream = Assembly.GetCallingAssembly().GetManifestResourceStream(resourceId);
			}
			if (stream == null)
			{
				throw new WebDriverException(string.Format(CultureInfo.InvariantCulture, "Cannot find a file named '{0}' or an embedded resource with the id '{1}'.", new object[2] { text, resourceId }));
			}
			return stream;
		}

		public static bool IsValidResourceName(string resourceId)
		{
			return new List<string>(Assembly.GetCallingAssembly().GetManifestResourceNames()).Contains(resourceId);
		}

		private static string GetPlatformString()
		{
			string result = "unknown";
			switch (Environment.OSVersion.Platform)
			{
			case PlatformID.Unix:
			case PlatformID.MacOSX:
			case (PlatformID)128:
			{
				using (Process process = new Process())
				{
					process.StartInfo.FileName = "uname";
					process.StartInfo.UseShellExecute = false;
					process.StartInfo.RedirectStandardOutput = true;
					process.Start();
					process.WaitForExit(1000);
					result = ((!process.StandardOutput.ReadToEnd().ToLowerInvariant().StartsWith("darwin")) ? "linux" : "mac");
				}
				break;
			}
			case PlatformID.Win32S:
			case PlatformID.Win32Windows:
			case PlatformID.Win32NT:
			case PlatformID.WinCE:
				result = "windows";
				break;
			}
			return result;
		}
	}
	internal class ReturnedCapabilities : ICapabilities, IHasCapabilitiesDictionary
	{
		private readonly Dictionary<string, object> capabilities = new Dictionary<string, object>();

		public string BrowserName
		{
			get
			{
				string result = string.Empty;
				object capability = GetCapability(CapabilityType.BrowserName);
				if (capability != null)
				{
					result = capability.ToString();
				}
				return result;
			}
		}

		public object this[string capabilityName]
		{
			get
			{
				if (!capabilities.ContainsKey(capabilityName))
				{
					throw new ArgumentException(string.Format(CultureInfo.InvariantCulture, "The capability {0} is not present in this set of capabilities", new object[1] { capabilityName }));
				}
				return capabilities[capabilityName];
			}
		}

		Dictionary<string, object> IHasCapabilitiesDictionary.CapabilitiesDictionary => CapabilitiesDictionary;

		internal Dictionary<string, object> CapabilitiesDictionary => capabilities;

		public ReturnedCapabilities()
		{
		}

		public ReturnedCapabilities(Dictionary<string, object> rawMap)
		{
			if (rawMap == null)
			{
				return;
			}
			foreach (string key in rawMap.Keys)
			{
				capabilities[key] = rawMap[key];
			}
		}

		public bool HasCapability(string capability)
		{
			return capabilities.ContainsKey(capability);
		}

		public object GetCapability(string capability)
		{
			object result = null;
			if (capabilities.ContainsKey(capability))
			{
				result = capabilities[capability];
			}
			return result;
		}

		public Dictionary<string, object> ToDictionary()
		{
			return capabilities;
		}

		public override string ToString()
		{
			return JsonConvert.SerializeObject(capabilities, Newtonsoft.Json.Formatting.Indented);
		}
	}
	public class ReturnedCookie : Cookie
	{
		private bool isSecure;

		private bool isHttpOnly;

		public override bool Secure => isSecure;

		public override bool IsHttpOnly => isHttpOnly;

		public ReturnedCookie(string name, string value, string domain, string path, DateTime? expiry, bool isSecure, bool isHttpOnly)
			: base(name, value, domain, path, expiry)
		{
			this.isSecure = isSecure;
			this.isHttpOnly = isHttpOnly;
		}

		public override string ToString()
		{
			return base.Name + "=" + base.Value + ((!base.Expiry.HasValue) ? string.Empty : ("; expires=" + base.Expiry.Value.ToUniversalTime().ToString("ddd MM/dd/yyyy HH:mm:ss UTC", CultureInfo.InvariantCulture))) + (string.IsNullOrEmpty(Path) ? string.Empty : ("; path=" + Path)) + (string.IsNullOrEmpty(base.Domain) ? string.Empty : ("; domain=" + base.Domain)) + (isSecure ? "; secure" : string.Empty) + (isHttpOnly ? "; httpOnly" : string.Empty);
		}
	}
