namespace OpenQA.Selenium.Interactions
{
	public class ActionBuilder
	{
		private Dictionary<InputDevice, ActionSequence> sequences = new Dictionary<InputDevice, ActionSequence>();

		public ActionBuilder AddAction(Interaction actionToAdd)
		{
			AddActions(actionToAdd);
			return this;
		}

		public ActionBuilder AddActions(params Interaction[] actionsToAdd)
		{
			ProcessTick(actionsToAdd);
			return this;
		}

		public IList<ActionSequence> ToActionSequenceList()
		{
			return new List<ActionSequence>(sequences.Values).AsReadOnly();
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			foreach (ActionSequence value in sequences.Values)
			{
				stringBuilder.AppendLine(value.ToString());
			}
			return stringBuilder.ToString();
		}

		private void ProcessTick(params Interaction[] interactionsToAdd)
		{
			List<InputDevice> list = new List<InputDevice>();
			Interaction[] array = interactionsToAdd;
			for (int i = 0; i < array.Length; i++)
			{
				InputDevice sourceDevice = array[i].SourceDevice;
				if (list.Contains(sourceDevice))
				{
					throw new ArgumentException("You can only add one action per device for a single tick.");
				}
			}
			List<InputDevice> list2 = new List<InputDevice>(sequences.Keys);
			array = interactionsToAdd;
			foreach (Interaction interaction in array)
			{
				FindSequence(interaction.SourceDevice).AddAction(interaction);
				list2.Remove(interaction.SourceDevice);
			}
			foreach (InputDevice item in list2)
			{
				sequences[item].AddAction(new PauseInteraction(item, TimeSpan.Zero));
			}
		}

		private ActionSequence FindSequence(InputDevice device)
		{
			if (sequences.ContainsKey(device))
			{
				return sequences[device];
			}
			int num = 0;
			foreach (KeyValuePair<InputDevice, ActionSequence> sequence in sequences)
			{
				num = Math.Max(num, sequence.Value.Count);
			}
			ActionSequence actionSequence = new ActionSequence(device, num);
			sequences[device] = actionSequence;
			return actionSequence;
		}
	}
	public enum MoveToElementOffsetOrigin
	{
		TopLeft,
		Center
	}
	public class Actions : IAction
	{
		private readonly TimeSpan DefaultMouseMoveDuration = TimeSpan.FromMilliseconds(250.0);

		private ActionBuilder actionBuilder = new ActionBuilder();

		private PointerInputDevice defaultMouse = new PointerInputDevice(PointerKind.Mouse, "default mouse");

		private KeyInputDevice defaultKeyboard = new KeyInputDevice("default keyboard");

		private IKeyboard keyboard;

		private IMouse mouse;

		private IActionExecutor actionExecutor;

		private CompositeAction action = new CompositeAction();

		public Actions(IWebDriver driver)
		{
			IHasInputDevices driverAs = GetDriverAs<IHasInputDevices>(driver);
			if (driverAs == null)
			{
				throw new ArgumentException("The IWebDriver object must implement or wrap a driver that implements IHasInputDevices.", "driver");
			}
			IActionExecutor driverAs2 = GetDriverAs<IActionExecutor>(driver);
			if (driverAs2 == null)
			{
				throw new ArgumentException("The IWebDriver object must implement or wrap a driver that implements IActionExecutor.", "driver");
			}
			keyboard = driverAs.Keyboard;
			mouse = driverAs.Mouse;
			actionExecutor = driverAs2;
		}

		public Actions KeyDown(string theKey)
		{
			return KeyDown(null, theKey);
		}

		public Actions KeyDown(IWebElement element, string theKey)
		{
			if (string.IsNullOrEmpty(theKey))
			{
				throw new ArgumentException("The key value must not be null or empty", "theKey");
			}
			ILocatable locatableFromElement = GetLocatableFromElement(element);
			action.AddAction(new KeyDownAction(keyboard, mouse, locatableFromElement, theKey));
			if (element != null)
			{
				actionBuilder.AddAction(defaultMouse.CreatePointerMove(element, 0, 0, DefaultMouseMoveDuration));
				actionBuilder.AddAction(defaultMouse.CreatePointerDown(MouseButton.Left));
				actionBuilder.AddAction(defaultMouse.CreatePointerUp(MouseButton.Left));
			}
			actionBuilder.AddAction(defaultKeyboard.CreateKeyDown(theKey[0]));
			actionBuilder.AddAction(new PauseInteraction(defaultKeyboard, TimeSpan.FromMilliseconds(100.0)));
			return this;
		}

		public Actions KeyUp(string theKey)
		{
			return KeyUp(null, theKey);
		}

		public Actions KeyUp(IWebElement element, string theKey)
		{
			if (string.IsNullOrEmpty(theKey))
			{
				throw new ArgumentException("The key value must not be null or empty", "theKey");
			}
			ILocatable locatableFromElement = GetLocatableFromElement(element);
			action.AddAction(new KeyUpAction(keyboard, mouse, locatableFromElement, theKey));
			if (element != null)
			{
				actionBuilder.AddAction(defaultMouse.CreatePointerMove(element, 0, 0, DefaultMouseMoveDuration));
				actionBuilder.AddAction(defaultMouse.CreatePointerDown(MouseButton.Left));
				actionBuilder.AddAction(defaultMouse.CreatePointerUp(MouseButton.Left));
			}
			actionBuilder.AddAction(defaultKeyboard.CreateKeyUp(theKey[0]));
			return this;
		}

		public Actions SendKeys(string keysToSend)
		{
			return SendKeys(null, keysToSend);
		}

		public Actions SendKeys(IWebElement element, string keysToSend)
		{
			if (string.IsNullOrEmpty(keysToSend))
			{
				throw new ArgumentException("The key value must not be null or empty", "keysToSend");
			}
			ILocatable locatableFromElement = GetLocatableFromElement(element);
			action.AddAction(new SendKeysAction(keyboard, mouse, locatableFromElement, keysToSend));
			if (element != null)
			{
				actionBuilder.AddAction(defaultMouse.CreatePointerMove(element, 0, 0, DefaultMouseMoveDuration));
				actionBuilder.AddAction(defaultMouse.CreatePointerDown(MouseButton.Left));
				actionBuilder.AddAction(defaultMouse.CreatePointerUp(MouseButton.Left));
			}
			foreach (char codePoint in keysToSend)
			{
				actionBuilder.AddAction(defaultKeyboard.CreateKeyDown(codePoint));
				actionBuilder.AddAction(defaultKeyboard.CreateKeyUp(codePoint));
			}
			return this;
		}

		public Actions ClickAndHold(IWebElement onElement)
		{
			MoveToElement(onElement).ClickAndHold();
			return this;
		}

		public Actions ClickAndHold()
		{
			action.AddAction(new ClickAndHoldAction(mouse, null));
			actionBuilder.AddAction(defaultMouse.CreatePointerDown(MouseButton.Left));
			return this;
		}

		public Actions Release(IWebElement onElement)
		{
			MoveToElement(onElement).Release();
			return this;
		}

		public Actions Release()
		{
			action.AddAction(new ButtonReleaseAction(mouse, null));
			actionBuilder.AddAction(defaultMouse.CreatePointerUp(MouseButton.Left));
			return this;
		}

		public Actions Click(IWebElement onElement)
		{
			MoveToElement(onElement).Click();
			return this;
		}

		public Actions Click()
		{
			action.AddAction(new ClickAction(mouse, null));
			actionBuilder.AddAction(defaultMouse.CreatePointerDown(MouseButton.Left));
			actionBuilder.AddAction(defaultMouse.CreatePointerUp(MouseButton.Left));
			return this;
		}

		public Actions DoubleClick(IWebElement onElement)
		{
			MoveToElement(onElement).DoubleClick();
			return this;
		}

		public Actions DoubleClick()
		{
			action.AddAction(new DoubleClickAction(mouse, null));
			actionBuilder.AddAction(defaultMouse.CreatePointerDown(MouseButton.Left));
			actionBuilder.AddAction(defaultMouse.CreatePointerUp(MouseButton.Left));
			actionBuilder.AddAction(defaultMouse.CreatePointerDown(MouseButton.Left));
			actionBuilder.AddAction(defaultMouse.CreatePointerUp(MouseButton.Left));
			return this;
		}

		public Actions MoveToElement(IWebElement toElement)
		{
			if (toElement == null)
			{
				throw new ArgumentException("MoveToElement cannot move to a null element with no offset.", "toElement");
			}
			ILocatable locatableFromElement = GetLocatableFromElement(toElement);
			action.AddAction(new MoveMouseAction(mouse, locatableFromElement));
			actionBuilder.AddAction(defaultMouse.CreatePointerMove(toElement, 0, 0, DefaultMouseMoveDuration));
			return this;
		}

		public Actions MoveToElement(IWebElement toElement, int offsetX, int offsetY)
		{
			return MoveToElement(toElement, offsetX, offsetY, MoveToElementOffsetOrigin.TopLeft);
		}

		public Actions MoveToElement(IWebElement toElement, int offsetX, int offsetY, MoveToElementOffsetOrigin offsetOrigin)
		{
			ILocatable locatableFromElement = GetLocatableFromElement(toElement);
			Size size = toElement.Size;
			_ = toElement.Location;
			if (offsetOrigin == MoveToElementOffsetOrigin.TopLeft)
			{
				int xOffset = offsetX - size.Width / 2;
				int yOffset = offsetY - size.Height / 2;
				action.AddAction(new MoveToOffsetAction(mouse, locatableFromElement, offsetX, offsetY));
				actionBuilder.AddAction(defaultMouse.CreatePointerMove(toElement, xOffset, yOffset, DefaultMouseMoveDuration));
			}
			else
			{
				int offsetX2 = offsetX + size.Width / 2;
				int offsetY2 = offsetY + size.Height / 2;
				action.AddAction(new MoveToOffsetAction(mouse, locatableFromElement, offsetX2, offsetY2));
				actionBuilder.AddAction(defaultMouse.CreatePointerMove(toElement, offsetX, offsetY, DefaultMouseMoveDuration));
			}
			return this;
		}

		public Actions MoveByOffset(int offsetX, int offsetY)
		{
			action.AddAction(new MoveToOffsetAction(mouse, null, offsetX, offsetY));
			actionBuilder.AddAction(defaultMouse.CreatePointerMove(CoordinateOrigin.Pointer, offsetX, offsetY, DefaultMouseMoveDuration));
			return this;
		}

		public Actions ContextClick(IWebElement onElement)
		{
			MoveToElement(onElement).ContextClick();
			return this;
		}

		public Actions ContextClick()
		{
			action.AddAction(new ContextClickAction(mouse, null));
			actionBuilder.AddAction(defaultMouse.CreatePointerDown(MouseButton.Right));
			actionBuilder.AddAction(defaultMouse.CreatePointerUp(MouseButton.Right));
			return this;
		}

		public Actions DragAndDrop(IWebElement source, IWebElement target)
		{
			ClickAndHold(source).MoveToElement(target).Release(target);
			return this;
		}

		public Actions DragAndDropToOffset(IWebElement source, int offsetX, int offsetY)
		{
			ClickAndHold(source).MoveByOffset(offsetX, offsetY).Release();
			return this;
		}

		public IAction Build()
		{
			return this;
		}

		public void Perform()
		{
			if (actionExecutor.IsActionExecutor)
			{
				actionExecutor.PerformActions(actionBuilder.ToActionSequenceList());
			}
			else
			{
				action.Perform();
			}
		}

		protected static ILocatable GetLocatableFromElement(IWebElement element)
		{
			if (element == null)
			{
				return null;
			}
			ILocatable locatable = null;
			for (IWrapsElement wrapsElement = element as IWrapsElement; wrapsElement != null; wrapsElement = wrapsElement.WrappedElement as IWrapsElement)
			{
				locatable = wrapsElement.WrappedElement as ILocatable;
			}
			if (locatable == null)
			{
				locatable = element as ILocatable;
			}
			if (locatable == null)
			{
				throw new ArgumentException("The IWebElement object must implement or wrap an element that implements ILocatable.", "element");
			}
			return locatable;
		}

		protected void AddAction(IAction actionToAdd)
		{
			action.AddAction(actionToAdd);
		}

		private T GetDriverAs<T>(IWebDriver driver) where T : class
		{
			T val = driver as T;
			if (val == null)
			{
				for (IWrapsDriver wrapsDriver = driver as IWrapsDriver; wrapsDriver != null; wrapsDriver = wrapsDriver.WrappedDriver as IWrapsDriver)
				{
					val = wrapsDriver.WrappedDriver as T;
					if (val != null)
					{
						driver = wrapsDriver.WrappedDriver;
						break;
					}
				}
			}
			return val;
		}
	}
	public class ActionSequence
	{
		private List<Interaction> interactions = new List<Interaction>();

		private InputDevice device;

		public int Count => interactions.Count;

		public ActionSequence(InputDevice device)
			: this(device, 0)
		{
		}

		public ActionSequence(InputDevice device, int initialSize)
		{
			if (device == null)
			{
				throw new ArgumentNullException("device", "Input device cannot be null.");
			}
			this.device = device;
			for (int i = 0; i < initialSize; i++)
			{
				AddAction(new PauseInteraction(device, TimeSpan.Zero));
			}
		}

		public ActionSequence AddAction(Interaction interactionToAdd)
		{
			if (interactionToAdd == null)
			{
				throw new ArgumentNullException("interactionToAdd", "Interaction to add to sequence must not be null");
			}
			if (!interactionToAdd.IsValidFor(device.DeviceKind))
			{
				throw new ArgumentException(string.Format(CultureInfo.InvariantCulture, "Interaction {0} is invalid for device type {1}.", new object[2]
				{
					interactionToAdd.GetType(),
					device.DeviceKind
				}), "interactionToAdd");
			}
			interactions.Add(interactionToAdd);
			return this;
		}

		public Dictionary<string, object> ToDictionary()
		{
			Dictionary<string, object> dictionary = device.ToDictionary();
			List<object> list = new List<object>();
			foreach (Interaction interaction in interactions)
			{
				list.Add(interaction.ToDictionary());
			}
			dictionary["actions"] = list;
			return dictionary;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder("Action sequence - ").Append(device.ToString());
			foreach (Interaction interaction in interactions)
			{
				stringBuilder.AppendLine();
				stringBuilder.AppendFormat("    {0}", interaction.ToString());
			}
			return stringBuilder.ToString();
		}
	}
