	public abstract class InputDevice
	{
		private string deviceName;

		public string DeviceName => deviceName;

		public abstract InputDeviceKind DeviceKind { get; }

		protected InputDevice(string deviceName)
		{
			if (string.IsNullOrEmpty(deviceName))
			{
				throw new ArgumentException("Device name must not be null or empty", "deviceName");
			}
			this.deviceName = deviceName;
		}

		public abstract Dictionary<string, object> ToDictionary();

		public Interaction CreatePause()
		{
			return CreatePause(TimeSpan.Zero);
		}

		public Interaction CreatePause(TimeSpan duration)
		{
			return new PauseInteraction(this, duration);
		}

		public override int GetHashCode()
		{
			return deviceName.GetHashCode();
		}

		public override string ToString()
		{
			return string.Format(CultureInfo.InvariantCulture, "{0} input device [name: {1}]", new object[2] { DeviceKind, deviceName });
		}
	}
	public enum InputDeviceKind
	{
		None,
		Key,
		Pointer
	}
	public abstract class Interaction
	{
		private InputDevice sourceDevice;

		public InputDevice SourceDevice => sourceDevice;

		protected Interaction(InputDevice sourceDevice)
		{
			if (sourceDevice == null)
			{
				throw new ArgumentNullException("sourceDevice", "Source device cannot be null");
			}
			this.sourceDevice = sourceDevice;
		}

		public abstract Dictionary<string, object> ToDictionary();

		public virtual bool IsValidFor(InputDeviceKind sourceDeviceKind)
		{
			return sourceDevice.DeviceKind == sourceDeviceKind;
		}
	}
