		protected override Dictionary<string, object> GetLegacyCapabilitiesDictionary(ICapabilities legacyCapabilities)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			foreach (KeyValuePair<string, object> item in (legacyCapabilities as IHasCapabilitiesDictionary).CapabilitiesDictionary)
			{
				if (item.Key == InternetExplorerOptions.Capability)
				{
					foreach (KeyValuePair<string, object> item2 in item.Value as Dictionary<string, object>)
					{
						dictionary.Add(item2.Key, item2.Value);
					}
				}
				else
				{
					dictionary.Add(item.Key, item.Value);
				}
			}
			return dictionary;
		}

		private static ICapabilities ConvertOptionsToCapabilities(InternetExplorerOptions options)
		{
			if (options == null)
			{
				throw new ArgumentNullException("options", "options must not be null");
			}
			return options.ToCapabilities();
		}
