				}
				if (!string.IsNullOrEmpty(logFile))
				{
					stringBuilder.Append(string.Format(CultureInfo.InvariantCulture, " -log-file={0}", new object[1] { logFile }));
				}
				if (!string.IsNullOrEmpty(libraryExtractionPath))
				{
					stringBuilder.Append(string.Format(CultureInfo.InvariantCulture, " -extract-path={0}", new object[1] { libraryExtractionPath }));
				}
				if (loggingLevel != InternetExplorerDriverLogLevel.Fatal)
				{
					stringBuilder.Append(string.Format(CultureInfo.InvariantCulture, " -log-level={0}", new object[1] { loggingLevel.ToString().ToUpperInvariant() }));
				}
				if (!string.IsNullOrEmpty(whitelistedIpAddresses))
				{
					stringBuilder.Append(string.Format(CultureInfo.InvariantCulture, " -whitelisted-ips={0}", new object[1] { whitelistedIpAddresses }));
				}
				if (base.SuppressInitialDiagnosticInformation)
				{
					stringBuilder.Append(" -silent");
				}
				return stringBuilder.ToString();
			}
		}

