		public InternetExplorerOptions()
		{
			base.BrowserName = "internet explorer";
			base.PlatformName = "windows";
			AddKnownCapabilityName(Capability, "current InterentExplorerOptions class instance");
			AddKnownCapabilityName("ignoreProtectedModeSettings", "IntroduceInstabilityByIgnoringProtectedModeSettings property");
			AddKnownCapabilityName("ignoreZoomSetting", "IgnoreZoomLevel property");
			AddKnownCapabilityName(CapabilityType.HasNativeEvents, "EnableNativeEvents property");
			AddKnownCapabilityName("initialBrowserUrl", "InitialBrowserUrl property");
			AddKnownCapabilityName("elementScrollBehavior", "ElementScrollBehavior property");
			AddKnownCapabilityName(CapabilityType.UnexpectedAlertBehavior, "UnhandledPromptBehavior property");
			AddKnownCapabilityName("enablePersistentHover", "EnablePersistentHover property");
			AddKnownCapabilityName("requireWindowFocus", "RequireWindowFocus property");
			AddKnownCapabilityName("browserAttachTimeout", "BrowserAttachTimeout property");
			AddKnownCapabilityName("ie.forceCreateProcessApi", "ForceCreateProcessApi property");
			AddKnownCapabilityName("ie.forceShellWindowsApi", "ForceShellWindowsApi property");
			AddKnownCapabilityName("ie.browserCommandLineSwitches", "BrowserComaandLineArguments property");
			AddKnownCapabilityName("ie.usePerProcessProxy", "UsePerProcessProxy property");
			AddKnownCapabilityName("ie.ensureCleanSession", "EnsureCleanSession property");
			AddKnownCapabilityName("ie.fileUploadDialogTimeout", "FileUploadDialogTimeout property");
			AddKnownCapabilityName("ie.enableFullPageScreenshot", "EnableFullPageScreenshot property");
		}

		public override void AddAdditionalCapability(string capabilityName, object capabilityValue)
		{
			AddAdditionalCapability(capabilityName, capabilityValue, isGlobalCapability: false);
		}

		public void AddAdditionalCapability(string capabilityName, object capabilityValue, bool isGlobalCapability)
		{
			if (IsKnownCapabilityName(capabilityName))
			{
				string typeSafeOptionName = GetTypeSafeOptionName(capabilityName);
				throw new ArgumentException(string.Format(CultureInfo.InvariantCulture, "There is already an option for the {0} capability. Please use the {1} instead.", new object[2] { capabilityName, typeSafeOptionName }), "capabilityName");
			}
			if (string.IsNullOrEmpty(capabilityName))
			{
				throw new ArgumentException("Capability name may not be null an empty string.", "capabilityName");
			}
			if (isGlobalCapability)
			{
				additionalCapabilities[capabilityName] = capabilityValue;
			}
			else
			{
				additionalInternetExplorerOptions[capabilityName] = capabilityValue;
			}
		}

		public override ICapabilities ToCapabilities()
		{
			DesiredCapabilities desiredCapabilities = GenerateDesiredCapabilities(isSpecificationCompliant: true);
			Dictionary<string, object> capabilityValue = BuildInternetExplorerOptionsDictionary();
			desiredCapabilities.SetCapability(Capability, capabilityValue);
			foreach (KeyValuePair<string, object> additionalCapability in additionalCapabilities)
			{
				desiredCapabilities.SetCapability(additionalCapability.Key, additionalCapability.Value);
			}
			return desiredCapabilities;
		}

		private Dictionary<string, object> BuildInternetExplorerOptionsDictionary()
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary[CapabilityType.HasNativeEvents] = enableNativeEvents;
			dictionary["enablePersistentHover"] = enablePersistentHover;
			if (requireWindowFocus)
			{
				dictionary["requireWindowFocus"] = true;
			}
			if (ignoreProtectedModeSettings)
			{
				dictionary["ignoreProtectedModeSettings"] = true;
			}
			if (ignoreZoomLevel)
			{
				dictionary["ignoreZoomSetting"] = true;
			}
			if (!string.IsNullOrEmpty(initialBrowserUrl))
			{
				dictionary["initialBrowserUrl"] = initialBrowserUrl;
			}
			if (elementScrollBehavior != 0)
			{
				if (elementScrollBehavior == InternetExplorerElementScrollBehavior.Bottom)
				{
					dictionary["elementScrollBehavior"] = 1;
				}
				else
				{
					dictionary["elementScrollBehavior"] = 0;
				}
			}
			if (browserAttachTimeout != TimeSpan.MinValue)
			{
				dictionary["browserAttachTimeout"] = Convert.ToInt32(browserAttachTimeout.TotalMilliseconds);
			}
			if (fileUploadDialogTimeout != TimeSpan.MinValue)
			{
				dictionary["ie.fileUploadDialogTimeout"] = Convert.ToInt32(fileUploadDialogTimeout.TotalMilliseconds);
			}
			if (forceCreateProcessApi)
			{
				dictionary["ie.forceCreateProcessApi"] = true;
				if (!string.IsNullOrEmpty(browserCommandLineArguments))
				{
					dictionary["ie.browserCommandLineSwitches"] = browserCommandLineArguments;
				}
			}
			if (forceShellWindowsApi)
			{
				dictionary["ie.forceShellWindowsApi"] = true;
			}
			if (base.Proxy != null)
			{
				dictionary["ie.usePerProcessProxy"] = usePerProcessProxy;
			}
			if (ensureCleanSession)
			{
				dictionary["ie.ensureCleanSession"] = true;
			}
			if (!enableFullPageScreenshot)
			{
				dictionary["ie.enableFullPageScreenshot"] = false;
			}
			foreach (KeyValuePair<string, object> additionalInternetExplorerOption in additionalInternetExplorerOptions)
			{
				dictionary[additionalInternetExplorerOption.Key] = additionalInternetExplorerOption.Value;
			}
			return dictionary;
		}
	}
