namespace OpenQA.Selenium.Firefox
{
	public class FirefoxBinary : IDisposable
	{
		private const string NoFocusLibraryName = "x_ignore_nofocus.so";

		private Dictionary<string, string> extraEnv = new Dictionary<string, string>();

		private Executable executable;

		private Process process;

		private TimeSpan timeout = TimeSpan.FromSeconds(45.0);

		private bool isDisposed;

		public TimeSpan Timeout
		{
			get
			{
				return timeout;
			}
			set
			{
				timeout = value;
			}
		}

		internal Executable BinaryExecutable => executable;

		protected static bool IsOnLinux => Platform.CurrentPlatform.IsPlatformType(PlatformType.Linux);

		protected Dictionary<string, string> ExtraEnvironmentVariables => extraEnv;

		public FirefoxBinary()
			: this(null)
		{
		}

		public FirefoxBinary(string pathToFirefoxBinary)
		{
			executable = new Executable(pathToFirefoxBinary);
		}

		[SecurityPermission(SecurityAction.Demand)]
		public void StartProfile(FirefoxProfile profile, params string[] commandLineArguments)
		{
			if (profile == null)
			{
				throw new ArgumentNullException("profile", "profile cannot be null");
			}
			if (commandLineArguments == null)
			{
				commandLineArguments = new string[0];
			}
			string profileDirectory = profile.ProfileDirectory;
			SetEnvironmentProperty("XRE_PROFILE_PATH", profileDirectory);
			SetEnvironmentProperty("MOZ_NO_REMOTE", "1");
			SetEnvironmentProperty("MOZ_CRASHREPORTER_DISABLE", "1");
			SetEnvironmentProperty("NO_EM_RESTART", "1");
			if (IsOnLinux && (profile.EnableNativeEvents || profile.AlwaysLoadNoFocusLibrary))
			{
				ModifyLinkLibraryPath(profile);
			}
			StringBuilder stringBuilder = new StringBuilder();
			string[] array = commandLineArguments;
			foreach (string value in array)
			{
				stringBuilder.Append(" ").Append(value);
			}
			process = new Process();
			process.StartInfo.FileName = BinaryExecutable.ExecutablePath;
			process.StartInfo.Arguments = stringBuilder.ToString();
			process.StartInfo.UseShellExecute = false;
			foreach (string key in extraEnv.Keys)
			{
				if (process.StartInfo.EnvironmentVariables.ContainsKey(key))
				{
					process.StartInfo.EnvironmentVariables[key] = extraEnv[key];
				}
				else
				{
					process.StartInfo.EnvironmentVariables.Add(key, extraEnv[key]);
				}
			}
			BinaryExecutable.SetLibraryPath(process);
			StartFirefoxProcess();
			CopeWithTheStrangenessOfTheMac();
		}

		public void SetEnvironmentProperty(string propertyName, string value)
		{
			if (string.IsNullOrEmpty(propertyName) || value == null)
			{
				throw new WebDriverException(string.Format(CultureInfo.InvariantCulture, "You must set both the property name and value: {0}, {1}", new object[2] { propertyName, value }));
			}
			if (extraEnv.ContainsKey(propertyName))
			{
				extraEnv[propertyName] = value;
			}
			else
			{
				extraEnv.Add(propertyName, value);
			}
		}

		[SecurityPermission(SecurityAction.Demand)]
		public void WaitForProcessExit()
		{
			process.WaitForExit();
		}

		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		public override string ToString()
		{
			return "FirefoxBinary(" + executable.ExecutablePath + ")";
		}

		[SecurityPermission(SecurityAction.Demand)]
		protected void StartFirefoxProcess()
		{
			process.Start();
		}

		[SecurityPermission(SecurityAction.Demand)]
		protected virtual void Dispose(bool disposing)
		{
			if (isDisposed)
			{
				return;
			}
			if (disposing && process != null)
			{
				if (!process.HasExited)
				{
					Thread.Sleep(1000);
				}
				if (!process.HasExited)
				{
					process.Kill();
				}
				process.Dispose();
				process = null;
			}
			isDisposed = true;
		}

		private static void Sleep(int timeInMilliseconds)
		{
			try
			{
				Thread.Sleep(timeInMilliseconds);
			}
			catch (ThreadInterruptedException innerException)
			{
				throw new WebDriverException("Thread was interrupted", innerException);
			}
		}

		private static string ExtractAndCheck(FirefoxProfile profile, string noFocusSoName, string libraryPath32Bit, string libraryPath64Bit)
		{
			List<string> obj = new List<string> { libraryPath32Bit, libraryPath64Bit };
			StringBuilder stringBuilder = new StringBuilder();
			foreach (string item in obj)
			{
				string text = Path.Combine(profile.ProfileDirectory, item);
				string path = Path.Combine(text, noFocusSoName);
				string resourceId = string.Format(CultureInfo.InvariantCulture, "WebDriver.FirefoxNoFocus.{0}.dll", new object[1] { item });
				if (ResourceUtilities.IsValidResourceName(resourceId))
				{
					using Stream stream = ResourceUtilities.GetResourceStream(noFocusSoName, resourceId);
					Directory.CreateDirectory(text);
					using FileStream fileStream = File.Create(path);
					byte[] array = new byte[1000];
					for (int num = stream.Read(array, 0, array.Length); num > 0; num = stream.Read(array, 0, array.Length))
					{
						fileStream.Write(array, 0, num);
					}
				}
				if (!File.Exists(path))
				{
					throw new WebDriverException("Could not locate " + item + ": native events will not work.");
				}
				stringBuilder.Append(text).Append(Path.PathSeparator);
			}
			return stringBuilder.ToString();
		}

		private void ModifyLinkLibraryPath(FirefoxProfile profile)
		{
			string environmentVariable = Environment.GetEnvironmentVariable("LD_LIBRARY_PATH");
			string text = ExtractAndCheck(profile, "x_ignore_nofocus.so", "x86", "x64");
			if (!string.IsNullOrEmpty(environmentVariable))
			{
				text += environmentVariable;
			}
			SetEnvironmentProperty("LD_LIBRARY_PATH", text);
			SetEnvironmentProperty("LD_PRELOAD", "x_ignore_nofocus.so");
		}

		[SecurityPermission(SecurityAction.Demand)]
		private void CopeWithTheStrangenessOfTheMac()
		{
			if (!Platform.CurrentPlatform.IsPlatformType(PlatformType.Mac))
			{
				return;
			}
			try
			{
				Thread.Sleep(300);
				if (process.ExitCode == 0)
				{
					return;
				}
				Thread.Sleep(10000);
				StartFirefoxProcess();
			}
			catch (ThreadStateException)
			{
			}
			try
			{
				Sleep(300);
				if (process.ExitCode == 0)
				{
					return;
				}
				StringBuilder stringBuilder = new StringBuilder("Unable to start firefox cleanly.\n");
				stringBuilder.Append("Exit value: ").Append(process.ExitCode.ToString(CultureInfo.InvariantCulture)).Append("\n");
				stringBuilder.Append("Ran from: ").Append(process.StartInfo.FileName).Append("\n");
				throw new WebDriverException(stringBuilder.ToString());
			}
			catch (ThreadStateException)
			{
			}
		}
	}
	public class FirefoxDriver : RemoteWebDriver
	{
		public static readonly string ProfileCapabilityName = "firefox_profile";

		public static readonly string BinaryCapabilityName = "firefox_binary";

		public static readonly int DefaultPort = 7055;

		public static readonly bool DefaultEnableNativeEvents = Platform.CurrentPlatform.IsPlatformType(PlatformType.Windows);

		public static readonly bool AcceptUntrustedCertificates = true;

		public static readonly bool AssumeUntrustedCertificateIssuer = true;

		public override IFileDetector FileDetector
		{
			get
			{
				return base.FileDetector;
			}
			set
			{
			}
		}

		public bool IsMarionette => base.IsSpecificationCompliant;

		public FirefoxDriver()
			: this(new FirefoxOptions(null, null, null))
		{
		}

		public FirefoxDriver(FirefoxOptions options)
			: this(CreateService(options), options, RemoteWebDriver.DefaultCommandTimeout)
		{
		}

		public FirefoxDriver(FirefoxDriverService service)
			: this(service, new FirefoxOptions(), RemoteWebDriver.DefaultCommandTimeout)
		{
		}

		public FirefoxDriver(string geckoDriverDirectory)
			: this(geckoDriverDirectory, new FirefoxOptions())
		{
		}

		public FirefoxDriver(string geckoDriverDirectory, FirefoxOptions options)
			: this(geckoDriverDirectory, options, RemoteWebDriver.DefaultCommandTimeout)
		{
		}

		public FirefoxDriver(string geckoDriverDirectory, FirefoxOptions options, TimeSpan commandTimeout)
			: this(FirefoxDriverService.CreateDefaultService(geckoDriverDirectory), options, commandTimeout)
		{
		}

		public FirefoxDriver(FirefoxDriverService service, FirefoxOptions options)
			: this(service, options, RemoteWebDriver.DefaultCommandTimeout)
		{
		}

		public FirefoxDriver(FirefoxDriverService service, FirefoxOptions options, TimeSpan commandTimeout)
			: base(CreateExecutor(service, options, commandTimeout), ConvertOptionsToCapabilities(options))
		{
		}

		protected virtual void PrepareEnvironment()
		{
		}

		private static ICommandExecutor CreateExecutor(FirefoxDriverService service, FirefoxOptions options, TimeSpan commandTimeout)
		{
			ICommandExecutor commandExecutor = null;
			if (options.UseLegacyImplementation)
			{
				FirefoxBinary binary = new FirefoxBinary(options.BrowserExecutableLocation);
				FirefoxProfile firefoxProfile = options.Profile;
				if (firefoxProfile == null)
				{
					firefoxProfile = new FirefoxProfile();
				}
				return CreateExtensionConnection(binary, firefoxProfile, commandTimeout);
			}
			if (service == null)
			{
				throw new ArgumentNullException("service", "You requested a service-based implementation, but passed in a null service object.");
			}
			return new DriverServiceCommandExecutor(service, commandTimeout);
		}

		private static ICommandExecutor CreateExtensionConnection(FirefoxBinary binary, FirefoxProfile profile, TimeSpan commandTimeout)
		{
			FirefoxProfile firefoxProfile = profile;
			string environmentVariable = Environment.GetEnvironmentVariable("webdriver.firefox.profile");
			if (firefoxProfile == null && environmentVariable != null)
			{
				firefoxProfile = new FirefoxProfileManager().GetProfile(environmentVariable);
			}
			else if (firefoxProfile == null)
			{
				firefoxProfile = new FirefoxProfile();
			}
			return new FirefoxDriverCommandExecutor(binary, firefoxProfile, "localhost", commandTimeout);
		}

		private static ICapabilities ConvertOptionsToCapabilities(FirefoxOptions options)
		{
			if (options == null)
			{
				throw new ArgumentNullException("options", "options must not be null");
			}
			ICapabilities result = options.ToCapabilities();
			if (options.UseLegacyImplementation)
			{
				result = RemoveUnneededCapabilities(result);
			}
			return result;
		}

		private static ICapabilities RemoveUnneededCapabilities(ICapabilities capabilities)
		{
			DesiredCapabilities obj = capabilities as DesiredCapabilities;
			obj.CapabilitiesDictionary.Remove(ProfileCapabilityName);
			obj.CapabilitiesDictionary.Remove(BinaryCapabilityName);
			return obj;
		}

		private static FirefoxOptions CreateOptionsFromCapabilities(ICapabilities capabilities)
		{
			FirefoxBinary binary = ExtractBinary(capabilities);
			FirefoxProfile profile = ExtractProfile(capabilities);
			DesiredCapabilities desiredCapabilities = RemoveUnneededCapabilities(capabilities) as DesiredCapabilities;
			return new FirefoxOptions(profile, binary, desiredCapabilities);
		}

		private static FirefoxBinary ExtractBinary(ICapabilities capabilities)
		{
			if (capabilities.GetCapability(BinaryCapabilityName) != null)
			{
				return new FirefoxBinary(capabilities.GetCapability(BinaryCapabilityName).ToString());
			}
			return new FirefoxBinary();
		}

		private static FirefoxProfile ExtractProfile(ICapabilities capabilities)
		{
			FirefoxProfile firefoxProfile = new FirefoxProfile();
			if (capabilities.GetCapability(ProfileCapabilityName) != null)
			{
				object capability = capabilities.GetCapability(ProfileCapabilityName);
				FirefoxProfile firefoxProfile2 = capability as FirefoxProfile;
				string text = capability as string;
				if (firefoxProfile2 != null)
				{
					firefoxProfile = firefoxProfile2;
				}
				else if (text != null)
				{
					try
					{
						firefoxProfile = FirefoxProfile.FromBase64String(text);
					}
					catch (IOException innerException)
					{
						throw new WebDriverException("Unable to create profile from specified string", innerException);
					}
				}
			}
			if (capabilities.GetCapability(CapabilityType.Proxy) != null)
			{
				Proxy proxyPreferences = null;
				object capability2 = capabilities.GetCapability(CapabilityType.Proxy);
				Proxy proxy = capability2 as Proxy;
				Dictionary<string, object> dictionary = capability2 as Dictionary<string, object>;
				if (proxy != null)
				{
					proxyPreferences = proxy;
				}
				else if (dictionary != null)
				{
					proxyPreferences = new Proxy(dictionary);
				}
				firefoxProfile.SetProxyPreferences(proxyPreferences);
			}
			if (capabilities.GetCapability(CapabilityType.AcceptSslCertificates) != null)
			{
				bool acceptUntrustedCertificates = (bool)capabilities.GetCapability(CapabilityType.AcceptSslCertificates);
				firefoxProfile.AcceptUntrustedCertificates = acceptUntrustedCertificates;
			}
			return firefoxProfile;
		}

		private static FirefoxDriverService CreateService(FirefoxOptions options)
		{
			if (options != null && options.UseLegacyImplementation)
			{
				return null;
			}
			return FirefoxDriverService.CreateDefaultService();
		}
	}
	public class FirefoxDriverCommandExecutor : ICommandExecutor, IDisposable
	{
		private FirefoxDriverServer server;

		private HttpCommandExecutor internalExecutor;

		private TimeSpan commandTimeout;

		private bool isDisposed;

		public CommandInfoRepository CommandInfoRepository => internalExecutor.CommandInfoRepository;

		public FirefoxDriverCommandExecutor(FirefoxBinary binary, FirefoxProfile profile, string host, TimeSpan commandTimeout)
		{
			server = new FirefoxDriverServer(binary, profile, host);
			this.commandTimeout = commandTimeout;
		}

		public Response Execute(Command commandToExecute)
		{
			if (commandToExecute == null)
			{
				throw new ArgumentNullException("commandToExecute", "Command may not be null");
			}
			Response response = null;
			if (commandToExecute.Name == DriverCommand.NewSession)
			{
				server.Start();
				internalExecutor = new HttpCommandExecutor(server.ExtensionUri, commandTimeout);
			}
			try
			{
				return internalExecutor.Execute(commandToExecute);
			}
			finally
			{
				if (commandToExecute.Name == DriverCommand.Quit)
				{
					Dispose();
				}
			}
		}

		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		protected virtual void Dispose(bool disposing)
		{
			if (!isDisposed)
			{
				if (disposing)
				{
					server.Dispose();
				}
				isDisposed = true;
			}
		}
	}
	public enum FirefoxDriverLogLevel
	{
		Trace,
		Debug,
		Config,
		Info,
		Warn,
		Error,
		Fatal,
		Default
	}
	public class FirefoxDriverServer : ICommandServer, IDisposable
	{
		private string host;

		private List<IPEndPoint> addresses = new List<IPEndPoint>();

		private FirefoxProfile profile;

		private FirefoxBinary process;

		private Uri extensionUri;

		public Uri ExtensionUri => extensionUri;

		public FirefoxDriverServer(FirefoxBinary binary, FirefoxProfile profile, string host)
		{
			this.host = host;
			if (profile == null)
			{
				this.profile = new FirefoxProfile();
			}
			else
			{
				this.profile = profile;
			}
			if (binary == null)
			{
				process = new FirefoxBinary();
			}
			else
			{
				process = binary;
			}
		}

		public void Start()
		{
			using ILock @lock = new SocketLock(profile.Port - 1);
			@lock.LockObject(process.Timeout);
			try
			{
				int num = DetermineNextFreePort(host, profile.Port);
				profile.Port = num;
				profile.WriteToDisk();
				process.StartProfile(profile, "-foreground");
				SetAddress(num);
				extensionUri = new Uri(string.Format(CultureInfo.InvariantCulture, "http://{0}:{1}/hub/", new object[2] { host, num }));
				ConnectToBrowser(process.Timeout);
			}
			finally
			{
				@lock.UnlockObject();
			}
		}

		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		protected virtual void Dispose(bool disposing)
		{
			if (disposing)
			{
				process.Dispose();
				profile.Clean();
			}
		}

		private static int DetermineNextFreePort(string host, int port)
		{
			int i;
			for (i = port; i < port + 200; i++)
			{
				using Socket socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
				socket.ExclusiveAddressUse = true;
				IPHostEntry hostEntry = Dns.GetHostEntry(host);
				IPAddress address = IPAddress.Parse("127.0.0.1");
				IPAddress[] addressList = hostEntry.AddressList;
				foreach (IPAddress iPAddress in addressList)
				{
					if (iPAddress.AddressFamily == AddressFamily.InterNetwork)
					{
						address = iPAddress;
						break;
					}
				}
				IPEndPoint localEP = new IPEndPoint(address, i);
				try
				{
					socket.Bind(localEP);
					return i;
				}
				catch (SocketException)
				{
				}
			}
			throw new WebDriverException(string.Format(CultureInfo.InvariantCulture, "Cannot find free port in the range {0} to {1} ", new object[2] { port, i }));
		}

		private static List<IPEndPoint> ObtainLoopbackAddresses(int port)
		{
			List<IPEndPoint> list = new List<IPEndPoint>();
			NetworkInterface[] allNetworkInterfaces = NetworkInterface.GetAllNetworkInterfaces();
			for (int i = 0; i < allNetworkInterfaces.Length; i++)
			{
				foreach (UnicastIPAddressInformation unicastAddress in allNetworkInterfaces[i].GetIPProperties().UnicastAddresses)
				{
					if (unicastAddress.Address.AddressFamily == AddressFamily.InterNetwork && IPAddress.IsLoopback(unicastAddress.Address))
					{
						list.Add(new IPEndPoint(unicastAddress.Address, port));
					}
				}
			}
			return list;
		}

		private static bool IsSocketConnected(Socket extensionSocket)
		{
			return extensionSocket?.Connected ?? false;
		}

		private void SetAddress(int port)
		{
			if (string.Compare("localhost", host, StringComparison.OrdinalIgnoreCase) == 0)
			{
				addresses = ObtainLoopbackAddresses(port);
			}
			else
			{
				IPHostEntry hostEntry = Dns.GetHostEntry(host);
				IPAddress address = IPAddress.Parse("127.0.0.1");
				IPAddress[] addressList = hostEntry.AddressList;
				foreach (IPAddress iPAddress in addressList)
				{
					if (iPAddress.AddressFamily == AddressFamily.InterNetwork)
					{
						address = iPAddress;
						break;
					}
				}
				IPEndPoint item = new IPEndPoint(address, port);
				addresses.Add(item);
			}
			if (addresses.Count == 0)
			{
				throw new WebDriverException(string.Format(CultureInfo.InvariantCulture, "Could not find any IPv4 addresses for host '{0}'", new object[1] { host }));
			}
		}

		private void ConnectToBrowser(TimeSpan timeToWait)
		{
			Socket socket = null;
			DateTime dateTime = DateTime.Now.AddMilliseconds(timeToWait.TotalMilliseconds);
			try
			{
				while (!IsSocketConnected(socket) && dateTime > DateTime.Now)
				{
					foreach (IPEndPoint address in addresses)
					{
						try
						{
							socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
							socket.Connect(address);
						}
						catch (SocketException)
						{
							Thread.Sleep(250);
							continue;
						}
						break;
					}
				}
				if (IsSocketConnected(socket))
				{
					return;
				}
				if (socket == null || socket.RemoteEndPoint == null)
				{
					StringBuilder stringBuilder = new StringBuilder();
					foreach (IPEndPoint address2 in addresses)
					{
						if (stringBuilder.Length > 0)
						{
							stringBuilder.Append(", ");
						}
						stringBuilder.AppendFormat(CultureInfo.InvariantCulture, "{0}:{1}", new object[2]
						{
							address2.Address.ToString(),
							address2.Port.ToString(CultureInfo.InvariantCulture)
						});
					}
					throw new WebDriverException(string.Format(CultureInfo.InvariantCulture, "Failed to start up socket within {0} milliseconds. Attempted to connect to the following addresses: {1}", new object[2]
					{
						timeToWait.TotalMilliseconds,
						stringBuilder.ToString()
					}));
				}
				IPEndPoint iPEndPoint = (IPEndPoint)socket.RemoteEndPoint;
				throw new WebDriverException(string.Format(CultureInfo.InvariantCulture, "Unable to connect to host {0} on port {1} after {2} milliseconds", new object[3]
				{
					iPEndPoint.Address.ToString(),
					iPEndPoint.Port.ToString(CultureInfo.InvariantCulture),
					timeToWait.TotalMilliseconds
				}));
			}
			finally
			{
				socket.Close();
			}
		}
	}
	public sealed class FirefoxDriverService : DriverService
	{
		private const string DefaultFirefoxDriverServiceFileName = "geckodriver";

		private static readonly Uri FirefoxDriverDownloadUrl = new Uri("https://github.com/mozilla/geckodriver/releases");

		private bool connectToRunningBrowser;

		private bool openBrowserToolbox;

		private int browserCommunicationPort = -1;

		private string browserBinaryPath = string.Empty;

		private string host = string.Empty;

		private FirefoxDriverLogLevel loggingLevel = FirefoxDriverLogLevel.Default;

		public string FirefoxBinaryPath
		{
			get
			{
				return browserBinaryPath;
			}
			set
			{
				browserBinaryPath = value;
			}
		}

		public int BrowserCommunicationPort
		{
			get
			{
				return browserCommunicationPort;
			}
			set
			{
				browserCommunicationPort = value;
			}
		}

		public string Host
		{
			get
			{
				return host;
			}
			set
			{
				host = value;
			}
		}

		public bool ConnectToRunningBrowser
		{
			get
			{
				return connectToRunningBrowser;
			}
			set
			{
				connectToRunningBrowser = value;
			}
		}

		public bool OpenBrowserToolbox
		{
			get
			{
				return openBrowserToolbox;
			}
			set
			{
				openBrowserToolbox = value;
			}
		}

		protected override TimeSpan InitializationTimeout => TimeSpan.FromSeconds(2.0);

		protected override TimeSpan TerminationTimeout => TimeSpan.FromMilliseconds(100.0);

		protected override bool HasShutdown => false;

		protected override string CommandLineArguments
		{
			get
			{
				StringBuilder stringBuilder = new StringBuilder();
				if (connectToRunningBrowser)
				{
					stringBuilder.Append(" --connect-existing");
				}
				if (browserCommunicationPort > 0)
				{
					stringBuilder.AppendFormat(CultureInfo.InvariantCulture, " --marionette-port {0}", new object[1] { browserCommunicationPort });
				}
				if (base.Port > 0)
				{
					stringBuilder.AppendFormat(CultureInfo.InvariantCulture, " --port {0}", new object[1] { base.Port });
				}
				if (!string.IsNullOrEmpty(browserBinaryPath))
				{
					stringBuilder.AppendFormat(CultureInfo.InvariantCulture, " --binary \"{0}\"", new object[1] { browserBinaryPath });
				}
				if (!string.IsNullOrEmpty(host))
				{
					stringBuilder.AppendFormat(CultureInfo.InvariantCulture, " --host \"{0}\"", new object[1] { host });
				}
				if (loggingLevel != FirefoxDriverLogLevel.Default)
				{
					stringBuilder.Append(string.Format(CultureInfo.InvariantCulture, " --log {0}", new object[1] { loggingLevel.ToString().ToLowerInvariant() }));
				}
				if (openBrowserToolbox)
				{
					stringBuilder.Append(" --jsdebugger");
				}
				return stringBuilder.ToString().Trim();
			}
		}

		private FirefoxDriverService(string executablePath, string executableFileName, int port)
			: base(executablePath, port, executableFileName, FirefoxDriverDownloadUrl)
		{
		}

		public static FirefoxDriverService CreateDefaultService()
		{
			return CreateDefaultService(DriverService.FindDriverServiceExecutable(FirefoxDriverServiceFileName(), FirefoxDriverDownloadUrl));
		}

		public static FirefoxDriverService CreateDefaultService(string driverPath)
		{
			return CreateDefaultService(driverPath, FirefoxDriverServiceFileName());
		}

		public static FirefoxDriverService CreateDefaultService(string driverPath, string driverExecutableFileName)
		{
			return new FirefoxDriverService(driverPath, driverExecutableFileName, PortUtilities.FindFreePort());
		}

		private static string FirefoxDriverServiceFileName()
		{
			string text = "geckodriver";
			switch (Environment.OSVersion.Platform)
			{
			case PlatformID.Win32S:
			case PlatformID.Win32Windows:
			case PlatformID.Win32NT:
			case PlatformID.WinCE:
				text += ".exe";
				break;
			default:
				if (Environment.OSVersion.Platform != (PlatformID)128)
				{
					throw new WebDriverException("Unsupported platform: " + Environment.OSVersion.Platform);
				}
				break;
			case PlatformID.Unix:
			case PlatformID.MacOSX:
				break;
			}
			return text;
		}
	}
	public class FirefoxExtension
	{
		private const string EmNamespaceUri = "http://www.mozilla.org/2004/em-rdf#";

		private const string RdfManifestFileName = "install.rdf";

		private const string JsonManifestFileName = "manifest.json";

		private string extensionFileName;

		private string extensionResourceId;

		public FirefoxExtension(string fileName)
			: this(fileName, string.Empty)
		{
		}

		internal FirefoxExtension(string fileName, string resourceId)
		{
			extensionFileName = fileName;
			extensionResourceId = resourceId;
		}

		public void Install(string profileDirectory)
		{
			DirectoryInfo directoryInfo = new DirectoryInfo(profileDirectory);
			string text = Path.Combine(Path.GetTempPath(), directoryInfo.Name + ".staging");
			string text2 = Path.Combine(text, Path.GetFileName(extensionFileName));
			if (Directory.Exists(text2))
			{
				Directory.Delete(text2, recursive: true);
			}
			Directory.CreateDirectory(text2);
			using (ZipStorer zipStorer = ZipStorer.Open(ResourceUtilities.GetResourceStream(extensionFileName, extensionResourceId), FileAccess.Read))
			{
				foreach (ZipStorer.ZipFileEntry item in zipStorer.ReadCentralDirectory())
				{
					string path = item.FilenameInZip.Replace('/', Path.DirectorySeparatorChar);
					string destinationFileName = Path.Combine(text2, path);
					zipStorer.ExtractFile(item, destinationFileName);
				}
			}
			string extensionId = GetExtensionId(text2);
			string text3 = Path.Combine(Path.Combine(profileDirectory, "extensions"), extensionId);
			if (Directory.Exists(text3))
			{
				Directory.Delete(text3, recursive: true);
			}
			Directory.CreateDirectory(text3);
			FileUtilities.CopyDirectory(text2, text3);
			FileUtilities.DeleteDirectory(text);
		}

		private static string GetExtensionId(string root)
		{
			string path = Path.Combine(root, "manifest.json");
			if (File.Exists(Path.Combine(root, "install.rdf")))
			{
				return ReadIdFromInstallRdf(root);
			}
			if (File.Exists(path))
			{
				return ReadIdFromManifestJson(root);
			}
			throw new WebDriverException("Extension should contain either install.rdf or manifest.json metadata file");
		}

		private static string ReadIdFromInstallRdf(string root)
		{
			string text = null;
			string text2 = Path.Combine(root, "install.rdf");
			try
			{
				XmlDocument xmlDocument = new XmlDocument();
				xmlDocument.Load(text2);
				XmlNamespaceManager xmlNamespaceManager = new XmlNamespaceManager(xmlDocument.NameTable);
				xmlNamespaceManager.AddNamespace("em", "http://www.mozilla.org/2004/em-rdf#");
				xmlNamespaceManager.AddNamespace("RDF", "http://www.w3.org/1999/02/22-rdf-syntax-ns#");
				XmlNode xmlNode = xmlDocument.SelectSingleNode("//em:id", xmlNamespaceManager);
				text = ((xmlNode != null) ? xmlNode.InnerText : (xmlDocument.SelectSingleNode("//RDF:Description", xmlNamespaceManager).Attributes["id", "http://www.mozilla.org/2004/em-rdf#"] ?? throw new WebDriverException("Cannot locate node containing extension id: " + text2)).Value);
				if (string.IsNullOrEmpty(text))
				{
					throw new FileNotFoundException("Cannot install extension with ID: " + text);
				}
				return text;
			}
			catch (Exception innerException)
			{
				throw new WebDriverException("Error installing extension", innerException);
			}
		}

		private static string ReadIdFromManifestJson(string root)
		{
			string text = null;
			JObject jObject = JObject.Parse(File.ReadAllText(Path.Combine(root, "manifest.json")));
			if (jObject["applications"] != null)
			{
				JToken jToken = jObject["applications"];
				if (jToken["gecko"] != null)
				{
					JToken jToken2 = jToken["gecko"];
					if (jToken2["id"] != null)
					{
						text = jToken2["id"].ToString().Trim();
					}
				}
			}
			if (string.IsNullOrEmpty(text))
			{
				string text2 = jObject["name"].ToString().Replace(" ", "");
				string text3 = jObject["version"].ToString();
				text = string.Format(CultureInfo.InvariantCulture, "{0}@{1}", new object[2] { text2, text3 });
			}
			return text;
		}
	}
