		public FirefoxOptions()
		{
			base.BrowserName = "firefox";
			AddKnownCapabilityName("moz:firefoxOptions", "current FirefoxOptions class instance");
			AddKnownCapabilityName("marionette", "UseLegacyImplementation property");
			AddKnownCapabilityName("profile", "Profile property");
			AddKnownCapabilityName("binary", "BrowserExecutableLocation property");
			AddKnownCapabilityName("args", "AddArguments method");
			AddKnownCapabilityName("prefs", "SetPreference method");
			AddKnownCapabilityName("log", "LogLevel property");
			AddKnownCapabilityName("firefox_profile", "Profile property");
			AddKnownCapabilityName("firefox_binary", "BrowserExecutableLocation property");
		}

		internal FirefoxOptions(FirefoxProfile profile, FirefoxBinary binary, DesiredCapabilities capabilities)
		{
			base.BrowserName = "firefox";
			if (profile != null)
			{
				this.profile = profile;
			}
			if (binary != null)
			{
				browserBinaryLocation = binary.BinaryExecutable.ExecutablePath;
			}
			if (capabilities != null)
			{
				ImportCapabilities(capabilities);
