		}

		public override void AddAdditionalCapability(string capabilityName, object capabilityValue)
		{
			AddAdditionalCapability(capabilityName, capabilityValue, isGlobalCapability: false);
		}

		public void AddAdditionalCapability(string capabilityName, object capabilityValue, bool isGlobalCapability)
		{
			if (IsKnownCapabilityName(capabilityName))
			{
				string typeSafeOptionName = GetTypeSafeOptionName(capabilityName);
				throw new ArgumentException(string.Format(CultureInfo.InvariantCulture, "There is already an option for the {0} capability. Please use the {1} instead.", new object[2] { capabilityName, typeSafeOptionName }), "capabilityName");
			}
			if (string.IsNullOrEmpty(capabilityName))
			{
				throw new ArgumentException("Capability name may not be null an empty string.", "capabilityName");
			}
			if (isGlobalCapability)
			{
				additionalCapabilities[capabilityName] = capabilityValue;
			}
			else
			{
				additionalFirefoxOptions[capabilityName] = capabilityValue;
			}
		}

		public override ICapabilities ToCapabilities()
		{
			DesiredCapabilities desiredCapabilities = GenerateDesiredCapabilities(isMarionette);
			if (isMarionette)
			{
				Dictionary<string, object> capabilityValue = GenerateFirefoxOptionsDictionary();
				desiredCapabilities.SetCapability("moz:firefoxOptions", capabilityValue);
			}
			else
			{
				if (profile != null)
				{
					if (base.Proxy != null)
					{
						profile.InternalSetProxyPreferences(base.Proxy);
					}
					desiredCapabilities.SetCapability("profile", profile.ToBase64String());
				}
				if (!string.IsNullOrEmpty(browserBinaryLocation))
				{
					desiredCapabilities.SetCapability("binary", browserBinaryLocation);
				}
				else
				{
					using FirefoxBinary firefoxBinary = new FirefoxBinary();
					string executablePath = firefoxBinary.BinaryExecutable.ExecutablePath;
					desiredCapabilities.SetCapability("binary", executablePath);
				}
			}
			foreach (KeyValuePair<string, object> additionalCapability in additionalCapabilities)
			{
				desiredCapabilities.SetCapability(additionalCapability.Key, additionalCapability.Value);
			}
			return desiredCapabilities;
		}

		private Dictionary<string, object> GenerateFirefoxOptionsDictionary()
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			if (profile != null)
			{
				profile.RemoveWebDriverExtension();
				dictionary["profile"] = profile.ToBase64String();
			}
			if (!string.IsNullOrEmpty(browserBinaryLocation))
			{
				dictionary["binary"] = browserBinaryLocation;
			}
			else if (!isMarionette)
			{
				using FirefoxBinary firefoxBinary = new FirefoxBinary();
				string executablePath = firefoxBinary.BinaryExecutable.ExecutablePath;
				if (!string.IsNullOrEmpty(executablePath))
				{
					dictionary["binary"] = executablePath;
				}
			}
			if (logLevel != FirefoxDriverLogLevel.Default)
			{
				Dictionary<string, object> dictionary2 = new Dictionary<string, object>();
				dictionary2["level"] = logLevel.ToString().ToLowerInvariant();
				dictionary["log"] = dictionary2;
			}
			if (firefoxArguments.Count > 0)
			{
				List<object> list = new List<object>();
				foreach (string firefoxArgument in firefoxArguments)
				{
					list.Add(firefoxArgument);
				}
				dictionary["args"] = list;
			}
			if (profilePreferences.Count > 0)
			{
				dictionary["prefs"] = profilePreferences;
			}
			foreach (KeyValuePair<string, object> additionalFirefoxOption in additionalFirefoxOptions)
			{
				dictionary.Add(additionalFirefoxOption.Key, additionalFirefoxOption.Value);
			}
			return dictionary;
		}

		private void SetPreferenceValue(string preferenceName, object preferenceValue)
		{
			if (string.IsNullOrEmpty(preferenceName))
			{
				throw new ArgumentException("Preference name may not be null an empty string.", "preferenceName");
			}
			if (!isMarionette)
			{
				throw new ArgumentException("Preferences cannot be set directly when using the legacy FirefoxDriver implementation. Set them in the profile.");
			}
			profilePreferences[preferenceName] = preferenceValue;
		}

		private void ImportCapabilities(DesiredCapabilities capabilities)
		{
			foreach (KeyValuePair<string, object> item in capabilities.CapabilitiesDictionary)
			{
				if (item.Key == CapabilityType.BrowserName)
				{
					continue;
				}
				if (item.Key == CapabilityType.BrowserVersion)
				{
					base.BrowserVersion = item.Value.ToString();
				}
				else if (item.Key == CapabilityType.PlatformName)
				{
					base.PlatformName = item.Value.ToString();
				}
				else if (item.Key == CapabilityType.Proxy)
				{
					base.Proxy = new Proxy(item.Value as Dictionary<string, object>);
				}
				else if (item.Key == CapabilityType.UnhandledPromptBehavior)
				{
					base.UnhandledPromptBehavior = (UnhandledPromptBehavior)Enum.Parse(typeof(UnhandledPromptBehavior), item.Value.ToString(), ignoreCase: true);
				}
				else if (item.Key == CapabilityType.PageLoadStrategy)
				{
					base.PageLoadStrategy = (PageLoadStrategy)Enum.Parse(typeof(PageLoadStrategy), item.Value.ToString(), ignoreCase: true);
				}
				else if (item.Key == "moz:firefoxOptions")
				{
					foreach (KeyValuePair<string, object> item2 in item.Value as Dictionary<string, object>)
					{
						if (item2.Key == "args")
						{
							object[] array = item2.Value as object[];
							for (int i = 0; i < array.Length; i++)
							{
								firefoxArguments.Add(array[i].ToString());
							}
						}
						else if (item2.Key == "prefs")
						{
							profilePreferences = item2.Value as Dictionary<string, object>;
						}
						else if (item2.Key == "log")
						{
							Dictionary<string, object> dictionary = item2.Value as Dictionary<string, object>;
							if (dictionary.ContainsKey("level"))
							{
								logLevel = (FirefoxDriverLogLevel)Enum.Parse(typeof(FirefoxDriverLogLevel), dictionary["level"].ToString(), ignoreCase: true);
							}
						}
						else if (item2.Key == "binary")
						{
							browserBinaryLocation = item2.Value.ToString();
						}
						else if (item2.Key == "profile")
						{
							profile = FirefoxProfile.FromBase64String(item2.Value.ToString());
						}
						else
						{
							AddAdditionalCapability(item2.Key, item2.Value);
						}
					}
				}
				else
				{
					AddAdditionalCapability(item.Key, item.Value, isGlobalCapability: true);
				}
			}
		}
	}
	public class FirefoxProfile
	{
		private const string ExtensionFileName = "webdriver.xpi";

		private const string ExtensionResourceId = "WebDriver.FirefoxExt.zip";

		private const string UserPreferencesFileName = "user.js";

		private const string WebDriverPortPreferenceName = "webdriver_firefox_port";

		private const string EnableNativeEventsPreferenceName = "webdriver_enable_native_events";

		private const string AcceptUntrustedCertificatesPreferenceName = "webdriver_accept_untrusted_certs";

		private const string AssumeUntrustedCertificateIssuerPreferenceName = "webdriver_assume_untrusted_issuer";

		private int profilePort;

		private string profileDir;

		private string sourceProfileDir;

		private bool enableNativeEvents;

		private bool loadNoFocusLibrary;

		private bool acceptUntrustedCerts;

		private bool assumeUntrustedIssuer;

		private bool deleteSource;

		private bool deleteOnClean = true;

