		public FirefoxProfile()
			: this(null)
		{
		}

		public FirefoxProfile(string profileDirectory)
			: this(profileDirectory, deleteSourceOnClean: false)
		{
		}

		public FirefoxProfile(string profileDirectory, bool deleteSourceOnClean)
		{
			sourceProfileDir = profileDirectory;
			profilePort = FirefoxDriver.DefaultPort;
			enableNativeEvents = FirefoxDriver.DefaultEnableNativeEvents;
			acceptUntrustedCerts = FirefoxDriver.AcceptUntrustedCertificates;
			assumeUntrustedIssuer = FirefoxDriver.AssumeUntrustedCertificateIssuer;
			deleteSource = deleteSourceOnClean;
			ReadDefaultPreferences();
			profilePreferences.AppendPreferences(ReadExistingPreferences());
			AddWebDriverExtension();
		}

		public static FirefoxProfile FromBase64String(string base64)
		{
			string text = FileUtilities.GenerateRandomTempDirectoryName("webdriver.{0}.duplicated");
			using (MemoryStream stream = new MemoryStream(Convert.FromBase64String(base64)))
			{
				using ZipStorer zipStorer = ZipStorer.Open(stream, FileAccess.Read);
				foreach (ZipStorer.ZipFileEntry item in zipStorer.ReadCentralDirectory())
				{
					string path = item.FilenameInZip.Replace('/', Path.DirectorySeparatorChar);
					string destinationFileName = Path.Combine(text, path);
					zipStorer.ExtractFile(item, destinationFileName);
				}
			}
			return new FirefoxProfile(text, deleteSourceOnClean: true);
		}

		public void AddExtension(string extensionToInstall)
		{
			extensions.Add(Path.GetFileNameWithoutExtension(extensionToInstall), new FirefoxExtension(extensionToInstall));
		}

		public void SetPreference(string name, string value)
		{
			profilePreferences.SetPreference(name, value);
		}

		public void SetPreference(string name, int value)
		{
			profilePreferences.SetPreference(name, value);
		}

		public void SetPreference(string name, bool value)
		{
			profilePreferences.SetPreference(name, value);
		}

		[Obsolete("Use the FirefoxOptions class to set a proxy for Firefox.")]
		public void SetProxyPreferences(Proxy proxy)
		{
			InternalSetProxyPreferences(proxy);
		}

		public void WriteToDisk()
		{
			profileDir = GenerateProfileDirectoryName();
			if (!string.IsNullOrEmpty(sourceProfileDir))
			{
				FileUtilities.CopyDirectory(sourceProfileDir, profileDir);
			}
			else
			{
				Directory.CreateDirectory(profileDir);
			}
			InstallExtensions();
			DeleteLockFiles();
			DeleteExtensionsCache();
			UpdateUserPreferences();
		}

		public void Clean()
		{
			if (deleteOnClean && !string.IsNullOrEmpty(profileDir) && Directory.Exists(profileDir))
			{
				FileUtilities.DeleteDirectory(profileDir);
			}
			if (deleteSource && !string.IsNullOrEmpty(sourceProfileDir) && Directory.Exists(sourceProfileDir))
			{
				FileUtilities.DeleteDirectory(sourceProfileDir);
			}
		}

		public string ToBase64String()
		{
			string empty = string.Empty;
			WriteToDisk();
			using MemoryStream memoryStream = new MemoryStream();
			using (ZipStorer zipStorer = ZipStorer.Create(memoryStream, string.Empty))
			{
				string[] files = Directory.GetFiles(profileDir, "*.*", SearchOption.AllDirectories);
				foreach (string text in files)
				{
					string fileNameInZip = text.Substring(profileDir.Length).Replace(Path.DirectorySeparatorChar, '/');
					zipStorer.AddFile(ZipStorer.CompressionMethod.Deflate, text, fileNameInZip, string.Empty);
				}
			}
			empty = Convert.ToBase64String(memoryStream.ToArray());
			Clean();
			return empty;
		}

		internal void AddWebDriverExtension()
		{
			if (!extensions.ContainsKey("webdriver"))
			{
				extensions.Add("webdriver", new FirefoxExtension("webdriver.xpi", "WebDriver.FirefoxExt.zip"));
			}
		}

		internal void RemoveWebDriverExtension()
		{
			if (extensions.ContainsKey("webdriver"))
			{
				extensions.Remove("webdriver");
			}
		}

		internal void InternalSetProxyPreferences(Proxy proxy)
		{
			if (proxy == null)
			{
				throw new ArgumentNullException("proxy", "proxy must not be null");
			}
			if (proxy.Kind == ProxyKind.Unspecified)
			{
				return;
			}
			SetPreference("network.proxy.type", (int)proxy.Kind);
			switch (proxy.Kind)
			{
			case ProxyKind.Manual:
				SetPreference("network.proxy.no_proxies_on", string.Empty);
				SetManualProxyPreference("ftp", proxy.FtpProxy);
				SetManualProxyPreference("http", proxy.HttpProxy);
				SetManualProxyPreference("ssl", proxy.SslProxy);
				SetManualProxyPreference("socks", proxy.SocksProxy);
				if (proxy.BypassProxyAddresses != null)
				{
					SetPreference("network.proxy.no_proxies_on", proxy.BypassProxyAddresses);
				}
				break;
			case ProxyKind.ProxyAutoConfigure:
				SetPreference("network.proxy.autoconfig_url", proxy.ProxyAutoConfigUrl);
				break;
			}
		}

		private static string GenerateProfileDirectoryName()
		{
			return FileUtilities.GenerateRandomTempDirectoryName("anonymous.{0}.webdriver-profile");
		}

		private void DeleteLockFiles()
		{
			File.Delete(Path.Combine(profileDir, ".parentlock"));
			File.Delete(Path.Combine(profileDir, "parent.lock"));
		}

		private void InstallExtensions()
		{
			foreach (string key in extensions.Keys)
			{
				extensions[key].Install(profileDir);
			}
		}

		private void DeleteExtensionsCache()
		{
			string path = Path.Combine(new DirectoryInfo(Path.Combine(profileDir, "extensions")).Parent.FullName, "extensions.cache");
			if (File.Exists(path))
			{
				File.Delete(path);
			}
		}

		private void UpdateUserPreferences()
		{
			if (profilePort == 0)
			{
				throw new WebDriverException("You must set the port to listen on before updating user preferences file");
			}
			string text = Path.Combine(profileDir, "user.js");
			if (File.Exists(text))
			{
				try
				{
					File.Delete(text);
				}
				catch (Exception innerException)
				{
					throw new WebDriverException("Cannot delete existing user preferences", innerException);
				}
			}
			profilePreferences.SetPreference("webdriver_firefox_port", profilePort);
			profilePreferences.SetPreference("webdriver_enable_native_events", enableNativeEvents);
			profilePreferences.SetPreference("webdriver_accept_untrusted_certs", acceptUntrustedCerts);
			profilePreferences.SetPreference("webdriver_assume_untrusted_issuer", assumeUntrustedIssuer);
			string preference = profilePreferences.GetPreference("browser.startup.homepage");
			if (!string.IsNullOrEmpty(preference))
			{
				profilePreferences.SetPreference("startup.homepage_welcome_url", string.Empty);
				if (preference != "about:blank")
				{
					profilePreferences.SetPreference("browser.startup.page", 1);
				}
			}
			profilePreferences.WriteToFile(text);
		}

		private void ReadDefaultPreferences()
		{
			using Stream stream = ResourceUtilities.GetResourceStream("webdriver.json", "WebDriver.FirefoxPreferences");
			using StreamReader streamReader = new StreamReader(stream);
			Dictionary<string, object> dictionary = JsonConvert.DeserializeObject<Dictionary<string, object>>(streamReader.ReadToEnd(), new JsonConverter[1]
			{
				new ResponseValueJsonConverter()
			});
			Dictionary<string, object> defaultImmutablePreferences = dictionary["frozen"] as Dictionary<string, object>;
			Dictionary<string, object> defaultPreferences = dictionary["mutable"] as Dictionary<string, object>;
			profilePreferences = new Preferences(defaultImmutablePreferences, defaultPreferences);
		}

		private Dictionary<string, string> ReadExistingPreferences()
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			try
			{
				if (!string.IsNullOrEmpty(sourceProfileDir))
				{
					string path = Path.Combine(sourceProfileDir, "user.js");
					if (File.Exists(path))
					{
						string[] array = File.ReadAllLines(path);
						foreach (string text in array)
						{
							if (text.StartsWith("user_pref(\"", StringComparison.OrdinalIgnoreCase))
							{
								string text2 = text.Substring("user_pref(\"".Length);
								text2 = text2.Substring(0, text2.Length - ");".Length);
								string[] array2 = text.Split(new string[1] { "," }, StringSplitOptions.None);
								array2[0] = array2[0].Substring(0, array2[0].Length - 1);
								dictionary.Add(array2[0].Trim(), array2[1].Trim());
							}
						}
					}
				}
			}
			catch (IOException innerException)
			{
				throw new WebDriverException(string.Empty, innerException);
			}
			return dictionary;
		}

		private void SetManualProxyPreference(string key, string settingString)
		{
			if (settingString != null)
			{
				string[] array = settingString.Split(new char[1] { ':' });
				SetPreference("network.proxy." + key, array[0]);
				if (array.Length > 1)
				{
					SetPreference("network.proxy." + key + "_port", int.Parse(array[1], CultureInfo.InvariantCulture));
				}
			}
		}
	}
	public class FirefoxProfileManager
	{
		private Dictionary<string, string> profiles = new Dictionary<string, string>();

		public ReadOnlyCollection<string> ExistingProfiles => new List<string>(profiles.Keys).AsReadOnly();

		public FirefoxProfileManager()
		{
			string applicationDataDirectory = GetApplicationDataDirectory();
			ReadProfiles(applicationDataDirectory);
		}

		public FirefoxProfile GetProfile(string profileName)
		{
			FirefoxProfile firefoxProfile = null;
			if (!string.IsNullOrEmpty(profileName) && profiles.ContainsKey(profileName))
			{
				firefoxProfile = new FirefoxProfile(profiles[profileName]);
				if (firefoxProfile.Port == 0)
				{
					firefoxProfile.Port = FirefoxDriver.DefaultPort;
				}
			}
			return firefoxProfile;
		}

		private static string GetApplicationDataDirectory()
		{
			string empty = string.Empty;
			return Path.Combine(path2: Environment.OSVersion.Platform switch
			{
				PlatformID.Unix => Path.Combine(".mozilla", "firefox"), 
				PlatformID.MacOSX => Path.Combine("Library", Path.Combine("Application Support", "Firefox")), 
				_ => Path.Combine("Mozilla", "Firefox"), 
			}, path1: Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData));
		}

		private void ReadProfiles(string appDataDirectory)
		{
			string text = Path.Combine(appDataDirectory, "profiles.ini");
			if (!File.Exists(text))
			{
				return;
			}
			IniFileReader iniFileReader = new IniFileReader(text);
			foreach (string sectionName in iniFileReader.SectionNames)
			{
				if (sectionName.StartsWith("profile", StringComparison.OrdinalIgnoreCase))
				{
					string value = iniFileReader.GetValue(sectionName, "name");
					bool flag = iniFileReader.GetValue(sectionName, "isrelative") == "1";
					string value2 = iniFileReader.GetValue(sectionName, "path");
					string empty = string.Empty;
					empty = ((!flag) ? value2 : Path.Combine(appDataDirectory, value2));
					profiles.Add(value, empty);
				}
			}
		}
	}
	public class FirefoxWebElement : RemoteWebElement
	{
		public FirefoxWebElement(FirefoxDriver parentDriver, string id)
			: base(parentDriver, id)
		{
		}

		public override bool Equals(object obj)
		{
			IWebElement webElement = obj as IWebElement;
			if (webElement == null)
			{
				return false;
			}
			if (webElement is IWrapsElement)
			{
				webElement = ((IWrapsElement)obj).WrappedElement;
			}
			if (!(webElement is FirefoxWebElement firefoxWebElement))
			{
				return false;
			}
			return base.Id == firefoxWebElement.Id;
		}

		public override int GetHashCode()
		{
			return base.GetHashCode();
		}
	}
	internal class Preferences
	{
		private Dictionary<string, string> preferences = new Dictionary<string, string>();

		private Dictionary<string, string> immutablePreferences = new Dictionary<string, string>();

		public Preferences(Dictionary<string, object> defaultImmutablePreferences, Dictionary<string, object> defaultPreferences)
		{
			if (defaultImmutablePreferences != null)
			{
				foreach (KeyValuePair<string, object> defaultImmutablePreference in defaultImmutablePreferences)
				{
					SetPreferenceValue(defaultImmutablePreference.Key, defaultImmutablePreference.Value);
					immutablePreferences.Add(defaultImmutablePreference.Key, defaultImmutablePreference.Value.ToString());
				}
			}
			if (defaultPreferences == null)
			{
				return;
			}
			foreach (KeyValuePair<string, object> defaultPreference in defaultPreferences)
			{
				SetPreferenceValue(defaultPreference.Key, defaultPreference.Value);
			}
		}

		internal void SetPreference(string key, string value)
		{
			SetPreferenceValue(key, value);
		}

		internal void SetPreference(string key, int value)
		{
			SetPreferenceValue(key, value);
		}

		internal void SetPreference(string key, bool value)
		{
			SetPreferenceValue(key, value);
		}

		internal string GetPreference(string preferenceName)
		{
			if (preferences.ContainsKey(preferenceName))
			{
				return preferences[preferenceName];
			}
			return string.Empty;
		}

		internal void AppendPreferences(Dictionary<string, string> preferencesToAdd)
		{
			foreach (KeyValuePair<string, string> item in preferencesToAdd)
			{
				if (IsSettablePreference(item.Key))
				{
					preferences[item.Key] = item.Value;
				}
			}
		}

		internal void WriteToFile(string filePath)
		{
			using TextWriter textWriter = File.CreateText(filePath);
			foreach (KeyValuePair<string, string> preference in preferences)
			{
				string text = preference.Value.Replace("\\", "\\\\");
				textWriter.WriteLine(string.Format(CultureInfo.InvariantCulture, "user_pref(\"{0}\", {1});", new object[2] { preference.Key, text }));
			}
		}

		private static bool IsWrappedAsString(string value)
		{
			if (value.StartsWith("\"", StringComparison.OrdinalIgnoreCase))
			{
				return value.EndsWith("\"", StringComparison.OrdinalIgnoreCase);
			}
			return false;
		}

		private bool IsSettablePreference(string preferenceName)
		{
			return !immutablePreferences.ContainsKey(preferenceName);
		}

		private void SetPreferenceValue(string key, object value)
		{
			if (!IsSettablePreference(key))
			{
				throw new ArgumentException(string.Format(CultureInfo.InvariantCulture, "Preference {0} may not be overridden: frozen value={1}, requested value={2}", new object[3]
				{
					key,
					immutablePreferences[key],
					value.ToString()
				}));
			}
			if (value is string value2)
			{
				if (IsWrappedAsString(value2))
				{
					throw new ArgumentException(string.Format(CultureInfo.InvariantCulture, "Preference values must be plain strings: {0}: {1}", new object[2] { key, value }));
				}
				preferences[key] = string.Format(CultureInfo.InvariantCulture, "\"{0}\"", new object[1] { value });
			}
			else if (value is bool)
			{
				preferences[key] = Convert.ToBoolean(value, CultureInfo.InvariantCulture).ToString().ToLowerInvariant();
			}
			else
			{
				if (!(value is int) && !(value is long))
				{
					throw new WebDriverException("Value must be string, int or boolean");
				}
				preferences[key] = Convert.ToInt32(value, CultureInfo.InvariantCulture).ToString(CultureInfo.InvariantCulture);
			}
		}
	}
