namespace OpenQA.Selenium.Firefox.Internal
{
	internal class Executable
	{
		private readonly string binaryInDefaultLocationForPlatform;

		private string binaryLocation;

		public string ExecutablePath => binaryLocation;

		public Executable(string userSpecifiedBinaryPath)
		{
			if (!string.IsNullOrEmpty(userSpecifiedBinaryPath))
			{
				if (File.Exists(userSpecifiedBinaryPath))
				{
					binaryLocation = userSpecifiedBinaryPath;
					return;
				}
				throw new WebDriverException("Specified firefox binary location does not exist or is not a real file: " + userSpecifiedBinaryPath);
			}
			binaryInDefaultLocationForPlatform = LocateFirefoxBinaryFromPlatform();
			if (binaryInDefaultLocationForPlatform != null && File.Exists(binaryInDefaultLocationForPlatform))
			{
				binaryLocation = binaryInDefaultLocationForPlatform;
				return;
			}
			throw new WebDriverException("Cannot find Firefox binary in PATH or default install locations. Make sure Firefox is installed. OS appears to be: " + Platform.CurrentPlatform.ToString());
		}

		[SecurityPermission(SecurityAction.Demand)]
		public void SetLibraryPath(Process builder)
		{
			string libraryPathPropertyName = GetLibraryPathPropertyName();
			StringBuilder stringBuilder = new StringBuilder();
			string environmentVariable = GetEnvironmentVariable(libraryPathPropertyName, null);
			if (environmentVariable != null)
			{
				stringBuilder.Append(environmentVariable).Append(Path.PathSeparator);
			}
			if (builder.StartInfo.EnvironmentVariables.ContainsKey(libraryPathPropertyName))
			{
				stringBuilder.Append(builder.StartInfo.EnvironmentVariables[libraryPathPropertyName]).Append(Path.PathSeparator);
			}
			string fullPath = Path.GetFullPath(binaryLocation);
			if (Platform.CurrentPlatform.IsPlatformType(PlatformType.Mac) && Platform.CurrentPlatform.MinorVersion > 5)
			{
				stringBuilder.Append(Path.PathSeparator);
			}
			else
			{
				stringBuilder.Insert(0, Path.PathSeparator).Insert(0, fullPath);
			}
			if (builder.StartInfo.EnvironmentVariables.ContainsKey(libraryPathPropertyName))
			{
				builder.StartInfo.EnvironmentVariables[libraryPathPropertyName] = stringBuilder.ToString();
			}
			else
			{
				builder.StartInfo.EnvironmentVariables.Add(libraryPathPropertyName, stringBuilder.ToString());
			}
		}

		[SecurityPermission(SecurityAction.Demand)]
		private static string LocateFirefoxBinaryFromPlatform()
		{
			string empty = string.Empty;
			if (Platform.CurrentPlatform.IsPlatformType(PlatformType.Windows))
			{
				string name = "SOFTWARE\\Mozilla\\Mozilla Firefox";
				RegistryKey registryKey = Registry.LocalMachine.OpenSubKey(name);
				if (registryKey == null)
				{
					registryKey = Registry.CurrentUser.OpenSubKey(name);
				}
				empty = ((registryKey == null) ? GetExecutablePathUsingDefaultInstallLocations(new string[2]
				{
					Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), "Mozilla Firefox"),
					Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles) + " (x86)", "Mozilla Firefox")
				}, "Firefox.exe") : GetExecutablePathUsingRegistry(registryKey));
			}
			else
			{
				empty = GetExecutablePathUsingDefaultInstallLocations(new string[2]
				{
					"/Applications/Firefox.app/Contents/MacOS",
					string.Format(CultureInfo.InvariantCulture, "/Users/{0}/Applications/Firefox.app/Contents/MacOS", new object[1] { Environment.UserName })
				}, "firefox-bin");
				if (string.IsNullOrEmpty(empty))
				{
					using Process process = new Process();
					process.StartInfo.FileName = "which";
					process.StartInfo.Arguments = "firefox";
					process.StartInfo.CreateNoWindow = true;
					process.StartInfo.RedirectStandardOutput = true;
					process.StartInfo.UseShellExecute = false;
					process.Start();
					process.WaitForExit();
					empty = process.StandardOutput.ReadToEnd().Trim();
				}
			}
			if (empty != null && File.Exists(empty))
			{
				return empty;
			}
			return FindBinary(new string[2] { "firefox3", "firefox" });
		}

		private static string GetExecutablePathUsingRegistry(RegistryKey mozillaKey)
		{
			string text = (string)mozillaKey.GetValue("CurrentVersion");
			if (string.IsNullOrEmpty(text))
			{
				throw new WebDriverException("Unable to determine the current version of FireFox using the registry, please make sure you have installed FireFox correctly");
			}
			string obj = (string)(mozillaKey.OpenSubKey(string.Format(CultureInfo.InvariantCulture, "{0}\\Main", new object[1] { text })) ?? throw new WebDriverException("Unable to determine the current version of FireFox using the registry, please make sure you have installed FireFox correctly")).GetValue("PathToExe");
			if (!File.Exists(obj))
			{
				throw new WebDriverException("FireFox executable listed in the registry does not exist, please make sure you have installed FireFox correctly");
			}
			return obj;
		}

		private static string GetExecutablePathUsingDefaultInstallLocations(string[] defaultInstallLocations, string exeName)
		{
			for (int i = 0; i < defaultInstallLocations.Length; i++)
			{
				string text = Path.Combine(defaultInstallLocations[i], exeName);
				if (File.Exists(text))
				{
					return text;
				}
			}
			return null;
		}

		private static string GetEnvironmentVariable(string name, string defaultValue)
		{
			string text = Environment.GetEnvironmentVariable(name);
			if (string.IsNullOrEmpty(text))
			{
				text = defaultValue;
			}
			return text;
		}

		private static string GetLibraryPathPropertyName()
		{
			string result = "LD_LIBRARY_PATH";
			if (Platform.CurrentPlatform.IsPlatformType(PlatformType.Windows))
			{
				result = "PATH";
			}
			else if (Platform.CurrentPlatform.IsPlatformType(PlatformType.Mac))
			{
				result = "DYLD_LIBRARY_PATH";
			}
			return result;
		}

		private static string FindBinary(string[] binaryNames)
		{
			for (int i = 0; i < binaryNames.Length; i++)
			{
				string text = binaryNames[i];
				if (Platform.CurrentPlatform.IsPlatformType(PlatformType.Windows))
				{
					text += ".exe";
				}
				string text2 = FileUtilities.FindFile(text);
				if (!string.IsNullOrEmpty(text2))
				{
					return Path.Combine(text2, text);
				}
			}
			return null;
		}
	}
	internal interface ILock : IDisposable
	{
		void LockObject(TimeSpan timeout);

		void UnlockObject();
	}
	internal class IniFileReader
	{
		private Dictionary<string, Dictionary<string, string>> iniFileStore = new Dictionary<string, Dictionary<string, string>>();

		public ReadOnlyCollection<string> SectionNames => new ReadOnlyCollection<string>(new List<string>(iniFileStore.Keys));

		public IniFileReader(string fileName)
		{
			if (string.IsNullOrEmpty(fileName))
			{
				throw new ArgumentNullException("fileName", "File name must not be null or empty");
			}
			if (!File.Exists(fileName))
			{
				throw new FileNotFoundException("INI file not found", fileName);
			}
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			string text = string.Empty;
			string[] array = File.ReadAllLines(fileName);
			foreach (string text2 in array)
			{
				if (string.IsNullOrEmpty(text2.Trim()) || text2.StartsWith(";", StringComparison.OrdinalIgnoreCase))
				{
					continue;
				}
				if (text2.StartsWith("[", StringComparison.OrdinalIgnoreCase) && text2.EndsWith("]", StringComparison.OrdinalIgnoreCase))
				{
					if (!string.IsNullOrEmpty(text))
					{
						iniFileStore.Add(text, dictionary);
					}
					text = text2.Substring(1, text2.Length - 2).ToUpperInvariant();
					dictionary = new Dictionary<string, string>();
					continue;
				}
				string[] array2 = text2.Split(new char[1] { '=' }, 2);
				string key = array2[0].ToUpperInvariant();
				string value = string.Empty;
				if (array2.Length > 1)
				{
					value = array2[1];
				}
				dictionary.Add(key, value);
			}
			iniFileStore.Add(text, dictionary);
		}

		public string GetValue(string sectionName, string valueName)
		{
			if (string.IsNullOrEmpty(sectionName))
			{
				throw new ArgumentNullException("sectionName", "Section name cannot be null or empty");
			}
			string key = sectionName.ToUpperInvariant();
			if (string.IsNullOrEmpty(valueName))
			{
				throw new ArgumentNullException("valueName", "Value name cannot be null or empty");
			}
			string key2 = valueName.ToUpperInvariant();
			if (!iniFileStore.ContainsKey(key))
			{
				throw new ArgumentException("Section does not exist: " + sectionName, "sectionName");
			}
			Dictionary<string, string> dictionary = iniFileStore[key];
			if (!dictionary.ContainsKey(key2))
			{
				throw new ArgumentException("Value does not exist: " + valueName, "valueName");
			}
			return dictionary[key2];
		}
	}
	internal class SocketLock : ILock, IDisposable
	{
		private static int delayBetweenSocketChecks = 100;

		private int lockPort;

		private Socket lockSocket;

		public SocketLock(int lockPort)
		{
			this.lockPort = lockPort;
			lockSocket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
			PreventSocketInheritance();
		}

		public void LockObject(TimeSpan timeout)
		{
			IPHostEntry hostEntry = Dns.GetHostEntry("localhost");
			IPAddress address = IPAddress.Parse("127.0.0.1");
			IPAddress[] addressList = hostEntry.AddressList;
			foreach (IPAddress iPAddress in addressList)
			{
				if (iPAddress.AddressFamily == AddressFamily.InterNetwork)
				{
					address = iPAddress;
					break;
				}
			}
			IPEndPoint address2 = new IPEndPoint(address, lockPort);
			DateTime dateTime = DateTime.Now.Add(timeout);
			do
			{
				try
				{
					if (IsLockFree(address2))
					{
						return;
					}
					Thread.Sleep(delayBetweenSocketChecks);
				}
				catch (ThreadInterruptedException innerException)
				{
					throw new WebDriverException("the thread was interrupted", innerException);
				}
				catch (IOException innerException2)
				{
					throw new WebDriverException("An unexpected error occurred", innerException2);
				}
			}
			while (DateTime.Now < dateTime);
			throw new WebDriverException(string.Format(CultureInfo.InvariantCulture, "Unable to bind to locking port {0} within {1} milliseconds", new object[2] { lockPort, timeout.TotalMilliseconds }));
		}

		public void UnlockObject()
		{
			try
			{
				lockSocket.Close();
			}
			catch (IOException innerException)
			{
				throw new WebDriverException("An error occured unlocking the object", innerException);
			}
		}

		public void Dispose()
		{
			if (lockSocket != null && lockSocket.Connected)
			{
				lockSocket.Close();
			}
			GC.SuppressFinalize(this);
		}

		private bool IsLockFree(IPEndPoint address)
		{
			try
			{
				lockSocket.Bind(address);
				return true;
			}
			catch (SocketException)
			{
				return false;
			}
		}

		private void PreventSocketInheritance()
		{
			if (Platform.CurrentPlatform.IsPlatformType(PlatformType.Windows))
			{
				NativeMethods.SetHandleInformation(lockSocket.Handle, NativeMethods.HandleInformation.Inherit | NativeMethods.HandleInformation.ProtectFromClose, NativeMethods.HandleInformation.None);
			}
		}
	}
