				desiredCapabilities.SetCapability("ms:inPrivate", true);
			}
			if (!string.IsNullOrEmpty(startPage))
			{
				desiredCapabilities.SetCapability("ms:startPage", startPage);
			}
			if (extensionPaths.Count > 0)
			{
				desiredCapabilities.SetCapability("ms:extensionPaths", extensionPaths);
			}
			foreach (KeyValuePair<string, object> additionalCapability in additionalCapabilities)
			{
				desiredCapabilities.SetCapability(additionalCapability.Key, additionalCapability.Value);
			}
			return desiredCapabilities;
		}
	}
