	public class DriverServiceCommandExecutor : ICommandExecutor, IDisposable
	{
		private DriverService service;

		private HttpCommandExecutor internalExecutor;

		private bool isDisposed;

		public CommandInfoRepository CommandInfoRepository => internalExecutor.CommandInfoRepository;

		public HttpCommandExecutor HttpExecutor => internalExecutor;

		public DriverServiceCommandExecutor(DriverService driverService, TimeSpan commandTimeout)
			: this(driverService, commandTimeout, enableKeepAlive: true)
		{
		}

		public DriverServiceCommandExecutor(DriverService driverService, TimeSpan commandTimeout, bool enableKeepAlive)
		{
			service = driverService;
			internalExecutor = new HttpCommandExecutor(driverService.ServiceUrl, commandTimeout, enableKeepAlive);
		}

		public Response Execute(Command commandToExecute)
		{
			if (commandToExecute == null)
			{
				throw new ArgumentNullException("commandToExecute", "Command to execute cannot be null");
			}
			Response response = null;
			if (commandToExecute.Name == DriverCommand.NewSession)
			{
				service.Start();
			}
			try
			{
				return internalExecutor.Execute(commandToExecute);
			}
			finally
			{
				if (commandToExecute.Name == DriverCommand.Quit)
				{
					Dispose();
				}
			}
		}

		public void Dispose()
		{
			Dispose(disposing: true);
		}

		protected virtual void Dispose(bool disposing)
		{
			if (!isDisposed)
			{
				if (disposing)
				{
					service.Dispose();
				}
				isDisposed = true;
			}
		}
	}
	public class ErrorResponse
	{
		private StackTraceElement[] stackTrace;

		private string message = string.Empty;

		private string className = string.Empty;

		private string screenshot = string.Empty;

		public string Message
		{
			get
			{
				return message;
			}
			set
			{
				message = value;
			}
		}

		public string ClassName
		{
			get
			{
				return className;
			}
			set
			{
				className = value;
			}
		}

		public string Screenshot
		{
			get
			{
				return screenshot;
			}
			set
			{
				screenshot = value;
			}
		}

		public StackTraceElement[] StackTrace
		{
			get
			{
				return stackTrace;
			}
			set
			{
				stackTrace = value;
			}
		}

		public ErrorResponse()
		{
		}

		public ErrorResponse(Dictionary<string, object> responseValue)
		{
			if (responseValue == null)
			{
				return;
			}
			if (responseValue.ContainsKey("message"))
			{
				if (responseValue["message"] != null)
				{
					message = responseValue["message"].ToString();
				}
				else
				{
					message = "The error did not contain a message.";
				}
			}
			if (responseValue.ContainsKey("screen") && responseValue["screen"] != null)
			{
				screenshot = responseValue["screen"].ToString();
			}
			if (responseValue.ContainsKey("class") && responseValue["class"] != null)
			{
				className = responseValue["class"].ToString();
			}
			if (!responseValue.ContainsKey("stackTrace") || !(responseValue["stackTrace"] is object[] array))
			{
				return;
			}
			List<StackTraceElement> list = new List<StackTraceElement>();
			object[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				if (array2[i] is Dictionary<string, object> elementAttributes)
				{
					list.Add(new StackTraceElement(elementAttributes));
				}
			}
			stackTrace = list.ToArray();
		}
	}
