		public event EventHandler<SendingRemoteHttpRequestEventArgs> SendingRemoteHttpRequest;

		public HttpCommandExecutor(Uri addressOfRemoteServer, TimeSpan timeout)
			: this(addressOfRemoteServer, timeout, enableKeepAlive: true)
		{
		}

		public HttpCommandExecutor(Uri addressOfRemoteServer, TimeSpan timeout, bool enableKeepAlive)
		{
			if (addressOfRemoteServer == null)
			{
				throw new ArgumentNullException("addressOfRemoteServer", "You must specify a remote address to connect to");
			}
			if (!addressOfRemoteServer.AbsoluteUri.EndsWith("/", StringComparison.OrdinalIgnoreCase))
			{
				addressOfRemoteServer = new Uri(addressOfRemoteServer.ToString() + "/");
			}
			remoteServerUri = addressOfRemoteServer;
			serverResponseTimeout = timeout;
			this.enableKeepAlive = enableKeepAlive;
			ServicePointManager.Expect100Continue = false;
			ServicePointManager.DefaultConnectionLimit = 2000;
			if (Type.GetType("Mono.Runtime", throwOnError: false, ignoreCase: true) == null)
			{
				HttpWebRequest.DefaultMaximumErrorResponseLength = -1;
			}
		}

		public virtual Response Execute(Command commandToExecute)
		{
			if (commandToExecute == null)
			{
				throw new ArgumentNullException("commandToExecute", "commandToExecute cannot be null");
			}
			CommandInfo commandInfo = commandInfoRepository.GetCommandInfo(commandToExecute.Name);
			HttpRequestInfo requestInfo = new HttpRequestInfo(remoteServerUri, commandToExecute, commandInfo);
			HttpResponseInfo stuff = MakeHttpRequest(requestInfo);
			Response response = CreateResponse(stuff);
			if (commandToExecute.Name == DriverCommand.NewSession && response.IsSpecificationCompliant)
			{
				commandInfoRepository = new W3CWireProtocolCommandInfoRepository();
			}
			return response;
		}

		protected virtual void OnSendingRemoteHttpRequest(SendingRemoteHttpRequestEventArgs eventArgs)
		{
			if (eventArgs == null)
			{
				throw new ArgumentNullException("eventArgs", "eventArgs must not be null");
			}
			if (this.SendingRemoteHttpRequest != null)
			{
				this.SendingRemoteHttpRequest(this, eventArgs);
			}
		}

		private static string GetTextOfWebResponse(HttpWebResponse webResponse)
		{
			StreamReader streamReader = new StreamReader(webResponse.GetResponseStream(), Encoding.UTF8);
			string text = streamReader.ReadToEnd();
			streamReader.Close();
			if (text.IndexOf('\0') >= 0)
			{
				text = text.Substring(0, text.IndexOf('\0'));
			}
			return text;
		}

		private HttpResponseInfo MakeHttpRequest(HttpRequestInfo requestInfo)
		{
			HttpWebRequest httpWebRequest = WebRequest.Create(requestInfo.FullUri) as HttpWebRequest;
			if (!string.IsNullOrEmpty(requestInfo.FullUri.UserInfo) && requestInfo.FullUri.UserInfo.Contains(":"))
			{
				string[] array = remoteServerUri.UserInfo.Split(new char[1] { ':' }, 2);
				httpWebRequest.Credentials = new NetworkCredential(array[0], array[1]);
				httpWebRequest.PreAuthenticate = true;
			}
			string userAgent = string.Format(CultureInfo.InvariantCulture, "selenium/{0} (.net {1})", new object[2]
			{
				ResourceUtilities.AssemblyVersion,
				ResourceUtilities.PlatformFamily
			});
			httpWebRequest.UserAgent = userAgent;
			httpWebRequest.Method = requestInfo.HttpMethod;
			httpWebRequest.Timeout = (int)serverResponseTimeout.TotalMilliseconds;
			httpWebRequest.Accept = "application/json, image/png";
			httpWebRequest.KeepAlive = enableKeepAlive;
			httpWebRequest.Proxy = proxy;
			httpWebRequest.ServicePoint.ConnectionLimit = 2000;
			if (httpWebRequest.Method == "GET")
			{
				httpWebRequest.Headers.Add("Cache-Control", "no-cache");
			}
			SendingRemoteHttpRequestEventArgs sendingRemoteHttpRequestEventArgs = new SendingRemoteHttpRequestEventArgs(httpWebRequest, requestInfo.RequestBody);
			OnSendingRemoteHttpRequest(sendingRemoteHttpRequestEventArgs);
			if (httpWebRequest.Method == "POST")
			{
				string requestBody = sendingRemoteHttpRequestEventArgs.RequestBody;
				byte[] bytes = Encoding.UTF8.GetBytes(requestBody);
				httpWebRequest.ContentType = "application/json;charset=utf-8";
				Stream requestStream = httpWebRequest.GetRequestStream();
				requestStream.Write(bytes, 0, bytes.Length);
				requestStream.Close();
			}
			HttpResponseInfo httpResponseInfo = new HttpResponseInfo();
			HttpWebResponse httpWebResponse = null;
			try
			{
				httpWebResponse = httpWebRequest.GetResponse() as HttpWebResponse;
			}
			catch (WebException ex)
			{
				httpWebResponse = ex.Response as HttpWebResponse;
				if (ex.Status == WebExceptionStatus.Timeout)
				{
					string format = "The HTTP request to the remote WebDriver server for URL {0} timed out after {1} seconds.";
					throw new WebDriverException(string.Format(CultureInfo.InvariantCulture, format, new object[2]
					{
						httpWebRequest.RequestUri.AbsoluteUri,
						serverResponseTimeout.TotalSeconds
					}), ex);
				}
				if (ex.Response == null)
				{
					string format2 = "A exception with a null response was thrown sending an HTTP request to the remote WebDriver server for URL {0}. The status of the exception was {1}, and the message was: {2}";
					throw new WebDriverException(string.Format(CultureInfo.InvariantCulture, format2, new object[3]
					{
						httpWebRequest.RequestUri.AbsoluteUri,
						ex.Status,
						ex.Message
					}), ex);
				}
			}
			if (httpWebResponse == null)
			{
				throw new WebDriverException("No response from server for url " + httpWebRequest.RequestUri.AbsoluteUri);
			}
			httpResponseInfo.Body = GetTextOfWebResponse(httpWebResponse);
			httpResponseInfo.ContentType = httpWebResponse.ContentType;
			httpResponseInfo.StatusCode = httpWebResponse.StatusCode;
			return httpResponseInfo;
		}

		private Response CreateResponse(HttpResponseInfo stuff)
		{
			Response response = new Response();
			string body = stuff.Body;
			if (stuff.ContentType != null && stuff.ContentType.StartsWith("application/json", StringComparison.OrdinalIgnoreCase))
			{
				response = Response.FromJson(body);
			}
			else
			{
				response.Value = body;
			}
			if (commandInfoRepository.SpecificationLevel < 1 && (stuff.StatusCode < HttpStatusCode.OK || stuff.StatusCode >= HttpStatusCode.BadRequest))
			{
				if (stuff.StatusCode >= HttpStatusCode.BadRequest && stuff.StatusCode < HttpStatusCode.InternalServerError)
				{
					response.Status = WebDriverResult.UnhandledError;
				}
				else if (stuff.StatusCode >= HttpStatusCode.InternalServerError)
				{
					if (stuff.StatusCode == HttpStatusCode.NotImplemented)
					{
						response.Status = WebDriverResult.UnknownCommand;
					}
					else if (response.Status == WebDriverResult.Success)
					{
						response.Status = WebDriverResult.UnhandledError;
					}
				}
				else
				{
					response.Status = WebDriverResult.UnhandledError;
				}
			}
			if (response.Value is string)
			{
				response.Value = ((string)response.Value).Replace("\r\n", "\n").Replace("\n", Environment.NewLine);
			}
			return response;
		}

		public void Dispose()
		{
			Dispose(disposing: true);
		}

		protected virtual void Dispose(bool disposing)
		{
			if (!isDisposed)
			{
				isDisposed = true;
			}
		}
	}
