	internal class CharArrayJsonConverter : JsonConverter
	{
		public override bool CanConvert(Type objectType)
		{
			if (objectType != null)
			{
				return objectType.IsAssignableFrom(typeof(char[]));
			}
			return false;
		}

		public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer)
		{
			if (writer == null)
			{
				return;
			}
			writer.WriteStartArray();
			if (value is char[] array)
			{
				char[] array2 = array;
				foreach (char value2 in array2)
				{
					int num = Convert.ToInt32(value2);
					if (num >= 32 && num <= 126)
					{
						writer.WriteValue(value2);
						continue;
					}
					string text = "\\u" + Convert.ToString(num, 16).PadLeft(4, '0');
					writer.WriteRawValue("\"" + text + "\"");
				}
			}
			writer.WriteEndArray();
		}

		public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
		{
			throw new NotImplementedException();
		}
	}
	internal class ResponseValueJsonConverter : JsonConverter
	{
		public override bool CanConvert(Type objectType)
		{
			return true;
		}

		public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
		{
			return ProcessToken(reader);
		}

		public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer)
		{
			serializer?.Serialize(writer, value);
		}

		private object ProcessToken(JsonReader reader)
		{
			object result = null;
			if (reader != null)
			{
				reader.DateParseHandling = DateParseHandling.None;
				if (reader.TokenType == JsonToken.StartObject)
				{
					Dictionary<string, object> dictionary = new Dictionary<string, object>();
					while (reader.Read() && reader.TokenType != JsonToken.EndObject)
					{
						string key = reader.Value.ToString();
						reader.Read();
						dictionary.Add(key, ProcessToken(reader));
					}
					result = dictionary;
				}
				else if (reader.TokenType == JsonToken.StartArray)
				{
					List<object> list = new List<object>();
					while (reader.Read() && reader.TokenType != JsonToken.EndArray)
					{
						list.Add(ProcessToken(reader));
					}
					result = list.ToArray();
				}
				else
				{
					result = reader.Value;
				}
			}
			return result;
		}
	}
