	public class ReadOnlyDesiredCapabilities : ICapabilities, IHasCapabilitiesDictionary
	{
		private readonly Dictionary<string, object> capabilities = new Dictionary<string, object>();

		public string BrowserName
		{
			get
			{
				string result = string.Empty;
				object capability = GetCapability(CapabilityType.BrowserName);
				if (capability != null)
				{
					result = capability.ToString();
				}
				return result;
			}
		}

		public Platform Platform => (GetCapability(CapabilityType.Platform) as Platform) ?? new Platform(PlatformType.Any);

		public string Version
		{
			get
			{
				string result = string.Empty;
				object capability = GetCapability(CapabilityType.Version);
				if (capability != null)
				{
					result = capability.ToString();
				}
				return result;
			}
		}

		public bool AcceptInsecureCerts
		{
			get
			{
				bool result = false;
				object capability = GetCapability(CapabilityType.AcceptInsecureCertificates);
				if (capability != null)
				{
					result = (bool)capability;
				}
				return result;
			}
		}

		Dictionary<string, object> IHasCapabilitiesDictionary.CapabilitiesDictionary => CapabilitiesDictionary;

		internal Dictionary<string, object> CapabilitiesDictionary => capabilities;

		public object this[string capabilityName]
		{
			get
			{
				if (!capabilities.ContainsKey(capabilityName))
				{
					throw new ArgumentException(string.Format(CultureInfo.InvariantCulture, "The capability {0} is not present in this set of capabilities", new object[1] { capabilityName }));
				}
				return capabilities[capabilityName];
			}
		}

		private ReadOnlyDesiredCapabilities()
		{
		}

		internal ReadOnlyDesiredCapabilities(DesiredCapabilities desiredCapabilities)
		{
			foreach (KeyValuePair<string, object> item in desiredCapabilities.CapabilitiesDictionary)
			{
				capabilities[item.Key] = item.Value;
			}
		}

		public bool HasCapability(string capability)
		{
			return capabilities.ContainsKey(capability);
		}

		public object GetCapability(string capability)
		{
			object obj = null;
			if (capabilities.ContainsKey(capability))
			{
				obj = capabilities[capability];
				string text = obj as string;
				if (capability == CapabilityType.Platform && text != null)
				{
					obj = Platform.FromString(obj.ToString());
				}
			}
			return obj;
		}

		public Dictionary<string, object> ToDictionary()
		{
			return capabilities;
		}

		public override int GetHashCode()
		{
			int num = ((BrowserName != null) ? BrowserName.GetHashCode() : 0);
			num = 31 * num + ((Version != null) ? Version.GetHashCode() : 0);
			return 31 * num + ((Platform != null) ? Platform.GetHashCode() : 0);
		}

		public override string ToString()
		{
			return string.Format(CultureInfo.InvariantCulture, "Capabilities [BrowserName={0}, Platform={1}, Version={2}]", new object[3]
			{
				BrowserName,
				Platform.PlatformType.ToString(),
				Version
			});
		}

		public override bool Equals(object obj)
		{
			if (this == obj)
			{
				return true;
			}
			if (!(obj is DesiredCapabilities desiredCapabilities))
			{
				return false;
			}
			if ((BrowserName != null) ? (BrowserName != desiredCapabilities.BrowserName) : (desiredCapabilities.BrowserName != null))
			{
				return false;
			}
			if (!Platform.IsPlatformType(desiredCapabilities.Platform.PlatformType))
			{
				return false;
			}
			if ((Version != null) ? (Version != desiredCapabilities.Version) : (desiredCapabilities.Version != null))
			{
				return false;
			}
			return true;
		}
	}
