		public ReadOnlyCollection<Cookie> AllCookies => GetAllCookies();

		public RemoteCookieJar(RemoteWebDriver driver)
		{
			this.driver = driver;
		}

		public void AddCookie(Cookie cookie)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary.Add("cookie", cookie);
			driver.InternalExecute(DriverCommand.AddCookie, dictionary);
		}

		public void DeleteCookieNamed(string name)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary.Add("name", name);
			driver.InternalExecute(DriverCommand.DeleteCookie, dictionary);
		}

		public void DeleteCookie(Cookie cookie)
		{
			if (cookie != null)
			{
				DeleteCookieNamed(cookie.Name);
			}
		}

		public void DeleteAllCookies()
		{
			driver.InternalExecute(DriverCommand.DeleteAllCookies, null);
		}

		public Cookie GetCookieNamed(string name)
		{
			Cookie result = null;
			if (name != null)
			{
				foreach (Cookie allCookie in AllCookies)
				{
					if (name.Equals(allCookie.Name))
					{
						result = allCookie;
						break;
					}
				}
			}
			return result;
		}

		private ReadOnlyCollection<Cookie> GetAllCookies()
		{
			List<Cookie> list = new List<Cookie>();
			object value = driver.InternalExecute(DriverCommand.GetAllCookies, new Dictionary<string, object>()).Value;
			try
			{
				if (value is object[] array)
				{
					object[] array2 = array;
					foreach (object obj in array2)
					{
						Dictionary<string, object> rawCookie = obj as Dictionary<string, object>;
						if (obj != null)
						{
							list.Add(Cookie.FromDictionary(rawCookie));
						}
					}
				}
				return new ReadOnlyCollection<Cookie>(list);
			}
			catch (Exception innerException)
			{
				throw new WebDriverException("Unexpected problem getting cookies", innerException);
			}
		}
	}
