	internal class RemoteTargetLocator : ITargetLocator
	{
		private RemoteWebDriver driver;

		public RemoteTargetLocator(RemoteWebDriver driver)
		{
			this.driver = driver;
		}

		public IWebDriver Frame(int frameIndex)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary.Add("id", frameIndex);
			driver.InternalExecute(DriverCommand.SwitchToFrame, dictionary);
			return driver;
		}

		public IWebDriver Frame(string frameName)
		{
			if (frameName == null)
			{
				throw new ArgumentNullException("frameName", "Frame name cannot be null");
			}
			string text = Regex.Replace(frameName, "(['\"\\\\#.:;,!?+<>=~*^$|%&@`{}\\-/\\[\\]\\(\\)])", "\\$1");
			ReadOnlyCollection<IWebElement> readOnlyCollection = driver.FindElements(By.CssSelector("frame[name='" + text + "'],iframe[name='" + text + "']"));
			if (readOnlyCollection.Count == 0)
			{
				readOnlyCollection = driver.FindElements(By.CssSelector("frame#" + text + ",iframe#" + text));
				if (readOnlyCollection.Count == 0)
				{
					throw new NoSuchFrameException("No frame element found with name or id " + frameName);
				}
			}
			return Frame(readOnlyCollection[0]);
		}

		public IWebDriver Frame(IWebElement frameElement)
		{
			if (frameElement == null)
			{
				throw new ArgumentNullException("frameElement", "Frame element cannot be null");
			}
			IWebElementReference webElementReference = frameElement as IWebElementReference;
			if (webElementReference == null && frameElement is IWrapsElement wrapsElement)
			{
				webElementReference = wrapsElement.WrappedElement as IWebElementReference;
			}
			if (webElementReference == null)
			{
				throw new ArgumentException("frameElement cannot be converted to IWebElementReference", "frameElement");
			}
			Dictionary<string, object> dictionary = webElementReference.ToDictionary();
			dictionary.Add("ELEMENT", webElementReference.ElementReferenceId);
			Dictionary<string, object> dictionary2 = new Dictionary<string, object>();
			dictionary2.Add("id", dictionary);
			driver.InternalExecute(DriverCommand.SwitchToFrame, dictionary2);
			return driver;
		}

		public IWebDriver ParentFrame()
		{
			Dictionary<string, object> parameters = new Dictionary<string, object>();
			driver.InternalExecute(DriverCommand.SwitchToParentFrame, parameters);
			return driver;
		}

		public IWebDriver Window(string windowHandleOrName)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			if (driver.IsSpecificationCompliant)
			{
				dictionary.Add("handle", windowHandleOrName);
				try
				{
					driver.InternalExecute(DriverCommand.SwitchToWindow, dictionary);
					return driver;
				}
				catch (NoSuchWindowException)
				{
					string text = null;
					try
					{
						text = driver.CurrentWindowHandle;
					}
					catch (NoSuchWindowException)
					{
					}
					foreach (string windowHandle in driver.WindowHandles)
					{
						Window(windowHandle);
						if (windowHandleOrName == driver.ExecuteScript("return window.name").ToString())
						{
							return driver;
						}
					}
					if (text != null)
					{
						Window(text);
					}
					throw;
				}
			}
			dictionary.Add("name", windowHandleOrName);
			driver.InternalExecute(DriverCommand.SwitchToWindow, dictionary);
			return driver;
		}

		public IWebDriver DefaultContent()
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary.Add("id", null);
			driver.InternalExecute(DriverCommand.SwitchToFrame, dictionary);
			return driver;
		}

		public IWebElement ActiveElement()
		{
			Response response = driver.InternalExecute(DriverCommand.GetActiveElement, null);
			return driver.GetElementFromResponse(response);
		}

		public IAlert Alert()
		{
			driver.InternalExecute(DriverCommand.GetAlertText, null);
			return new RemoteAlert(driver);
		}
	}
	internal class RemoteTimeouts : ITimeouts
	{
		private const string ImplicitTimeoutName = "implicit";

		private const string AsyncScriptTimeoutName = "script";

		private const string PageLoadTimeoutName = "pageLoad";

		private const string LegacyPageLoadTimeoutName = "page load";

		private readonly TimeSpan DefaultImplicitWaitTimeout = TimeSpan.FromSeconds(0.0);

		private readonly TimeSpan DefaultAsyncScriptTimeout = TimeSpan.FromSeconds(30.0);

		private readonly TimeSpan DefaultPageLoadTimeout = TimeSpan.FromSeconds(300.0);

		private RemoteWebDriver driver;

		public TimeSpan ImplicitWait
		{
			get
			{
				return ExecuteGetTimeout("implicit");
			}
			set
			{
				ExecuteSetTimeout("implicit", value);
			}
		}

		public TimeSpan AsynchronousJavaScript
		{
			get
			{
				return ExecuteGetTimeout("script");
			}
			set
			{
				ExecuteSetTimeout("script", value);
			}
		}

		public TimeSpan PageLoad
		{
			get
			{
				string timeoutType = "page load";
				if (driver.IsSpecificationCompliant)
				{
					timeoutType = "pageLoad";
				}
				return ExecuteGetTimeout(timeoutType);
			}
			set
			{
				string timeoutType = "page load";
				if (driver.IsSpecificationCompliant)
				{
					timeoutType = "pageLoad";
				}
				ExecuteSetTimeout(timeoutType, value);
			}
		}

		public RemoteTimeouts(RemoteWebDriver driver)
		{
			this.driver = driver;
		}

		private TimeSpan ExecuteGetTimeout(string timeoutType)
		{
			if (driver.IsSpecificationCompliant)
			{
				Dictionary<string, object> obj = (Dictionary<string, object>)driver.InternalExecute(DriverCommand.GetTimeouts, null).Value;
				if (!obj.ContainsKey(timeoutType))
				{
					throw new WebDriverException("Specified timeout type not defined");
				}
				return TimeSpan.FromMilliseconds(Convert.ToDouble(obj[timeoutType], CultureInfo.InvariantCulture));
			}
			throw new NotImplementedException("Driver instance must comply with the W3C specification to support getting timeout values.");
		}

		private void ExecuteSetTimeout(string timeoutType, TimeSpan timeToWait)
		{
			double num = timeToWait.TotalMilliseconds;
			if (timeToWait == TimeSpan.MinValue)
			{
				if (driver.IsSpecificationCompliant)
				{
					if (timeoutType == "implicit")
					{
						TimeSpan defaultImplicitWaitTimeout = DefaultImplicitWaitTimeout;
						num = defaultImplicitWaitTimeout.TotalMilliseconds;
					}
					else if (timeoutType == "script")
					{
						TimeSpan defaultImplicitWaitTimeout = DefaultAsyncScriptTimeout;
						num = defaultImplicitWaitTimeout.TotalMilliseconds;
					}
					else
					{
						TimeSpan defaultImplicitWaitTimeout = DefaultPageLoadTimeout;
						num = defaultImplicitWaitTimeout.TotalMilliseconds;
					}
				}
				else
				{
					num = -1.0;
				}
			}
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			if (driver.IsSpecificationCompliant)
			{
				dictionary.Add(timeoutType, Convert.ToInt64(num));
			}
			else
			{
				dictionary.Add("type", timeoutType);
				dictionary.Add("ms", num);
			}
			driver.InternalExecute(DriverCommand.SetTimeouts, dictionary);
		}
	}
