		private object ParseJavaScriptReturnValue(object responseValue)
		{
			object obj = null;
			Dictionary<string, object> dictionary = responseValue as Dictionary<string, object>;
			object[] array = responseValue as object[];
			if (dictionary != null)
			{
				if (elementFactory.ContainsElementReference(dictionary))
				{
					return elementFactory.CreateElement(dictionary);
				}
				string[] array2 = new string[dictionary.Keys.Count];
				dictionary.Keys.CopyTo(array2, 0);
				string[] array3 = array2;
				foreach (string key in array3)
				{
					dictionary[key] = ParseJavaScriptReturnValue(dictionary[key]);
				}
				return dictionary;
			}
			if (array != null)
			{
				bool flag = true;
				List<object> list = new List<object>();
				object[] array4 = array;
				foreach (object responseValue2 in array4)
				{
					object obj2 = ParseJavaScriptReturnValue(responseValue2);
					if (!(obj2 is IWebElement))
					{
						flag = false;
					}
					list.Add(obj2);
				}
				if (list.Count > 0 && flag)
				{
					List<IWebElement> list2 = new List<IWebElement>();
					foreach (object item2 in list)
					{
						IWebElement item = item2 as IWebElement;
						list2.Add(item);
					}
					return list2.AsReadOnly();
				}
				return list.AsReadOnly();
			}
			return responseValue;
		}
