	internal class RemoteWindow : IWindow
	{
		private RemoteWebDriver driver;

		public Point Position
		{
			get
			{
				Response response;
				if (driver.IsSpecificationCompliant)
				{
					response = driver.InternalExecute(DriverCommand.GetWindowRect, null);
				}
				else
				{
					Dictionary<string, object> dictionary = new Dictionary<string, object>();
					dictionary.Add("windowHandle", "current");
					response = driver.InternalExecute(DriverCommand.GetWindowPosition, dictionary);
				}
				Dictionary<string, object> obj = (Dictionary<string, object>)response.Value;
				int x = Convert.ToInt32(obj["x"], CultureInfo.InvariantCulture);
				int y = Convert.ToInt32(obj["y"], CultureInfo.InvariantCulture);
				return new Point(x, y);
			}
			set
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				dictionary.Add("x", value.X);
				dictionary.Add("y", value.Y);
				if (driver.IsSpecificationCompliant)
				{
					driver.InternalExecute(DriverCommand.SetWindowRect, dictionary);
					return;
				}
				dictionary.Add("windowHandle", "current");
				driver.InternalExecute(DriverCommand.SetWindowPosition, dictionary);
			}
		}

		public Size Size
		{
			get
			{
				Response response;
				if (driver.IsSpecificationCompliant)
				{
					response = driver.InternalExecute(DriverCommand.GetWindowRect, null);
				}
				else
				{
					Dictionary<string, object> dictionary = new Dictionary<string, object>();
					dictionary.Add("windowHandle", "current");
					response = driver.InternalExecute(DriverCommand.GetWindowSize, dictionary);
				}
				Dictionary<string, object> obj = (Dictionary<string, object>)response.Value;
				return new Size(height: Convert.ToInt32(obj["height"], CultureInfo.InvariantCulture), width: Convert.ToInt32(obj["width"], CultureInfo.InvariantCulture));
			}
			set
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				dictionary.Add("width", value.Width);
				dictionary.Add("height", value.Height);
				if (driver.IsSpecificationCompliant)
				{
					driver.InternalExecute(DriverCommand.SetWindowRect, dictionary);
					return;
				}
				dictionary.Add("windowHandle", "current");
				driver.InternalExecute(DriverCommand.SetWindowSize, dictionary);
			}
		}

		public RemoteWindow(RemoteWebDriver driver)
		{
			this.driver = driver;
		}

		public void Maximize()
		{
			Dictionary<string, object> dictionary = null;
