	public class Response
	{
		private object responseValue;

		private string responseSessionId;

		private WebDriverResult responseStatus;

		private bool isSpecificationCompliant;

		public object Value
		{
			get
			{
				return responseValue;
			}
			set
			{
				responseValue = value;
			}
		}

		public string SessionId
		{
			get
			{
				return responseSessionId;
			}
			set
			{
				responseSessionId = value;
			}
		}

		public WebDriverResult Status
		{
			get
			{
				return responseStatus;
			}
			set
			{
				responseStatus = value;
			}
		}

		public bool IsSpecificationCompliant => isSpecificationCompliant;

		public Response()
		{
		}

		public Response(SessionId sessionId)
		{
			if (sessionId != null)
			{
				responseSessionId = sessionId.ToString();
			}
		}

		private Response(Dictionary<string, object> rawResponse)
		{
			if (rawResponse.ContainsKey("sessionId") && rawResponse["sessionId"] != null)
			{
				responseSessionId = rawResponse["sessionId"].ToString();
			}
			if (rawResponse.ContainsKey("value"))
			{
				responseValue = rawResponse["value"];
			}
			if (rawResponse.ContainsKey("status"))
			{
				responseStatus = (WebDriverResult)Convert.ToInt32(rawResponse["status"], CultureInfo.InvariantCulture);
				return;
			}
			isSpecificationCompliant = true;
			if (!rawResponse.ContainsKey("value") && responseValue == null)
			{
				if (rawResponse.ContainsKey("capabilities"))
				{
					responseValue = rawResponse["capabilities"];
				}
				else
				{
					responseValue = rawResponse;
				}
			}
			if (!(responseValue is Dictionary<string, object> dictionary))
			{
				return;
			}
			if (dictionary.ContainsKey("sessionId"))
			{
				responseSessionId = dictionary["sessionId"].ToString();
				if (dictionary.ContainsKey("capabilities"))
				{
					responseValue = dictionary["capabilities"];
				}
				else
				{
					responseValue = dictionary["value"];
				}
			}
			else if (dictionary.ContainsKey("error"))
			{
				responseStatus = WebDriverError.ResultFromError(dictionary["error"].ToString());
			}
		}

		public static Response FromJson(string value)
		{
			return new Response(JsonConvert.DeserializeObject<Dictionary<string, object>>(value, new JsonConverter[1]
			{
				new ResponseValueJsonConverter()
			}));
		}

		public string ToJson()
		{
			return JsonConvert.SerializeObject(this);
		}

		public override string ToString()
		{
			return string.Format(CultureInfo.InvariantCulture, "({0} {1}: {2})", new object[3] { SessionId, Status, Value });
		}
	}
