	internal static class WebDriverError
	{
		public const string ElementClickIntercepted = "element click intercepted";

		public const string ElementNotSelectable = "element not selectable";

		public const string ElementNotInteractable = "element not interactable";

		public const string ElementNotVisible = "element not visible";

		public const string InsecureCertificate = "insecure certificate";

		public const string InvalidArgument = "invalid argument";

		public const string InvalidCookieDomain = "invalid cookie domain";

		public const string InvalidCoordinates = "invalid coordinates";

		public const string InvalidElementCoordinates = "invalid element coordinates";

		public const string InvalidElementState = "invalid element state";

		public const string InvalidSelector = "invalid selector";

		public const string InvalidSessionId = "invalid session id";

		public const string JavaScriptError = "javascript error";

		public const string MoveTargetOutOfBounds = "move target out of bounds";

		public const string NoSuchAlert = "no such alert";

		public const string NoSuchCookie = "no such cookie";

		public const string NoSuchElement = "no such element";

		public const string NoSuchFrame = "no such frame";

		public const string NoSuchWindow = "no such window";

		public const string ScriptTimeout = "script timeout";

		public const string SessionNotCreated = "session not created";

		public const string StaleElementReference = "stale element reference";

		public const string Timeout = "timeout";

		public const string UnableToSetCookie = "unable to set cookie";

		public const string UnableToCaptureScreen = "unable to capture screen";

		public const string UnexpectedAlertOpen = "unexpected alert open";

		public const string UnknownCommand = "unknown command";

		public const string UnknownError = "unknown error";

		public const string UnknownMethod = "unknown method";

		public const string UnsupportedOperation = "unsupported operation";

		private static Dictionary<string, WebDriverResult> resultMap;

		private static object lockObject = new object();

		public static WebDriverResult ResultFromError(string error)
		{
			lock (lockObject)
			{
				if (resultMap == null)
				{
					InitializeResultMap();
				}
			}
			if (!resultMap.ContainsKey(error))
			{
				error = "unsupported operation";
			}
			return resultMap[error];
		}

		private static void InitializeResultMap()
		{
			resultMap = new Dictionary<string, WebDriverResult>();
			resultMap["element click intercepted"] = WebDriverResult.ElementClickIntercepted;
			resultMap["element not selectable"] = WebDriverResult.ElementNotSelectable;
			resultMap["element not visible"] = WebDriverResult.ElementNotDisplayed;
			resultMap["element not interactable"] = WebDriverResult.ElementNotInteractable;
			resultMap["insecure certificate"] = WebDriverResult.InsecureCertificate;
			resultMap["invalid argument"] = WebDriverResult.InvalidArgument;
			resultMap["invalid cookie domain"] = WebDriverResult.InvalidCookieDomain;
			resultMap["invalid coordinates"] = WebDriverResult.InvalidElementCoordinates;
			resultMap["invalid element coordinates"] = WebDriverResult.InvalidElementCoordinates;
			resultMap["invalid element state"] = WebDriverResult.InvalidElementState;
			resultMap["invalid selector"] = WebDriverResult.InvalidSelector;
			resultMap["invalid session id"] = WebDriverResult.NoSuchDriver;
			resultMap["javascript error"] = WebDriverResult.UnexpectedJavaScriptError;
			resultMap["move target out of bounds"] = WebDriverResult.MoveTargetOutOfBounds;
			resultMap["no such alert"] = WebDriverResult.NoAlertPresent;
			resultMap["no such cookie"] = WebDriverResult.NoSuchCookie;
			resultMap["no such element"] = WebDriverResult.NoSuchElement;
			resultMap["no such frame"] = WebDriverResult.NoSuchFrame;
			resultMap["no such window"] = WebDriverResult.NoSuchWindow;
			resultMap["script timeout"] = WebDriverResult.AsyncScriptTimeout;
			resultMap["session not created"] = WebDriverResult.SessionNotCreated;
			resultMap["stale element reference"] = WebDriverResult.ObsoleteElement;
			resultMap["timeout"] = WebDriverResult.Timeout;
			resultMap["unable to set cookie"] = WebDriverResult.UnableToSetCookie;
			resultMap["unable to capture screen"] = WebDriverResult.UnableToCaptureScreen;
			resultMap["unexpected alert open"] = WebDriverResult.UnexpectedAlertOpen;
			resultMap["unknown command"] = WebDriverResult.UnknownCommand;
			resultMap["unknown error"] = WebDriverResult.UnhandledError;
			resultMap["unknown method"] = WebDriverResult.UnknownCommand;
			resultMap["unsupported operation"] = WebDriverResult.UnhandledError;
		}
	}
