namespace OpenQA.Selenium.Chrome
{
	public class ChromeDriver : RemoteWebDriver
	{
		public static readonly bool AcceptUntrustedCertificates = true;

		private const string GetNetworkConditionsCommand = "getNetworkConditions";

		private const string SetNetworkConditionsCommand = "setNetworkConditions";

		private const string DeleteNetworkConditionsCommand = "deleteNetworkConditions";

		private const string SendChromeCommand = "sendChromeCommand";

		private const string SendChromeCommandWithResult = "sendChromeCommandWithResult";

		public override IFileDetector FileDetector
		{
			get
			{
				return base.FileDetector;
			}
			set
			{
			}
		}

		public ChromeNetworkConditions NetworkConditions
		{
			get
			{
				return ChromeNetworkConditions.FromDictionary(Execute("getNetworkConditions", null).Value as Dictionary<string, object>);
			}
			set
			{
				if (value == null)
				{
					throw new ArgumentNullException("value", "value must not be null");
				}
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				dictionary["network_conditions"] = value.ToDictionary();
				Execute("setNetworkConditions", dictionary);
			}
		}

		public ChromeDriver()
			: this(new ChromeOptions())
		{
		}

		public ChromeDriver(ChromeOptions options)
			: this(ChromeDriverService.CreateDefaultService(), options, RemoteWebDriver.DefaultCommandTimeout)
		{
		}

		public ChromeDriver(ChromeDriverService service)
			: this(service, new ChromeOptions())
		{
		}

		public ChromeDriver(string chromeDriverDirectory)
			: this(chromeDriverDirectory, new ChromeOptions())
		{
		}

		public ChromeDriver(string chromeDriverDirectory, ChromeOptions options)
			: this(chromeDriverDirectory, options, RemoteWebDriver.DefaultCommandTimeout)
		{
		}

		public ChromeDriver(string chromeDriverDirectory, ChromeOptions options, TimeSpan commandTimeout)
			: this(ChromeDriverService.CreateDefaultService(chromeDriverDirectory), options, commandTimeout)
		{
		}

		public ChromeDriver(ChromeDriverService service, ChromeOptions options)
			: this(service, options, RemoteWebDriver.DefaultCommandTimeout)
		{
		}

		public ChromeDriver(ChromeDriverService service, ChromeOptions options, TimeSpan commandTimeout)
			: base(new DriverServiceCommandExecutor(service, commandTimeout), ConvertOptionsToCapabilities(options))
		{
			AddCustomChromeCommand("getNetworkConditions", "GET", "/session/{sessionId}/chromium/network_conditions");
			AddCustomChromeCommand("setNetworkConditions", "POST", "/session/{sessionId}/chromium/network_conditions");
			AddCustomChromeCommand("deleteNetworkConditions", "DELETE", "/session/{sessionId}/chromium/network_conditions");
			AddCustomChromeCommand("sendChromeCommand", "POST", "/session/{sessionId}/chromium/send_command");
			AddCustomChromeCommand("sendChromeCommandWithResult", "POST", "/session/{sessionId}/chromium/send_command_and_get_result");
		}

		public void ExecuteChromeCommand(string commandName, Dictionary<string, object> commandParameters)
		{
			if (commandName == null)
			{
				throw new ArgumentNullException("commandName", "commandName must not be null");
			}
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary["cmd"] = commandName;
			dictionary["params"] = commandParameters;
			Execute("sendChromeCommand", dictionary);
		}

		public object ExecuteChromeCommandWithResult(string commandName, Dictionary<string, object> commandParameters)
		{
			if (commandName == null)
			{
				throw new ArgumentNullException("commandName", "commandName must not be null");
			}
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary["cmd"] = commandName;
			dictionary["params"] = commandParameters;
			return Execute("sendChromeCommandWithResult", dictionary).Value;
		}

		private static ICapabilities ConvertOptionsToCapabilities(ChromeOptions options)
		{
			if (options == null)
			{
				throw new ArgumentNullException("options", "options must not be null");
			}
			return options.ToCapabilities();
		}

		private void AddCustomChromeCommand(string commandName, string method, string resourcePath)
		{
			CommandInfo commandInfo = new CommandInfo(method, resourcePath);
			base.CommandExecutor.CommandInfoRepository.TryAddCommand(commandName, commandInfo);
		}
	}
	public sealed class ChromeDriverService : DriverService
	{
		private const string DefaultChromeDriverServiceExecutableName = "chromedriver";

		private static readonly Uri ChromeDriverDownloadUrl = new Uri("http://chromedriver.storage.googleapis.com/index.html");

		private string logPath = string.Empty;

		private string urlPathPrefix = string.Empty;

		private string portServerAddress = string.Empty;

		private string whitelistedIpAddresses = string.Empty;

		private int adbPort = -1;

		private bool enableVerboseLogging;

		public string LogPath
		{
			get
			{
				return logPath;
			}
			set
			{
				logPath = value;
			}
		}

		public string UrlPathPrefix
		{
			get
			{
				return urlPathPrefix;
			}
			set
			{
				urlPathPrefix = value;
			}
		}

		public string PortServerAddress
		{
			get
			{
				return portServerAddress;
			}
			set
			{
				portServerAddress = value;
			}
		}

		public int AndroidDebugBridgePort
		{
			get
			{
				return adbPort;
			}
			set
			{
				adbPort = value;
			}
		}

		public bool EnableVerboseLogging
		{
			get
			{
				return enableVerboseLogging;
			}
			set
			{
				enableVerboseLogging = value;
			}
		}

		public string WhitelistedIPAddresses
		{
			get
			{
				return whitelistedIpAddresses;
			}
			set
			{
				whitelistedIpAddresses = value;
			}
		}

		protected override string CommandLineArguments
		{
			get
			{
				StringBuilder stringBuilder = new StringBuilder(base.CommandLineArguments);
				if (adbPort > 0)
				{
					stringBuilder.AppendFormat(CultureInfo.InvariantCulture, " --adb-port={0}", new object[1] { adbPort });
				}
				if (base.SuppressInitialDiagnosticInformation)
				{
					stringBuilder.Append(" --silent");
				}
				if (enableVerboseLogging)
				{
					stringBuilder.Append(" --verbose");
				}
				if (!string.IsNullOrEmpty(logPath))
				{
					stringBuilder.AppendFormat(CultureInfo.InvariantCulture, " --log-path={0}", new object[1] { logPath });
				}
				if (!string.IsNullOrEmpty(urlPathPrefix))
				{
					stringBuilder.AppendFormat(CultureInfo.InvariantCulture, " --url-base={0}", new object[1] { urlPathPrefix });
				}
				if (!string.IsNullOrEmpty(portServerAddress))
				{
					stringBuilder.AppendFormat(CultureInfo.InvariantCulture, " --port-server={0}", new object[1] { portServerAddress });
				}
				if (!string.IsNullOrEmpty(whitelistedIpAddresses))
				{
					stringBuilder.Append(string.Format(CultureInfo.InvariantCulture, " -whitelisted-ips={0}", new object[1] { whitelistedIpAddresses }));
				}
				return stringBuilder.ToString();
			}
		}

		private ChromeDriverService(string executablePath, string executableFileName, int port)
			: base(executablePath, port, executableFileName, ChromeDriverDownloadUrl)
		{
		}

		public static ChromeDriverService CreateDefaultService()
		{
			return CreateDefaultService(DriverService.FindDriverServiceExecutable(ChromeDriverServiceFileName(), ChromeDriverDownloadUrl));
		}

		public static ChromeDriverService CreateDefaultService(string driverPath)
		{
			return CreateDefaultService(driverPath, ChromeDriverServiceFileName());
		}

		public static ChromeDriverService CreateDefaultService(string driverPath, string driverExecutableFileName)
		{
			return new ChromeDriverService(driverPath, driverExecutableFileName, PortUtilities.FindFreePort());
		}

		private static string ChromeDriverServiceFileName()
		{
			string text = "chromedriver";
			switch (Environment.OSVersion.Platform)
			{
			case PlatformID.Win32S:
			case PlatformID.Win32Windows:
			case PlatformID.Win32NT:
			case PlatformID.WinCE:
				text += ".exe";
				break;
			default:
				if (Environment.OSVersion.Platform != (PlatformID)128)
				{
					throw new WebDriverException("Unsupported platform: " + Environment.OSVersion.Platform);
				}
				break;
			case PlatformID.Unix:
			case PlatformID.MacOSX:
				break;
			}
			return text;
		}
	}
